/// 逗号分隔的字段串 → 名字列表
fn split_cols(s: &str) -> Vec<String> {
    s.split(',')
        .map(|x| x.trim())
        .filter(|x| !x.is_empty())
        .map(|x| x.to_string())
        .collect()
}

/// 下拉菜单的「选项 → 写回」：`values` 是 (显示, 写回值)，`apply` 收写回值。
/// 索引页那些「格子 + 小箭头」的列（方法 / 表空间 / 排序规则…）都走这套。
fn pick_menu(
    values: Vec<(String, String)>,
    apply: Rc<dyn Fn(String, &mut App)>,
) -> impl Fn(PopupMenu) -> PopupMenu + 'static {
    move |menu| {
        let mut m = menu;
        for (label, value) in &values {
            let apply = apply.clone();
            let value = value.clone();
            m = m.item(
                PopupMenuItem::new(label.clone())
                    .on_click(move |_, _, cx| apply(value.clone(), cx)),
            );
        }
        m
    }
}

/// mock 档的索引：参考图那屏是一条「int 列 + varchar 列」的唯一索引
/// （`ix_organizations_tenant`：tenant_id + name），这里按 mock 列名换成
/// `ix_<表>_org`（org_id + name），形状一致，一打开「索引」页就有东西可看。
fn mock_design_indexes(table: &str) -> Vec<DesignIndex> {
    let cols = mock_design_cols(table);
    let ty_of = |n: &str| cols.iter().find(|c| c.name == n).map(|c| c.ty.clone());
    let (Some(t_org), Some(t_name)) = (ty_of("org_id"), ty_of("name")) else {
        return Vec::new();
    };
    vec![DesignIndex {
        name: format!("ix_{table}_org"),
        fields: vec![
            IndexField::make("org_id", &t_org),
            IndexField::make("name", &t_name),
        ],
        unique: true,
        ..Default::default()
    }]
}

/// 选项子页的三个值（PG：填充因子 / 表空间 / 表注释；MySQL 出行内 COMMENT='…'）
#[derive(Clone, Debug, PartialEq, Default)]
struct DesignOptions {
    fillfactor: String,
    tablespace: String,
    comment: String,
    /// 「不记录」：PG 的 UNLOGGED 表（不写 WAL，崩溃后不恢复）
    unlogged: bool,
    /// 「所有者」：表属主（PG 出 ALTER TABLE OWNER TO，mock 档仅展示）
    owner: String,
    /// 「继承自」：父表名（PG 出 INHERITS (…)）
    inherit: String,
    /// 「集群」：CLUSTER 依据的索引名
    cluster: String,
}

/// 排除约束（仅 PostgreSQL 生成 DDL）：元素串形如 `room WITH =`，
/// 方法是索引访问方法（gist / spgist / gin …），谓词是不带 WHERE 的条件。
#[derive(Clone, Debug, PartialEq, Default)]
struct DesignExclude {
    name: String,
    elements: String,
    /// 索引访问方法的 SQL 名（btree / gist / …），展示名见 EXCLUDE_METHODS
    method: String,
    predicate: String,
    /// 注释（PG 生成 COMMENT ON CONSTRAINT）
    comment: String,
}

/// 排除约束「索引方法」的 (展示名, SQL 名)：DDL 里 USING 用 SQL 名
pub(crate) const EXCLUDE_METHODS: [(&str, &str); 5] = [
    ("B-Tree", "btree"),
    ("GiST", "gist"),
    ("GIN", "gin"),
    ("BRIN", "brin"),
    ("SP-GiST", "spgist"),
];

/// 排除「元素」浮层的行草稿：参考图七列（元素 / 运算符类别模式 / 运算符类别 /
/// 排序 / Nulls 排序 / 运算符模式 / 运算符）。
#[derive(Clone, Debug, Default, PartialEq)]
struct ExcludeRow {
    on: bool,
    name: String,
    opclass_schema: String,
    opclass: String,
    sort: String,
    nulls: String,
    operator_schema: String,
    operator: String,
}

impl ExcludeRow {
    fn empty(name: &str, on: bool) -> Self {
        Self {
            on,
            name: name.to_string(),
            ..Default::default()
        }
    }
}

/// 把 elements 串拆成行草稿：`room [opclass] WITH =` 一段一行；
/// 与表格列匹配的行 on=true（勾选排前），没匹配上的自由片段放最后。
fn parse_exclude_rows(elements: &str, cols: &[DesignCol]) -> Vec<ExcludeRow> {
    let mut rows: Vec<ExcludeRow> = Vec::new();
    for part in elements.split(',') {
        let part = part.trim();
        if part.is_empty() {
            continue;
        }
        let (left, op) = match part.split_once(" WITH ") {
            Some((l, r)) => (l.trim(), r.trim()),
            None => (part, ""),
        };
        let mut it = left.split_whitespace();
        let name = it.next().unwrap_or_default().to_string();
        let rest: Vec<&str> = it.collect();
        let mut row = ExcludeRow {
            on: true,
            operator: op.to_string(),
            ..Default::default()
        };
        row.name = name;
        if rest.len() >= 2 {
            row.opclass_schema = rest[0].to_string();
            row.opclass = rest[1].to_string();
        } else if rest.len() == 1 {
            row.opclass = rest[0].to_string();
        }
        rows.push(row);
    }
    // 表格里的列：勾选的排前面，没勾的排后面（参考图整列都在，等用户勾）
    for c in cols {
        let name = c.name.trim();
        if name.is_empty() {
            continue;
        }
        let pos = rows.iter().position(|r| r.name == name);
        let mut row = ExcludeRow::empty(name, pos.is_some());
        if let Some(i) = pos {
            row = rows.remove(i);
        }
        rows.push(row);
    }
    rows
}

/// 行草稿序列化回 elements 串：`name [opclass] WITH op`（运算符空缺省 =），
/// 只取勾上的行，顺序即草稿顺序。
fn serialize_exclude_rows(rows: &[ExcludeRow]) -> String {
    rows.iter()
        .filter(|r| r.on && !r.name.trim().is_empty())
        .map(|r| {
            let opclass = r.opclass.trim();
            let op = if r.operator.trim().is_empty() {
                "="
            } else {
                r.operator.trim()
            };
            let schema = r.operator_schema.trim();
            if opclass.is_empty() && schema.is_empty() {
                format!("{} WITH {}", r.name.trim(), op)
            } else if schema.is_empty() {
                format!("{} {} WITH {}", r.name.trim(), opclass, op)
            } else {
                format!(
                    "{} {} OPERATOR ({}) WITH {}",
                    r.name.trim(),
                    opclass,
                    schema,
                    op
                )
            }
        })
        .collect::<Vec<_>>()
        .join(", ")
}

/// 排除「元素」浮层的草稿：行 + 选中行 + 每行七格的常驻输入
#[derive(Clone)]
struct ExcludeElementsEditor {
    /// 正在编辑的排除约束行
    row: usize,
    rows: Vec<ExcludeRow>,
    /// 选中行（↑ ↓ + − 作用在它上面）
    sel: usize,
    /// 每行七格的输入（[元素, 运算符类别模式, 运算符类别, 排序, Nulls 排序,
    /// 运算符模式, 运算符]），随行增删重建
    inputs: Vec<[Option<Entity<InputState>>; 7]>,
}

/// 规则（仅 PostgreSQL）：CREATE RULE "name" AS ON event [WHERE (…) DO …]。
/// 启用默认勾上（参考图种子行）；PG 的规则没有 ENABLE / DISABLE 语法，仅展示。
#[derive(Clone, Debug, PartialEq)]
struct DesignRule {
    name: String,
    event: String,
    qualification: String,
    action: String,
    statement: String,
    enabled: bool,
    comment: String,
}

impl Default for DesignRule {
    fn default() -> Self {
        Self {
            name: String::new(),
            event: String::new(),
            qualification: String::new(),
            action: String::new(),
            statement: String::new(),
            enabled: true,
            comment: String::new(),
        }
    }
}

/// 规则「代替运行」下拉的候选（参考图只有 ALSO / INSTEAD 两项）
const RULE_ACTIONS: [&str; 2] = ["ALSO", "INSTEAD"];

/// 触发器（三方言）：MySQL 按事件拆条、PG 引用函数、SQL Server 语句级内联主体
#[derive(Clone, Debug, PartialEq, Default)]
struct DesignTrigger {
    name: String,
    timing: String,
    events: String,
    for_each: String,
    function: String,
    body: String,
    /// 「更新字段」：UPDATE 事件勾上时的字段清单（PG 出 UPDATE OF …）
    update_fields: String,
    /// 「启用」：PG / MySQL / SQL Server 的触发器可禁用，默认勾上
    enabled: bool,
    /// 「当」：WHEN 条件（可空）
    when: String,
    /// 「参数」
    args: String,
    /// 注释（PG 生成 COMMENT ON TRIGGER）
    comment: String,
}

impl DesignTrigger {
    /// 事件勾选格（插入 / 更新 / 删除 / 截断）的读写
    fn has_event(&self, ev: &str) -> bool {
        self.events
            .split(',')
            .any(|e| e.trim().eq_ignore_ascii_case(ev))
    }

    fn set_event(&mut self, ev: &str, on: bool) {
        let mut list: Vec<String> = self
            .events
            .split(',')
            .map(|e| e.trim().to_uppercase())
            .filter(|e| !e.is_empty())
            .collect();
        let upper = ev.to_uppercase();
        match list.iter().position(|e| *e == upper) {
            Some(i) if !on => {
                list.remove(i);
            }
            None if on => list.push(upper),
            _ => {}
        }
        self.events = list.join(", ");
    }
}

/// 触发器的事件清单（逗号分隔 → 大写列表）
fn design_trigger_events(t: &DesignTrigger) -> Vec<String> {
    t.events
        .split(',')
        .map(|e| e.trim().to_uppercase())
        .filter(|e| !e.is_empty())
        .collect()
}

/// 检查约束子句：`CONSTRAINT name CHECK (expr)`；PG 且勾了「无继承」追加
/// NO INHERIT（继承层级里不向下传递）。
pub(crate) fn design_check_sql(is_pg: bool, ck: &DesignPair) -> Option<String> {
    let name = ck.name.trim();
    let expr = ck.value.trim();
    if name.is_empty() || expr.is_empty() {
        return None;
    }
    let quoted = if name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_') {
        name.to_string()
    } else {
        format!("{name}")
    };
    let no_inherit = if is_pg && ck.no_inherit { " NO INHERIT" } else { "" };
    Some(format!("CONSTRAINT {quoted} CHECK ({expr}){no_inherit}"))
}

/// 唯一键约束子句：`CONSTRAINT name UNIQUE (cols)`（表内约束）。
pub(crate) fn design_unique_sql(is_mysql: bool, uk: &DesignPair) -> Option<String> {
    let name = uk.name.trim();
    let cols = uk.value.trim();
    if name.is_empty() || cols.is_empty() {
        return None;
    }
    let q = |n: &str| {
        if is_mysql {
            format!("`{n}`")
        } else {
            format!("\"{n}\"")
        }
    };
    let list: Vec<String> = cols
        .split(',')
        .map(|c| c.trim())
        .filter(|c| !c.is_empty())
        .map(q)
        .collect();
    if list.is_empty() {
        return None;
    }
    Some(format!("CONSTRAINT {} UNIQUE ({})", q(name), list.join(", ")))
}

/// 排除约束子句：`CONSTRAINT name EXCLUDE USING method (elements) WHERE (predicate)`
/// （表内约束；方法为空时省 USING，谓词为空时省 WHERE）。
/// 行存在就出形状（参考界面口径：新加的空行出 `EXCLUDE USING btree`）——
/// 名字空着不带 CONSTRAINT 前缀、元素空着不带括号；完整性仍由
/// design_excludes_validation 把守，预览不挡。
fn design_exclude_sql(ex: &DesignExclude) -> Option<String> {
    let name = ex.name.trim();
    let elements = ex.elements.trim();
    let method = if ex.method.trim().is_empty() {
        "btree"
    } else {
        ex.method.trim()
    };
    let mut sql = String::new();
    if !name.is_empty() {
        sql.push_str(&format!("CONSTRAINT \"{name}\" "));
    }
    sql.push_str(&format!("EXCLUDE USING {method}"));
    if !elements.is_empty() {
        sql.push_str(&format!(" ({elements})"));
    }
    let predicate = ex.predicate.trim();
    if !predicate.is_empty() {
        sql.push_str(&format!(" WHERE ({predicate})"));
    }
    Some(sql)
}

/// 规则子页的 DDL（仅 PostgreSQL）：`CREATE RULE "name" AS ON event [TO 目标]
/// [WHERE (cond)] DO [ALSO | INSTEAD] stmt | DO NOTHING`。`to` 是限定后的表 /
/// 视图名，传空则不写 TO 段（表页沿用既有口径）。
fn design_rule_sql(rule: &DesignRule, to: &str) -> Option<String> {
    let name = rule.name.trim();
    let event = rule.event.trim().to_uppercase();
    if name.is_empty() || event.is_empty() {
        return None;
    }
    let quoted = format!("\"{name}\"");
    let action = rule.action.trim().to_uppercase();
    let stmt = rule.statement.trim();
    let tail = if action == "NOTHING" || stmt.is_empty() {
        "DO NOTHING".to_string()
    } else if action.is_empty() {
        format!("DO {stmt}")
    } else {
        format!("DO {action} {stmt}")
    };
    let qualification = rule.qualification.trim();
    let where_clause = if qualification.is_empty() {
        String::new()
    } else {
        format!(" WHERE ({qualification})")
    };
    let to_clause = if to.is_empty() {
        String::new()
    } else {
        format!(" TO {to}")
    };
    Some(format!(
        "CREATE RULE {quoted} AS ON {event}{to_clause}{where_clause} {tail};"
    ))
}

/// 视图 / 实体化视图的 DDL 预览：正文为空时直接收尾成 `AS;`
/// （照参考界面：新对象预览 `CREATE … "public"."Untitled"\nAS;`），
/// 否则 `CREATE <keyword> <name> AS <body>;`。
pub fn design_view_sql(keyword: &str, name: &str, body: &str) -> String {
    let body = body.trim();
    if body.is_empty() {
        format!("CREATE {keyword} {name}\nAS;\n")
    } else {
        format!("CREATE {keyword} {name} AS\n{body};\n")
    }
}

/// PostgreSQL 视图的 DDL（「定义」正文 + 「高级」里的检查选项 / 安全屏障）：
/// 安全屏障挂在 `AS` 之前（`WITH (security_barrier=true)`），检查选项挂在查询
/// 之后（`WITH LOCAL / CASCADED CHECK OPTION`）。qual 是 `"public"."v_x"` 形式。
pub fn design_view_sql_pg(
    qual: &str,
    body: &str,
    check_option: &str,
    security_barrier: bool,
) -> String {
    let body = body.trim();
    if body.is_empty() {
        return "-- 在「定义」页写入 SELECT 语句后，这里显示生成的视图定义\n-- CREATE VIEW … AS …\n"
            .to_string();
    }
    let with = if security_barrier {
        " WITH (security_barrier=true)"
    } else {
        ""
    };
    let check = match check_option.trim().to_uppercase().as_str() {
        "LOCAL" => " WITH LOCAL CHECK OPTION",
        "CASCADED" => " WITH CASCADED CHECK OPTION",
        _ => "",
    };
    format!("CREATE VIEW {qual}{with} AS\n{body}{check};\n")
}

/// PG 视图定义之后的附属语句，三个子页各出一条、顺序固定：
/// 注释页 `COMMENT ON VIEW` → 高级页属主 → 规则页 `CREATE RULE … TO`。
/// 截图口径：属主走 `ALTER TABLE 名 OWNER TO "…"`（一行写完，表页那条才是两行式），
/// 语句之间空一行——前面的 `CREATE VIEW …;` 已收尾在一个换行上，故首条只补一个。
fn design_view_pg_tail(qual: &str, owner: &str, comment: &str, rules: &[DesignRule]) -> String {
    let mut stmts: Vec<String> = Vec::new();
    let comment = comment.trim();
    if !comment.is_empty() {
        stmts.push(format!("COMMENT ON VIEW {qual} IS '{comment}';"));
    }
    let owner = owner.trim();
    if !owner.is_empty() {
        stmts.push(format!("ALTER TABLE {qual} OWNER TO \"{owner}\";"));
    }
    stmts.extend(rules.iter().filter_map(|r| design_rule_sql(r, qual)));
    if stmts.is_empty() {
        return String::new();
    }
    let mut out = String::from("\n");
    out.push_str(&stmts.join("\n\n"));
    out
}

/// 函数 / 存储过程的 DDL（按方言分叉）。
///
/// - **PostgreSQL**：`CREATE OR REPLACE FUNCTION "f"(a integer) RETURNS integer
///   AS $fn$ … $fn$ LANGUAGE plpgsql;`
/// - **MySQL**：有返回值是函数（`CREATE FUNCTION … RETURNS t`），没返回值是
///   存储过程（`CREATE PROCEDURE`）；模式写进括号里（`IN` / `OUT` / `INOUT`）。
/// - **SQL Server**：`CREATE PROCEDURE [dbo].[f] @a int AS …`；`OUTPUT` 走
///   `AS` 之后的返回表变量，简化成普通 `OUT` 参数。
///
/// 正文为空时给提示注释（不假装能生成）。
pub fn design_function_sql(
    kind: mock::DbKind,
    schema: &str,
    name: &str,
    params: &[DesignParam],
    ret: &str,
    body: &str,
) -> String {
    let body = body.trim();
    let ret = ret.trim();
    if name.trim().is_empty() {
        return "-- 先在设计器里填上对象名\n".to_string();
    }
    if body.is_empty() {
        return format!(
            "-- 在「函数体」页写入语句后，这里显示生成的 {name} 定义\n"
        );
    }
    let real: Vec<&DesignParam> = params.iter().filter(|p| !design_param_blank(p)).collect();
    match kind {
        mock::DbKind::PostgreSql => {
            let args = real
                .iter()
                .map(|p| {
                    let mode = match p.mode.trim().to_ascii_uppercase().as_str() {
                        "OUT" => "OUT ",
                        "INOUT" => "INOUT ",
                        _ => "",
                    };
                    let ty = if p.ty.trim().is_empty() {
                        "text".to_string()
                    } else {
                        p.ty.trim().to_string()
                    };
                    format!("{mode}{} {ty}", sql_ident_dq(&p.name))
                })
                .collect::<Vec<_>>()
                .join(", ");
            let ret_ty = if ret.is_empty() { "void" } else { ret };
            let qualified = if schema.trim().is_empty() {
                sql_ident_dq(name)
            } else {
                format!("{}.{}", sql_ident_dq(schema), sql_ident_dq(name))
            };
            format!(
                "CREATE OR REPLACE FUNCTION {qualified}({args})\nRETURNS {ret_ty}\nAS $fn$\n{body}\n$fn$\nLANGUAGE plpgsql;\n"
            )
        }
        mock::DbKind::MySql => {
            let args = real
                .iter()
                .map(|p| {
                    let mode = match p.mode.trim().to_ascii_uppercase().as_str() {
                        "OUT" => "OUT ",
                        "INOUT" => "INOUT ",
                        _ => "IN ",
                    };
                    let ty = if p.ty.trim().is_empty() {
                        "TEXT".to_string()
                    } else {
                        p.ty.trim().to_string()
                    };
                    format!("{mode}{} {ty}", sql_ident_bt(&p.name))
                })
                .collect::<Vec<_>>()
                .join(", ");
            let qualified = if schema.trim().is_empty() {
                sql_ident_bt(name)
            } else {
                format!("{}.{}", sql_ident_bt(schema), sql_ident_bt(name))
            };
            if ret.is_empty() {
                format!("CREATE PROCEDURE {qualified}({args})\n{body}\n")
            } else {
                format!(
                    "CREATE FUNCTION {qualified}({args})\nRETURNS {ret}\nDETERMINISTIC\n{body}\n"
                )
            }
        }
        mock::DbKind::SqlServer => {
            let args = real
                .iter()
                .map(|p| {
                    let mode = match p.mode.trim().to_ascii_uppercase().as_str() {
                        "OUT" | "OUTPUT" => "OUTPUT ",
                        _ => "",
                    };
                    let ty = if p.ty.trim().is_empty() {
                        "nvarchar(max)".to_string()
                    } else {
                        p.ty.trim().to_string()
                    };
                    format!("{mode}@{} {ty}", p.name.trim())
                })
                .collect::<Vec<_>>()
                .join(", ");
            let qualified = if schema.trim().is_empty() {
                format!("[{}]", name)
            } else {
                format!("[{}].[{}]", schema, name)
            };
            format!("CREATE PROCEDURE {qualified} {args}\nAS\n{body}\n")
        }
        _ => format!("-- 当前方言（{}）暂不支持函数 / 存储过程定义\n", kind.label()),
    }
}

/// 函数 / 存储过程的参数校验：名字与类型必填（不重名），PG 之外不允许 OUT。
pub fn design_function_validation(
    kind: mock::DbKind,
    params: &[DesignParam],
    ret: &str,
) -> Option<String> {
    let real: Vec<&DesignParam> = params.iter().filter(|p| !design_param_blank(p)).collect();
    for (i, p) in real.iter().enumerate() {
        if p.name.trim().is_empty() {
            return Some(format!("第 {} 个参数的名称不能为空", i + 1));
        }
        if p.ty.trim().is_empty() {
            return Some(format!("参数「{}」的类型不能为空", p.name.trim()));
        }
        if p.mode.trim().eq_ignore_ascii_case("out")
            && !matches!(kind, mock::DbKind::PostgreSql | mock::DbKind::MySql | mock::DbKind::SqlServer)
        {
            return Some(format!("参数「{}」的 OUT 模式不被当前方言支持", p.name.trim()));
        }
        if let Some(j) = real
            .iter()
            .position(|o| o.name.trim().eq_ignore_ascii_case(p.name.trim()))
            && j != i
        {
            return Some(format!("参数名「{}」重复", p.name.trim()));
        }
    }
    // 函数（不是存储过程）必须有返回值
    if !ret.trim().is_empty() && ret.trim().eq_ignore_ascii_case("void") {
        return None;
    }
    None
}

/// 双引号包标识符（PG 口径）。
fn sql_ident_dq(name: &str) -> String {
    format!("\"{}\"", name.trim().replace('"', "\"\""))
}

/// 反引号包标识符（MySQL 口径）。
fn sql_ident_bt(name: &str) -> String {
    format!("`{}`", name.trim().replace('`', "``"))
}

/// 完整列类型：类型自带括号（varchar(32)）就原样，否则把长度拼上去
fn design_full_type(c: &DesignCol) -> String {
    let ty = c.ty.trim();
    if ty.is_empty() {
        return String::new();
    }
    let len = c.len.trim();
    if len.is_empty() || ty.contains('(') {
        return ty.to_string();
    }
    let dec = c.dec.trim();
    if dec.is_empty() {
        format!("{ty}({len})")
    } else {
        format!("{ty}({len},{dec})")
    }
}

/// 长度 / 小数点的显示兜底：模型里没填时按类型给参考值（int8 → 64、bool → 1、
/// float8 → 53 …），只在显示层，不进模型、不影响 DDL。
fn design_len_display(ty: &str, len: &str) -> String {
    if !len.trim().is_empty() {
        return len.to_string();
    }
    let known = match ty.trim() {
        "int8" | "bigint" => "64",
        "int4" | "integer" | "int" => "32",
        "int2" | "smallint" => "16",
        "bool" | "boolean" => "1",
        "float8" | "double precision" => "53",
        "float4" | "real" => "24",
        _ => "",
    };
    known.to_string()
}

/// 索引「字段」浮层（参考界面点「字段」格弹出的小表格）的工作状态：
/// 草稿与选中行，确定才写回模型。
#[derive(Clone)]
struct IndexFieldsEditor {
    /// 正在编辑的索引行
    row: usize,
    fields: Vec<IndexField>,
    /// 选中行（↑ ↓ + − 作用在它上面）
    sel: usize,
}

/// 触发器「更新字段」勾选浮层的草稿：确定才写回 update_fields
#[derive(Clone)]
struct TriggerFieldsEditor {
    /// 正在编辑的触发器行
    row: usize,
    items: Vec<(String, bool)>,
    /// 选中行（↑ ↓ 作用在它上面）
    sel: usize,
}

/// 设计器工作状态，随设计页签存亡（放 [OpenTab] 里，关页签即弃）。
/// baseline_* 是打开 / 保存时的快照：「已修改 / 无变更」拿工作集跟它比，
/// SQL 预览页的「之前」与「更改」脚本也从这批基线出发。
#[derive(Clone)]
pub(crate) struct DesignerState {
    pub(crate) popup: Option<DesignPopup>,
    /// 各子页表头拖动后的列宽：key = (子页, 列序号)
    pub(crate) widths: HashMap<(usize, usize), f32>,
    /// 正在拖动表头分割线：(子页, 列序号, 按下时的 x, 按下时的列宽)
    pub(crate) resize: Option<(usize, usize, f32, f32)>,
    /// 网格与属性面板之间那条缝拖出来的高：key = 缝位（D_SPLIT_*），
    /// 没拖过的子页保持该属性面板的固有高。
    pub(crate) props_h: HashMap<u32, f32>,
    pub(crate) cols: Vec<DesignCol>,
    pub(crate) baseline: Vec<DesignCol>,
    /// 锚点行（属性面板显示它的属性）
    pub(crate) sel: usize,
    /// 当前列（表头淡蓝块 + 当前格跟它走）
    pub(crate) cur: usize,
    /// 子页签 0..=10
    pub(crate) sub: usize,
    /// 字段子页的常驻编辑器，每行 [名称, 长度, 小数点, 注释, 默认, 虚拟类型, 类型]。
    pub(crate) edits: Vec<[Option<Entity<InputState>>; 7]>,
    /// 索引子页的模型与常驻编辑器（每行 [名称, 注释, 填充因子, 待处理列表限制,
    /// 每范围页数, 约束]）。
    pub(crate) indexes: Vec<DesignIndex>,
    pub(crate) index_edits: Vec<[Option<Entity<InputState>>; 6]>,
    pub(crate) index_sel: usize,
    pub(crate) index_cur: usize,
    /// 索引「字段」浮层的草稿（None = 收起）
    pub(crate) idx_editor: Option<IndexFieldsEditor>,
    pub(crate) baseline_indexes: Vec<DesignIndex>,
    /// 外键子页的模型与常驻编辑器（每行 [名称, 引用表, 注释]）。
    pub(crate) fks: Vec<DesignForeignKey>,
    pub(crate) fk_edits: Vec<[Option<Entity<InputState>>; 5]>,
    pub(crate) fk_sel: usize,
    pub(crate) fk_cur: usize,
    pub(crate) baseline_fks: Vec<DesignForeignKey>,
    /// 唯一键子页：常驻一行空白种子行（参考界面口径：空行等着输入，不算数据）。
    pub(crate) uniques: Vec<DesignPair>,
    pub(crate) unique_edits: Vec<[Option<Entity<InputState>>; 3]>,
    pub(crate) unique_sel: usize,
    pub(crate) unique_cur: usize,
    pub(crate) baseline_uniques: Vec<DesignPair>,
    /// 检查子页：常驻一行空白种子行（与外键 / 唯一键同口径）
    pub(crate) checks: Vec<DesignPair>,
    pub(crate) check_edits: Vec<[Option<Entity<InputState>>; 3]>,
    pub(crate) check_sel: usize,
    pub(crate) check_cur: usize,
    pub(crate) baseline_checks: Vec<DesignPair>,
    /// 选项 / 注释子页：填充因子、表空间、表注释
    pub(crate) options: DesignOptions,
    /// [所有者, 表空间, 继承自, 填充因子, 集群, 表注释]
    pub(crate) opt_edits: [Option<Entity<InputState>>; 6],
    /// 排除子页（仅 PostgreSQL）：名称 / 元素 / 方法 / 谓词 / 注释
    pub(crate) excludes: Vec<DesignExclude>,
    pub(crate) exclude_edits: Vec<[Option<Entity<InputState>>; 3]>,
    /// 排除子页当前行 / 当前列（0 名称 … 3 注释）
    pub(crate) exclude_sel: usize,
    pub(crate) exclude_cur: usize,
    /// 规则子页（仅 PostgreSQL）：名称 / 事件 / 条件 / 动作 / 语句
    pub(crate) rules: Vec<DesignRule>,
    pub(crate) rule_edits: Vec<[Option<Entity<InputState>>; 5]>,
    /// 规则子页当前行 / 当前列（0 名称 … 4 注释）
    pub(crate) rule_sel: usize,
    pub(crate) rule_cur: usize,
    /// 触发器子页（三方言）：名称 / 时机 / 事件 / 级 / 函数 / 主体
    pub(crate) triggers: Vec<DesignTrigger>,
    pub(crate) trigger_edits: Vec<[Option<Entity<InputState>>; 3]>,
    /// 触发器子页当前行 / 当前列（0 名称 … 9 注释）
    pub(crate) trig_sel: usize,
    pub(crate) trig_cur: usize,
    /// 「更新字段」勾选浮层草稿（None = 收起）
    pub(crate) trig_fields_editor: Option<TriggerFieldsEditor>,
    /// 排除「元素」浮层的草稿（None = 收起）
    pub(crate) exclude_editor: Option<ExcludeElementsEditor>,
    /// 保存基线：选项 / 排除 / 规则 / 触发器（baseline_checks 在检查子页字段旁，
    /// 与 baseline、baseline_indexes、baseline_fks、baseline_uniques 同口径）。
    pub(crate) baseline_options: DesignOptions,
    pub(crate) baseline_excludes: Vec<DesignExclude>,
    pub(crate) baseline_rules: Vec<DesignRule>,
    pub(crate) baseline_triggers: Vec<DesignTrigger>,
    /// SQL 预览页的子页签：0 = 更改（增量脚本），1 = DDL（之前 / 之后对比）
    pub(crate) sql_sub: usize,
    /// 视图 / 实体化视图 / 函数的「定义」「函数体」正文（SQL 预览由它生成）
    pub(crate) view_body: String,
    /// 打开已有视图时从真库读回的正文：改了没有就比它，空正文不等于「改过」
    pub(crate) baseline_view_body: String,
    pub(crate) view_editor: Option<Entity<EditorState>>,
    /// 视图 / 实体化视图设计器底部「预览」面板（None = 还没点过预览）
    pub(crate) preview: Option<DesignPreview>,
    /// 函数设计器「参数」子页：参数行 + 每行的常驻编辑器
    /// （名称 / 类型 / 模式 / 默认值）
    pub(crate) params: Vec<DesignParam>,
    pub(crate) param_edits: Vec<[Option<Entity<InputState>>; 4]>,
    pub(crate) baseline_params: Vec<DesignParam>,
    /// 函数设计器「参数」子页当前行（点格子换它，删除按钮删它）
    pub(crate) param_sel: usize,
    /// 函数设计器「返回值」子页：返回类型（留空 = 存储过程）
    pub(crate) ret_ty: String,
    pub(crate) baseline_ret_ty: String,
    /// 函数设计器「返回值」子页的常驻编辑器
    pub(crate) ret_edit: Option<Entity<InputState>>,
    /// 实体化视图「刷新选项」：PG 的 CONCURRENTLY
    pub(crate) matview_concurrent: bool,
    pub(crate) baseline_matview_concurrent: bool,
    /// 实体化视图「高级」：创建时立即填充数据（PG 的 WITH DATA）
    pub(crate) matview_with_data: bool,
    pub(crate) baseline_matview_with_data: bool,
    /// 视图「高级」：检查选项（PG 的 `WITH LOCAL / CASCADED CHECK OPTION`，空 = 不写）
    pub(crate) view_check_option: String,
    pub(crate) baseline_view_check_option: String,
    /// 视图「高级」：安全屏障（PG 的 `WITH (security_barrier=true)`）
    pub(crate) view_security_barrier: bool,
    pub(crate) baseline_view_security_barrier: bool,
    /// 视图「注释」子页的多行正文（值仍写回 `options.comment`，与表 / 实体化视图同源）
    pub(crate) view_comment_edit: Option<Entity<TextareaState>>,
    /// 保存后的提示；一动模型就撤（与 Flutter 版 _note 同款）
    pub(crate) note: Option<&'static str>,
    /// 正在从真库反查已有表结构（打开设计页签后异步回填）
    pub(crate) loading: bool,
    /// None = 编辑已有表（名字随目录项走）；Some(name) = 新建表，
    /// name 空 = 未命名（页面上没有表名框，点「保存」时弹独立窗口补）。
    pub(crate) new_name: Option<String>,
}

/// 角色 / 用户设计器工作状态，随页签存亡（放 [OpenTab] 里，关页签即弃）。
/// `baseline` 是打开 / 保存成功时的目录快照：「已修改」与 `ALTER ROLE`
/// 的差异都从它出发。
#[derive(Clone)]
pub(crate) struct RoleState {
    pub(crate) model: role_design::RoleModel,
    pub(crate) baseline: role_design::RoleModel,
    /// 子页签 0..=5（[R_SUBTABS]）
    pub(crate) sub: usize,
    /// 正在从真库反查目录属性
    pub(crate) loading: bool,
    /// 正在后台跑保存脚本（连点两次会发两遍 ALTER ROLE）
    pub(crate) saving: bool,
    /// 新建角色：目录里还没有这一项，保存走 CREATE ROLE
    pub(crate) is_new: bool,
    /// 保存回执的说明行（成功提示或失败原因）
    pub(crate) note: Option<String>,
    /// 常驻编辑器：0 名称 / 1 连接限制 / 2 密码 / 3 确认密码。
    /// 过期日期不占编辑器：这里没有日历控件，它走 [DaroApp::role_open_date_prompt]
    /// 的小窗输入，正文只从模型渲染（子窗口回调拿不到 Window，无法回写编辑器）。
    pub(crate) edits: [Option<Entity<InputState>>; 4],
    /// 确认密码框的原文（不进 [role_design::RoleModel]：它不是目录属性）
    pub(crate) confirm: String,
    /// 注释页的多行正文
    pub(crate) comment_edit: Option<Entity<TextareaState>>,
    /// 「成员属于」页工作集 / 基线（列出的是父角色）
    pub(crate) member_of: Vec<role_design::MemberRow>,
    pub(crate) member_of_base: Vec<role_design::MemberRow>,
    /// 「成员」页工作集 / 基线（列出的是子角色）
    pub(crate) members: Vec<role_design::MemberRow>,
    pub(crate) members_base: Vec<role_design::MemberRow>,
    /// 成员网格里选中的行（参考界面整行铺蓝，只为键盘定位，不参与保存）
    pub(crate) member_sel: Option<usize>,
    /// SQL 预览子页：0 = 更改、1 = DDL（与表 / 视图设计器同一口径）
    pub(crate) sql_sub: usize,
}

/// [RoleState::edits] 的下标。
const R_EDIT_NAME: usize = 0;
const R_EDIT_LIMIT: usize = 1;
const R_EDIT_PW: usize = 2;
const R_EDIT_CONFIRM: usize = 3;

/// 常规页复选框在 [DaroApp::role_set_flag] 里的下标（照截图行序）。
