    /// 表节点展开后的八个分组行，以及已展开组的内容。
    /// 字段组走列缓存，其余七组共用一份 `TableParts`（第一次真正展开非字段组时才查）。
    #[allow(clippy::too_many_arguments)]
    fn table_obj_children(
        &self,
        ix: usize,
        dix: usize,
        six_val: usize,
        cix: usize,
        oix: usize,
        obj: &str,
        obj_key: &str,
        indent: f32,
        q: Option<&str>,
        ink: &TreeInk,
        cx: &mut Context<Self>,
    ) -> Vec<AnyElement> {
        let conn = &self.conns[ix];
        let db = catalog::databases(conn).get(dix).copied().unwrap_or_default();
        let schema = catalog::schemas(conn, db).get(six_val).copied().unwrap_or("");
        let mut rows = Vec::new();
        let mut parts: Option<catalog::TableParts> = None;
        for (gix, (label, _)) in OBJ_GROUPS.iter().enumerate() {
            let group_key = node_key(obj_key, label);
            let open = self.expanded.contains(&group_key);
            rows.push(self.obj_group_row_elem(
                ix,
                dix,
                six_val,
                cix,
                oix,
                gix,
                indent + 12.5,
                open,
                q,
                ink,
                cx,
            ));
            if !open {
                continue;
            }
            if gix == 0 {
                for (colix, col) in catalog::table_columns(conn, db, schema, obj).iter().enumerate()
                {
                    rows.push(self.col_row_elem(
                        ix,
                        dix,
                        six_val,
                        cix,
                        oix,
                        colix,
                        indent + 25.,
                        &col.name,
                        q,
                        ink,
                        cx,
                    ));
                }
            } else {
                let p = parts
                    .get_or_insert_with(|| catalog::table_parts(conn, db, schema, obj));
                for (iix, name) in p.group(gix).iter().enumerate() {
                    rows.push(self.sub_row_elem(
                        ix,
                        dix,
                        six_val,
                        cix,
                        oix,
                        gix,
                        iix,
                        indent + 25.,
                        name,
                        q,
                        ink,
                        cx,
                    ));
                }
            }
        }
        rows
    }

