    /// 树里是否还有任何名字命中（决定根行与「找不到项目」空态）。
    fn any_match(&self, q: &str) -> bool {
        for conn in &self.conns {
            if contains_ci(&conn.name, q) {
                return true;
            }
            if !conn.connected {
                continue;
            }
            for db in catalog::databases(conn) {
                if contains_ci(db, q)
                    || CATEGORIES
                        .iter()
                        .enumerate()
                        .any(|(cix, (label, _))| {
                            catalog::has_category(conn.kind, cix) && contains_ci(label, q)
                        })
                {
                    return true;
                }
                let scopes: Vec<&str> = if catalog::has_schemas(conn.kind) {
                    catalog::schemas(conn, db).to_vec()
                } else {
                    vec![""]
                };
                for schema in scopes {
                    if contains_ci(schema, q) {
                        return true;
                    }
                    for (cix, _) in CATEGORIES.iter().enumerate() {
                        if !catalog::has_category(conn.kind, cix) {
                            continue;
                        }
                        for obj in self.objects_of(conn, db, schema, cix) {
                            if contains_ci(obj, q) {
                                return true;
                            }
                            // 查询没有字段，别拿查询名去查列
                            if cix == 4 {
                                continue;
                            }
                            if catalog::table_columns(conn, db, schema, obj)
                                .iter()
                                .any(|col| contains_ci(&col.name, q))
                            {
                                return true;
                            }
                        }
                    }
                }
            }
        }
        false
    }

    /// 旧单栏渲染路径：分栏改成 [dock::DaroApp::workspace] 之后保留一份参考实现，
    /// 不再接入渲染树（避免和分栏版重复挂页签点击 / 滚动 id）。
    #[allow(dead_code)]
    fn center(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let p = self.pal();
        let bg = to_hsla(p.background);

        let tab = self.active_table();
        let has_tab = tab.is_some();
        // 数据页自带「工具条 / 网格滚动区 / 记录导航条」三段，高度要确定，
        // 外层再套竖向滚动会让 flex_1 拿到无界高度、导航条被顶出窗口
        let self_scrolls = tab.as_ref().is_some_and(|t| !t.query && !t.design);
        let content = if let Some(t) = tab {
            if t.query {
                self.query_page(&t, cx).into_any_element()
            } else if t.design {
                self.designer_page(&t, cx).into_any_element()
            } else {
                self.table_page(&t, cx).into_any_element()
            }
        } else if self.list_view {
            self.object_list(cx).into_any_element()
        } else {
            div()
                .p(px(8.))
                .child(self.object_grid(cx))
                .into_any_element()
        };

        let scroll_id = if has_tab {
            "table-grid-scroll"
        } else if self.list_view {
            "object-list-scroll"
        } else {
            "object-grid-scroll"
        };
        // overflow_y_scrollbar 会把 div 包成 Scrollable，条件书写不了，
        // 只能分两条路各自成型再擦成同一个类型
        let panel: AnyElement = if self_scrolls {
            div().flex_1().min_h_0().child(content).into_any_element()
        } else if has_tab {
            // 页签内容自带各自的右键菜单（查询编辑器 / 设计器 / 网格），这里不套分类菜单
            div()
                .id(scroll_id)
                .flex_1()
                .min_h_0()
                .overflow_y_scrollbar()
                .child(content)
                .into_any_element()
        } else {
            div()
                .id(scroll_id)
                .flex_1()
                .min_h_0()
                .overflow_y_scrollbar()
                // 菜单挂在滚动容器上（不是内容那一层）：行数不满一屏时，下面的
                // 空白也得能右键出分类菜单，和参考界面一致。
                .on_mouse_down(
                    MouseButton::Right,
                    cx.listener(move |this, _, _, _| this.blank_for_context(BlankPane::Objects)),
                )
                .context_menu(node_context_menu(cx.entity().clone()))
                .child(content)
                .into_any_element()
        };

        v_flex()
            .size_full()
            .bg(bg)
            .child(self.tab_bar(cx))
            .when(!has_tab, |s| s.child(self.action_bar(cx)))
            .child(panel)
    }

    /// 页签图标：查询 / 角色 / 设计 / 数据各按对象类型取字形。
    /// 设计页签用铅笔图标（表 / 视图 / 实体化视图三档），函数没有设计档，
    /// 仍用函数图标；角色页签走用户对象图标（`FB_User` 是功能区大图标，不进页签）。
    fn tab_glyph(t: &OpenTab) -> art::Glyph {
        if t.notes.is_some() {
            art::Glyph::Zed(ZedIcon::File)
        } else if t.kv {
            art::Glyph::Zed(ZedIcon::Key)
        } else if t.query {
            art::Glyph::Query
        } else if t.role {
            art::Glyph::User
        } else if t.design && t.cat == 0 {
            art::Glyph::DesignTable
        } else if t.design && t.cat == 1 {
            art::Glyph::DesignView
        } else if t.design && t.cat == 2 {
            art::Glyph::DesignMatView
        } else if t.cat == 0 {
            art::Glyph::Table
        } else if t.cat == 2 {
            art::Glyph::MatView
        } else if t.cat == 3 {
            art::Glyph::Function
        } else {
            art::Glyph::View
        }
    }

    /// 页签条上的文字：查询 =「查询-N」、设计 =「名字 @库 (连接) (设计)」、
    /// 数据 =「名字 @库 (连接)」、角色 =「名字 (连接)」，
    /// 工作集有改动都带前缀「*」。
    /// 新建表未命名时设计页签显示「新建表」，保存命名后换真名。
    fn tab_label(&self, t: &OpenTab) -> String {
        if let Some(n) = &t.notes {
            return format!("发布说明 v{}", n.version);
        }
        if t.kv {
            // 键浏览页挂在库（命名空间）上：「db0 (连接)」
            return format!("{} ({})", t.db, t.conn_name);
        }
        if t.query {
            // 参考界面查询页签：「查询-N」，编辑过未保存前缀「*」
            let star = if t.qstate.as_ref().is_some_and(|q| q.dirty) { "*" } else { "" };
            let seq = t.qstate.as_ref().map(|q| q.seq).unwrap_or(0);
            return format!("{star}查询-{seq}");
        }
        if t.role {
            // 角色是集群级对象，没有库 / 模式坐标，标题只挂连接名。
            let Some(rs) = t.rstate.as_ref() else {
                return String::from("角色");
            };
            let star = if Self::role_dirty(rs) { "*" } else { "" };
            // 改名还没落库时页签保持老名字，和数据页签一样只跟着目录走。
            let name = match (rs.is_new, rs.model.name.is_empty()) {
                (true, true) => "新建角色",
                (true, false) => rs.model.name.as_str(),
                (false, _) => rs.baseline.name.as_str(),
            };
            return format!("{star}{name} ({})", t.conn_name);
        }
        let star = if t.design {
            let dirty = t.dstate.as_ref().is_some_and(design_dirty);
            if dirty { "*" } else { "" }
        } else if t.dirty() {
            // 数据页签工作集有变化（改格 / 增删行未应用）→ 前缀「*」
            "*"
        } else {
            ""
        };
        if t.design {
            match t.dstate.as_ref().and_then(|d| d.new_name.as_deref()) {
                // 新建实体化视图照参考界面显示「无标题 @库.模式（连接）」
                Some("") if t.cat == 2 => {
                    return format!("{star}{}", self.tab_title_named(t, Some("无标题")));
                }
                // 还没命名的新建对象：标题按分类出「新建表 / 新建视图」
                Some("") => {
                    return format!("{star}新建{}", CATEGORIES[t.cat].0);
                }
                Some(name) => {
                    return format!("{star}{} (设计)", self.tab_title_named(t, Some(name)));
                }
                None => {}
            }
        }
        format!("{star}{}", self.tab_title(t))
    }

    /// 中部的页签条：0 号「对象」页常驻，双击树节点追加数据页签。
    /// 活动页签铺 accent 淡底（参考界面实测 #d7cdff，从这里按 accent 派生）。
    /// 旧单栏页签条（分栏版在 [dock::DaroApp::pane_tab_bar]）。
    #[allow(dead_code)]
    fn tab_bar(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let p = self.pal();
        let (bg, border, fg, muted, accent) = (
            to_hsla(p.background),
            to_hsla(p.border),
            to_hsla(p.foreground),
            to_hsla(p.subtle_foreground),
            p.accent,
        );
        // 参考界面取样：页签条 #f0f0f0、活动页签纯白并压住下边线、非活动页签同条底
        let strip = to_hsla(p.chrome);
        let active_bg = to_hsla(p.background);
        let tab_line = to_hsla(p.border);

        let object_tab = h_flex()
            .id("tab-objects")
            .h_full()
            .px(px(12.))
            .items_center()
            .cursor_pointer()
            .when(self.active_tab == 0, |s| s.bg(active_bg))
            .when(self.active_tab > 0, move |s| s.hover(move |s| s.bg(to_hsla(p.hover))))
            .on_click(cx.listener(|this, _, _, cx| {
                this.active_tab = 0;
                cx.notify();
            }))
            .child(div().text_xs().text_color(fg).child("对象"));

        let tabs = self.opened.iter().enumerate().map(|(ix, t)| {
            let glyph = Self::tab_glyph(t);
            let active = self.active_tab == ix + 1;
            let title = self.tab_label(t);
            h_flex()
                .id(rid(&format!("tab/{ix}")))
                .h_full()
                .px(px(10.))
                .gap(px(5.))
                .items_center()
                .cursor_pointer()
                .when(active, move |s| {
                    s.bg(active_bg)
                        .border_l_1()
                        .border_r_1()
                        .border_color(tab_line)
                })
                .when(!active, move |s| s.hover(move |s| s.bg(to_hsla(p.hover))))
                .on_click(cx.listener(move |this, _, _, cx| {
                    // × 的点击会冒泡到页签本体，刚关完一页时下标可能越界，夹回来
                    this.active_tab = (ix + 1).min(this.opened.len());
                    cx.notify();
                }))
                .child(art::icon(glyph, 15., to_hsla(accent)))
                .child(div().text_xs().text_color(fg).child(title))
                .child(
                    h_flex()
                        .id(rid(&format!("tab-close/{ix}")))
                        .size(px(14.))
                        .items_center()
                        .justify_center()
                        .rounded(px(2.))
                        .cursor_pointer()
                        .when(!active, |s| s.opacity(0.))  // 非活动页签默认透明
                        .hover(move |s| {
                            s.opacity(1.).bg(to_hsla(p.hover))
                        })
                        .on_click(cx.listener(move |this, _, _, cx| {
                            this.close_tab(ix);
                            this.active_tab = this.active_tab.min(this.opened.len());
                            cx.notify();
                        }))
                        .child(
                            Icon::new(ZedIcon::Close)
                                .with_size(px(11.))
                                .text_color(muted),
                        ),
                )
        });

        h_flex()
            .h(px(26.))
            .flex_none()
            .bg(bg)
            .border_b_1()
            .border_color(border)
            .child(object_tab)
            .children(tabs)
    }

    // ── 底部「单元格编辑器」抽屉 ─────────────────────────────

    /// 工具条开关：打开时顺带把收起态放开，否则会出现「开着但看不见内容」。
    fn toggle_cell_viewer(&mut self, cx: &mut Context<Self>) {
        self.cell_viewer.open = !self.cell_viewer.open;
        if self.cell_viewer.open {
            self.cell_viewer.collapsed = false;
        }
        cx.notify();
    }

    fn set_cell_viewer_tab(&mut self, tab: usize, cx: &mut Context<Self>) {
        if self.cell_viewer.tab != tab {
            self.cell_viewer.tab = tab;
            cx.notify();
        }
    }

    fn toggle_cell_viewer_collapsed(&mut self, cx: &mut Context<Self>) {
        self.cell_viewer.collapsed = !self.cell_viewer.collapsed;
        cx.notify();
    }

    fn close_cell_viewer(&mut self, cx: &mut Context<Self>) {
        self.cell_viewer.open = false;
        cx.notify();
    }

    /// 数据页当前格的值；行越界 / 空表返回 None（抽屉给「请先选中」提示）。
    fn data_viewer_value(t: &OpenTab) -> Option<String> {
        let (disp, cix) = t.cell;
        if cix >= t.cols.len() {
            return None;
        }
        let order = visible_data_order(t);
        if disp < order.len() {
            t.data.get(order[disp]).and_then(|r| r.get(cix)).cloned()
        } else {
            t.inserted
                .get(disp - order.len())
                .and_then(|r| r.get(cix))
                .cloned()
        }
    }

    /// 查询结果当前格的值；消息 / 摘要页或越界返回 None。
    fn query_viewer_value(q: &QueryState) -> Option<String> {
        let oi = q.pane.checked_sub(2)?;
        let out = q.outcomes.get(oi)?;
        out.result
            .as_ref()?
            .get(out.cell.0)?
            .get(out.cell.1)
            .cloned()
    }

    /// 抽屉整体：页签条 + 内容。`value = None` 表示当前没选中单元格。
    fn cell_viewer_panel(
        &self,
        value: Option<String>,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let p = self.pal();
        let (bg, border, fg, muted) = (
            to_hsla(p.background),
            to_hsla(p.border),
            to_hsla(p.foreground),
            to_hsla(p.muted_foreground),
        );
        let hover = to_hsla(p.hover);
        let accent = to_hsla(p.accent);
        let tab_now = self.cell_viewer.tab;

        let tab = |cx: &mut Context<Self>, ix: usize| -> AnyElement {
            let active = tab_now == ix;
            h_flex()
                .id(rid(&format!("cellviewer/tab/{ix}")))
                .h_full()
                .px(px(12.))
                .items_center()
                .cursor_pointer()
                .when(active, |s| s.border_b_2().border_color(accent))
                .when(!active, move |s| s.hover(move |s| s.bg(hover)))
                .on_click(cx.listener(move |this, _, _, cx| this.set_cell_viewer_tab(ix, cx)))
                .child(
                    div()
                        .text_size(px(12.))
                        .text_color(if active { fg } else { muted })
                        .child(cell_value::VIEW_TABS[ix]),
                )
                .test_support()
                .into_any_element()
        };

        let icon_btn = |id: &'static str, icon: ZedIcon, cx: &mut Context<Self>| -> AnyElement {
            let collapse = id == "cellviewer/collapse";
            div()
                .id(rid(id))
                .size(px(24.))
                .flex_none()
                .flex()
                .items_center()
                .justify_center()
                .rounded(px(2.))
                .cursor_pointer()
                .hover(move |s| s.bg(hover))
                .on_click(cx.listener(move |this, _, _, cx| {
                    if collapse {
                        this.toggle_cell_viewer_collapsed(cx);
                    } else {
                        this.close_cell_viewer(cx);
                    }
                }))
                .child(Icon::new(icon).with_size(px(13.)).text_color(muted))
                .test_support()
                .into_any_element()
        };

        let head = h_flex()
            .id("cellviewer/header")
            .h(px(CV_HEAD_H))
            .flex_none()
            .items_center()
            .bg(bg)
            .border_t_1()
            .border_b_1()
            .border_color(border)
            .children((0..cell_value::VIEW_TABS.len()).map(|ix| tab(cx, ix)))
            .child(div().flex_1())
            .child(icon_btn(
                "cellviewer/collapse",
                if self.cell_viewer.collapsed {
                    ZedIcon::ChevronUp
                } else {
                    ZedIcon::ChevronDown
                },
                cx,
            ))
            .child(div().w(px(4.)))
            .child(icon_btn("cellviewer/close", ZedIcon::Close, cx))
            .child(div().w(px(2.)))
            .test_support();

        v_flex()
            .id("cellviewer")
            .flex_none()
            .child(head)
            .when(!self.cell_viewer.collapsed, |s| {
                s.child(self.cell_viewer_body(value, cx))
            })
            .test_support()
            .into_any_element()
    }

    fn cell_viewer_body(
        &self,
        value: Option<String>,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let p = self.pal();
        let bg = to_hsla(p.background);
        let Some(value) = value else {
            return div()
                .id("cellviewer/body")
                .h(px(CV_H))
                .flex_none()
                .bg(bg)
                .flex()
                .items_center()
                .justify_center()
                .child(
                    div()
                        .text_size(px(12.))
                        .text_color(to_hsla(p.subtle_foreground))
                        .child("请先选中一个单元格"),
                )
                .test_support()
                .into_any_element();
        };
        let body = match self.cell_viewer.tab {
            cell_value::TAB_JSON => self.cell_viewer_json(&value),
            cell_value::TAB_HEX => self.cell_viewer_hex(&value),
            cell_value::TAB_IMAGE => self.cell_viewer_image(&value, cx),
            cell_value::TAB_WEB => self.cell_viewer_mono(&value, "cellviewer/web"),
            _ => self.cell_viewer_mono(&value, "cellviewer/text"),
        };
        div()
            .id("cellviewer/body")
            .h(px(CV_H))
            .flex_none()
            .bg(bg)
            .overflow_hidden()
            .child(body)
            .test_support()
            .into_any_element()
    }

    /// 文本 / 网页两个页签的等宽只读视图（网页页签同样展示源码，不做浏览器渲染）。
    fn cell_viewer_mono(&self, text: &str, id: &'static str) -> AnyElement {
        let p = self.pal();
        div()
            .id(rid(id))
            .size_full()
            .overflow_scroll()
            .p(px(6.))
            .child(
                div()
                    .font_family("Consolas")
                    .text_size(px(12.5))
                    .line_height(px(CV_LINE_H))
                    .whitespace_nowrap()
                    .text_color(to_hsla(p.foreground))
                    .child(text.to_string()),
            )
            .test_support()
            .into_any_element()
    }

    /// JSON 页签：合法 JSON 先缩进，再按记号着色；每行带行号槽。
    fn cell_viewer_json(&self, text: &str) -> AnyElement {
        let p = self.pal();
        let subtle = to_hsla(p.subtle_foreground);
        let gutter = to_hsla(if self.dark { 0x252525 } else { 0xf9f9f9 });
        let (key, string, number, literal, punct) = if self.dark {
            (0x79b8ff, 0x9ecbff, 0x7ee787, 0xd2a8ff, 0xa6a6a6)
        } else {
            (0x0451a5, 0x0a7d32, 0x00a651, 0x8b3fa8, 0x5f5f5f)
        };
        let pretty = cell_value::json_pretty(text);
        let shown = pretty.as_deref().unwrap_or(text);
        let lines: Vec<&str> = shown.split('\n').collect();
        let shown_lines = lines.len().min(CV_MAX_LINES);
        let rows = lines[..shown_lines]
            .iter()
            .enumerate()
            .map(|(ix, line)| {
                h_flex()
                    .flex_none()
                    .h(px(CV_LINE_H))
                    .items_center()
                    .child(
                        div()
                            .w(px(CV_GUTTER_JSON))
                            .h_full()
                            .flex_none()
                            .flex()
                            .items_center()
                            .justify_end()
                            .pr(px(8.))
                            .bg(gutter)
                            .text_size(px(11.5))
                            .text_color(subtle)
                            .child(format!("{}", ix + 1)),
                    )
                    .child(
                        h_flex()
                            .flex_1()
                            .min_w_0()
                            .items_center()
                            .pl(px(8.))
                            .whitespace_nowrap()
                            .children(cell_value::json_spans(line).into_iter().map(
                                |(text, tok)| {
                                    let color = match tok {
                                        cell_value::JsonTok::Key => key,
                                        cell_value::JsonTok::Str => string,
                                        cell_value::JsonTok::Num => number,
                                        cell_value::JsonTok::Literal => literal,
                                        cell_value::JsonTok::Punct => punct,
                                    };
                                    div()
                                        .text_size(px(12.5))
                                        .font_family("Consolas")
                                        .text_color(to_hsla(color))
                                        .child(text)
                                        .into_any_element()
                                },
                            )),
                    )
            });
        let mut lines_el = v_flex().flex_none().children(rows);
        if lines.len() > shown_lines {
            lines_el = lines_el.child(
                div()
                    .p(px(6.))
                    .text_size(px(11.5))
                    .text_color(subtle)
                    .child(format!(
                        "（内容过长，仅显示前 {shown_lines} 行，共 {} 行）",
                        lines.len()
                    )),
            );
        }
        div()
            .id("cellviewer/json")
            .size_full()
            .overflow_scroll()
            .child(lines_el)
            .test_support()
            .into_any_element()
    }

    /// 十六进制页签：偏移槽 + 16 字节一行的十六进制 + ASCII 侧栏。
    fn cell_viewer_hex(&self, text: &str) -> AnyElement {
        let p = self.pal();
        let subtle = to_hsla(p.subtle_foreground);
        let gutter = to_hsla(p.chrome);
        let (bytes_color, ascii_color) = if self.dark {
            (0x86b8ff, 0xb8d4ff)
        } else {
            (0x0000ff, 0x000080)
        };
        let lines = cell_value::hex_lines(text, 16);
        if lines.is_empty() {
            return self.cell_viewer_hint("当前单元格为空");
        }
        let shown = lines.len().min(CV_MAX_LINES);
        let rows = lines[..shown].iter().map(|line| {
            h_flex()
                .flex_none()
                .h(px(CV_LINE_H))
                .items_center()
                .child(
                    div()
                        .w(px(CV_GUTTER_HEX))
                        .h_full()
                        .flex_none()
                        .flex()
                        .items_center()
                        .justify_end()
                        .pr(px(8.))
                        .bg(gutter)
                        .text_size(px(11.5))
                        .text_color(subtle)
                        .child(line.offset.clone()),
                )
                .child(
                    div()
                        .w(px(332.))
                        .flex_none()
                        .pl(px(8.))
                        .text_size(px(12.5))
                        .font_family("Consolas")
                        .text_color(to_hsla(bytes_color))
                        .whitespace_nowrap()
                        .child(line.hex.clone()),
                )
                .child(
                    div()
                        .flex_1()
                        .min_w_0()
                        .pl(px(12.))
                        .text_size(px(12.5))
                        .font_family("Consolas")
                        .text_color(to_hsla(ascii_color))
                        .whitespace_nowrap()
                        .child(line.ascii.clone()),
                )
        });
        let mut el = v_flex().flex_none().children(rows);
        if lines.len() > shown {
            el = el.child(
                div()
                    .p(px(6.))
                    .text_size(px(11.5))
                    .text_color(subtle)
                    .child(format!(
                        "（内容过长，仅显示前 {shown} 行，共 {} 行）",
                        lines.len()
                    )),
            );
        }
        div()
            .id("cellviewer/hex")
            .size_full()
            .overflow_scroll()
            .child(el)
            .test_support()
            .into_any_element()
    }

    /// 图像页签：暗色画布 + 左侧图标栏 + 字节数；能解码 base64 图片就居中显示。
    fn cell_viewer_image(&self, text: &str, cx: &mut Context<Self>) -> AnyElement {
        let decoded = cell_value::decode_base64_image(text);
        let rail = v_flex()
            .w(px(38.))
            .h_full()
            .flex_none()
            .items_center()
            .py(px(8.))
            .gap(px(10.))
            .bg(to_hsla(0x383838))
            .child(art::icon(
                art::Glyph::Asset("OV_Model_Image"),
                16.,
                to_hsla(0x5b9bd5),
            ))
            .when_some(decoded.as_ref(), |s, (kind, bytes)| {
                let (ext, bytes) = (image_ext(*kind), bytes.clone());
                s.child(
                    div()
                        .id("cellviewer/download")
                        .size(px(20.))
                        .flex()
                        .items_center()
                        .justify_center()
                        .rounded(px(2.))
                        .cursor_pointer()
                        .hover(|s| s.bg(to_hsla(0x4a4a4a)))
                        .on_click(cx.listener(move |this, _, _, cx| {
                            let name = format!("cell.{ext}");
                            let Some(path) = rfd::FileDialog::new()
                                .set_file_name(&name)
                                .save_file()
                            else {
                                return;
                            };
                            if let Err(err) = std::fs::write(&path, &bytes) {
                                prompt_dialog::open_notice(
                                    this.dark,
                                    "下载失败",
                                    format!("无法写入 {}：{err}", path.display()),
                                    cx,
                                );
                            }
                        }))
                        .child(art::icon(
                            art::Glyph::Asset("TB_Save_To_Disk"),
                            14.,
                            to_hsla(0x8fb8e0),
                        ))
                        .test_support(),
                )
            });

        let content = v_flex()
            .flex_1()
            .min_w_0()
            .h_full()
            .p(px(10.))
            .gap(px(6.))
            .child(
                div()
                    .text_size(px(12.))
                    .text_color(to_hsla(0x5bc0de))
                    .child(format!("大小: {} 字节", text.len())),
            )
            .when_some(decoded, |s, (kind, bytes)| {
                let image = Arc::new(Image::from_bytes(image_format(kind), bytes));
                s.child(
                    div()
                        .flex_1()
                        .min_h_0()
                        .flex()
                        .items_center()
                        .justify_center()
                        .child(img(image).max_w_full().max_h_full()),
                )
            });

        h_flex()
            .id("cellviewer/image")
            .size_full()
            .bg(to_hsla(0x282828))
            .child(rail)
            .child(content)
            .test_support()
            .into_any_element()
    }

    fn cell_viewer_hint(&self, text: &str) -> AnyElement {
        let p = self.pal();
        div()
            .size_full()
            .flex()
            .items_center()
            .justify_center()
            .child(
                div()
                    .text_size(px(12.))
                    .text_color(to_hsla(p.subtle_foreground))
                    .child(text.to_string()),
            )
            .into_any_element()
    }

    /// 「打开表」的数据页：工具条 + 双行表头的网格 + 底部记录导航条，
    /// 布局与密度照参考界面实测（行高 17.5、表头 40、列宽数值）。
    fn table_page(&self, t: &OpenTab, cx: &mut Context<Self>) -> AnyElement {
        let p = self.pal();
        let (bg, border, fg, muted, subtle, accent, selection) = (
            to_hsla(p.background),
            to_hsla(p.border),
            to_hsla(p.foreground),
            to_hsla(p.muted_foreground),
            to_hsla(p.subtle_foreground),
            p.accent,
            to_hsla(p.selection),
        );
        let hover = to_hsla(p.hover);
        // 数据页配色照参考界面取样：表头白底、当前列两行各铺一档浅蓝、
        // 选中行 #cde4f6 一档、当前格深蓝反白、竖向分隔线比外框浅一档。
        // 表头 / 页码框的「纸底」：亮色主题就是纯白，暗色跟内容底同色
        let paper = to_hsla(p.background);
        // 明色主题往白里调（≈#afd4f1），暗色主题往底色调（深蓝格），否则白字压浅蓝看不见
        let head_cur = to_hsla(blend(accent, p.background, 0.74));
        // 选区覆盖的列头 / 行槽再浅一档（参考界面实机取样 #d9ebf9），
        // 当前列 / 当前行仍用 head_cur 压深
        let head_sel = to_hsla(blend(accent, p.background, 0.86));
        // 类型行照 DBeaver 实测：钢蓝笔画，选中列浅蓝底上也同色；暗色提亮一档
        let ty_fg = to_hsla(if self.dark { 0x8fb0d6 } else { 0x567fab });
        // 当前格：暗色下把蓝压深一档，保证白字有对比
        let cur_cell = to_hsla(if self.dark {
            blend(accent, 0x000000, 0.22)
        } else {
            accent
        });
        // 多选区块：参考参考界面实机取样 #4da0e3，整块实心 + 白字；
        // 暗色压深一档，白字不刺眼
        let sel_cell = to_hsla(if self.dark {
            blend(accent, 0x000000, 0.28)
        } else {
            0x4da0e3
        });
        // 网格分隔线：暗色跟主题的 border（原先照参考界面取样的竖 #595a5a /
        // 横 #a6a6a6 在深色底上亮得刺眼，而且换主题不跟着变）；亮色仍是
        // #dcdcdc，比外框深一档。
        let line = to_hsla(if self.dark { p.border } else { 0xdcdcdc });
        // 待应用状态：改动过的格铺淡琥珀、新增行铺淡绿。参考界面只靠行头
        // * 区分新增；这里把「还没应用的改动」显式标出来（应用后消失）。
        let dirty_cell = to_hsla(if self.dark {
            blend(p.background, 0xffc857, 0.16)
        } else {
            0xfff4d6
        });
        let new_row = to_hsla(if self.dark {
            blend(p.background, 0x3fb950, 0.10)
        } else {
            0xf0faf2
        });

        // 工作集（可编辑）行数 = 筛选后的已有数据 + 新增未应用；排序只作用于
        // data（应用面板多键优先，否则表头单键），新增行永远贴在尾部（参考界面同款）
        // 视图页（cat != 0）：表头只有列名一行（视图没有声明类型），
        // 工具条也没有「导入」（参考界面实测，见 DETAILS.md「数据页 1:1」）
        let is_view = t.cat != 0;
        let order = visible_data_order(t);
        let rows = order.len() + t.inserted.len();
        let dirty = t.dirty();
        // 与基线对齐（改动格上色用）：优先按行身份；demo / 无行标识的表
        // 退回同下标对齐。行数变了（删过行）就没有可比对象，不标改动格。
        let base_of: Vec<Option<usize>> = if t.row_keys.iter().any(|k| !k.is_empty()) {
            let mut map = std::collections::HashMap::with_capacity(t.baseline_row_keys.len());
            for (i, k) in t.baseline_row_keys.iter().enumerate() {
                map.insert(k.as_slice(), i);
            }
            t.row_keys
                .iter()
                .map(|k| map.get(k.as_slice()).copied())
                .collect()
        } else if t.data.len() == t.baseline.len() {
            (0..t.data.len()).map(Some).collect()
        } else {
            vec![None; t.data.len()]
        };
        // 多选区块（超过一格）不铺整行浅蓝：区块自身实心蓝就已经标出范围，
        // 再叠行底色会把矩形边界糊掉
        let multi_sel = t.sel.is_some_and(|s| {
            let (r0, c0, r1, c1) = s.rect();
            r0 != r1 || c0 != c1
        });
        let cols = &t.cols;
        // 列宽按「表头名 / 类型 / 该列最长的值」自适应，再夹到 [56, 320]：
        // 参考界面里 parent_id 这类列不会被截成 parent…，长 id 也放得下。
        // 只采样前 T_COL_W_SCAN 行：远程一页 1000 行，逐行量宽每帧都要
        // 跑满整页；采样后宽度也不随翻页抖动。
        let col_w = grid_auto_col_widths(t);
        // 客户端列序缓存：显示位置 → 原始列下标；列宽按原始下标取缓存值
        let disp_cols = t.col_order();
        let width_of = |cix: usize| t.col_width(cix, col_w[cix]);
        // 显示序宽度只算一次：总宽、横向虚拟化、每个格子的宽度都从这里取，
        // 免得逐格再做列序 → 原始下标的查表
        let disp_w: Vec<f32> = disp_cols.iter().map(|&c| width_of(c)).collect();
        let total_w = T_GUTTER_W + disp_w.iter().sum::<f32>();
        // 横向列虚拟化：宽表每帧只建视口附近的列，两侧用等高占位撑住。
        // 视口宽同样优先用量到的滚动容器宽度（首帧为 0 时用窗口宽兜底）。
        let view_w = {
            let measured = t.scroll.bounds().size.width.as_f32();
            if measured > 0. { measured } else { self.viewport_w }
        };
        let (first_col, last_col, col_pad_l, col_pad_r) = visible_col_window(
            t.scroll.offset().x.as_f32().abs(),
            view_w,
            T_GUTTER_W,
            &disp_w,
        );
        // 表头拖动重排时的插入位指示（2px 竖条，贯穿表头与表体）。
        // slot 是「拿掉被拖列之后」的插入下标，落到当前显示序里就是一条缝：
        // 向右拖过第 slot 列 → 缝在该列右侧，向左拖 → 缝在该列左侧；
        // 还没跨过邻列时贴被拖列的前进侧
        // （落点按当前显示列宽现算，不用起拖快照，免得和列边界错开）
        let drop_x = self
            .col_drag
            .as_ref()
            .filter(|d| same_tab(t, &d.tab) && d.moved)
            .map(|d| {
                let gap = if d.slot > d.from || (d.slot == d.from && d.right) {
                    d.slot + 1
                } else {
                    d.slot
                };
                let before: f32 = disp_w.iter().take(gap).sum();
                T_GUTTER_W + before
            });
        // 远程分页：data 就是当前页。总数统计过就按它算页数；没统计过时
        // 「本页满页」才允许再往后翻（下一页是空页时回执会把总数补出来）。
        // mock：整表在内存里，按「限制记录」的页大小切页。
        let local_size = t.local_page_size();
        let (pages, page, page_start, page_end) = match t.page.as_ref() {
            Some(p) => {
                let pages = match p.total {
                    Some(total) => total.div_ceil(p.page_size).max(1),
                    None => p.page_no + 1 + usize::from(t.data.len() == p.page_size),
                };
                (pages, p.page_no, 0, rows)
            }
            None => {
                let pages = rows.div_ceil(local_size).max(1);
                let page = t.cell.0 / local_size;
                (
                    pages,
                    page,
                    page * local_size,
                    (page * local_size + local_size).min(rows),
                )
            }
        };

        // 行虚拟化：远程一页 1000 行，全量建元素时一次 hover / 拖选就要重建
        // 上万棵子树，是表格操作卡顿的主因。只建视口附近的行，上下用等高
        // 空白撑住滚动条。窗口高度略大于网格高度，多出的部分正好当缓冲。
        let head_h = if is_view {
            T_HEAD_NAME_H
        } else {
            T_HEAD_NAME_H + T_HEAD_TYPE_H
        };
        let local_rows = page_end.saturating_sub(page_start);
        let (first_row, last_row) = visible_row_window(
            t.scroll.offset().y.as_f32().abs(),
            head_h,
            T_ROW_H,
            measured_view_h(&t.scroll, self.viewport_h),
            local_rows,
        );

        // ── 工具条：图标 + 文字（参考界面数据页；企业版项入口全通，点击弹「敬请期待」）──
        let tbtn = |id: &'static str, glyph: art::Glyph, label: &'static str, enabled: bool| {
            h_flex()
                .id(rid(&format!("tp/{id}")))
                .h(px(22.))
                .flex_none()
                .px(px(5.))
                .gap(px(4.))
                .items_center()
                .rounded(px(2.))
                .when(enabled, |s| s.cursor_pointer().hover(move |s| s.bg(hover)))
                .opacity(if enabled { 1. } else { 0.85 })
                .child(art::icon(glyph, 16., muted))
                .child(div().text_size(px(12.)).text_color(fg).child(label))
                .test_support()
        };
        let tsep = || div().w(px(1.)).h(px(15.)).mx(px(6.)).flex_none().bg(border);
        // 企业版工具：入口全通，点击一律弹「敬请期待」
        let tbtn_ent = |id: &'static str, glyph: art::Glyph, label: &'static str| {
            h_flex()
                .id(rid(&format!("tp/{id}")))
                .h(px(22.))
                .flex_none()
                .px(px(5.))
                .gap(px(4.))
                .items_center()
                .rounded(px(2.))
                .cursor_pointer()
                .hover(move |s| s.bg(hover))
                .child(div().flex_none().child(art::icon(glyph, 16., muted)))
                .child(div().text_size(px(12.)).text_color(fg).child(label))
                .test_support()
        };

        let toolbar = h_flex()
            .h(px(T_TOOLBAR_H))
            .flex_none()
            .items_center()
            .px(px(6.))
            .gap(px(2.))
            .bg(to_hsla(p.chrome))
            .border_b_1()
            .border_color(border)
            .child(
                tbtn_ent("profile", art::Glyph::Asset("TB_Table_Profile"), "表配置文件")
                    .on_click(cx.listener(|this, _, _, cx| {
                        ent_coming_soon(this.dark, cx);
                    })),
            )
            .child(tsep())
            .child(tbtn("txn", art::Glyph::Txn, "开始事务", false))
            .child(tsep())
            .child(
                tbtn("edit", art::Glyph::CellEdit, "单元格编辑器", true)
                    .when(self.cell_viewer.open, |s| s.bg(selection))
                    .on_click(cx.listener(|this, _, _, cx| this.toggle_cell_viewer(cx))),
            )
            .child(tsep())
            .child(self.filter_bar_btn(t, cx))
            .child(tbtn("cols", art::Glyph::Columns, "列", false))
            .child(tsep())
            .child(tbtn("hist", art::Glyph::History, "历史", false))
            .child(
                tbtn_ent("ai-fill", art::Glyph::AiTable, "AI 自动填充")
                    .on_click(cx.listener(|this, _, _, cx| {
                        ent_coming_soon(this.dark, cx);
                    })),
            )
            .child(
                tbtn_ent("analysis", art::Glyph::Asset("TB_Schema_Analysis"), "数据分析")
                    .on_click(cx.listener(|this, _, _, cx| {
                        ent_coming_soon(this.dark, cx);
                    })),
            )
            .child(tsep())
            .when(!is_view, |s| {
                s.child(
                    tbtn("import", art::Glyph::ImportWizard, "导入", true).on_click(cx.listener(
                        |this, _, _, cx| this.open_data_import(cx),
                    )),
                )
            })
            .child(
                tbtn("export", art::Glyph::ExportWizard, "导出", true).on_click(cx.listener(
                    |this, _, _, cx| this.open_export_result(cx),
                )),
            )
            .when(!is_view, |s| {
                s.child(
                    tbtn_ent("gen", art::Glyph::Asset("TB_Data_Generation"), "数据生成")
                        .on_click(cx.listener(|this, _, _, cx| {
                            ent_coming_soon(this.dark, cx);
                        })),
                )
                .child(
                    tbtn_ent("mask", art::Glyph::Asset("TB_Data_Masking"), "数据脱敏")
                        .on_click(cx.listener(|this, _, _, cx| {
                            ent_coming_soon(this.dark, cx);
                        })),
                )
            })
            .child(div().flex_1());

        // ── 表头：列名 + 类型同处一格（类型在列名下方），当前列整格浅蓝，
        // 底部 2px 强调条 ──
        let me = cx.entity().clone();
        let header = h_flex()
            .flex_none()
            .relative()
            .on_mouse_move(cx.listener(|this, ev: &MouseMoveEvent, _, cx| {
                this.grid_header_move(ev.position.x.as_f32(), cx);
            }))
            .on_mouse_up(
                MouseButton::Left,
                cx.listener(|this, _, _, cx| this.grid_header_up(cx)),
            )
            .child(
                div()
                    .w(px(T_GUTTER_W))
                    .h_full()
                    .flex_none()
                    .bg(paper)
                    .border_r_1()
                    .border_b_1()
                    .border_color(line),
            )
            .when(col_pad_l > 0., |s| {
                s.child(div().w(px(col_pad_l)).h_full().flex_none())
            })
            .children(
                disp_cols
                    .iter()
                    .enumerate()
                    .skip(first_col)
                    .take(last_col - first_col)
                    .map(|(dc, &cix)| {
                let col = &cols[cix];
                let width = disp_w[dc];
                let hovered = t.head_hover == Some(dc) || t.head_menu == Some(dc);
                let (sorted, asc) = match t.sort {
                    Some((sc, a)) if sc == cix => (true, a),
                    _ => (false, true),
                };
                // 应用筛选后：本列被筛到 → 漏斗；被排序 → 方向箭头（避开表头点击排序）
                let applied = t.filter.applied.as_ref();
                let col_filtered =
                    applied.is_some_and(|a| a.model.crits().iter().any(|c| c.col == cix));
                let col_sort = applied.and_then(|a| {
                    a.sorts
                        .iter()
                        .find(|(sc, _)| *sc == cix)
                        .map(|(_, a)| *a)
                });
                let cur = t.cell.1 == cix;
                // 选区覆盖到的列头一起激活（浅蓝底 + 底部强调条），不只当前列
                let in_sel_cols = t.sel.is_some_and(|s| {
                    let (_, c0, _, c1) = s.rect();
                    dc >= c0 && dc <= c1
                });
                v_flex()
                    .id(rid(&format!("th/{cix}")))
                    .w(px(width))
                    .h_full()
                    .flex_none()
                    .relative()
                    .border_r_1()
                    .border_color(line)
                    .cursor_pointer()
                    // 按下先记「可能的重排」；没拖出阈值就在松开时按点击排序
                    .on_mouse_down(
                        MouseButton::Left,
                        cx.listener(move |this, ev: &MouseDownEvent, _, cx| {
                            this.grid_col_drag_begin(dc, ev.position.x.as_f32(), cx);
                        }),
                    )
                    // 悬停态只记当前格：「…」按钮跟它走
                    .on_hover(cx.listener(move |this, hovered: &bool, _, cx| {
                        let Some(tab) = this.active_data_tab_mut() else {
                            return;
                        };
                        let next = if *hovered { Some(dc) } else { None };
                        // 移入相邻列时 leave 可能晚于 enter 到达：别把新列的悬停清掉
                        if next.is_none() && tab.head_hover != Some(dc) {
                            return;
                        }
                        // 菜单开着时浮层会抢悬停发 leave：按钮收了菜单就跟着没
                        if next.is_none() && tab.head_menu == Some(dc) {
                            return;
                        }
                        if tab.head_hover == next {
                            return;
                        }
                        tab.head_hover = next;
                        cx.notify();
                    }))
                    .child(
                        h_flex()
                            .h(px(T_HEAD_NAME_H))
                            .w_full()
                            .flex_none()
                            .px(px(7.))
                            .gap(px(3.))
                            .items_center()
                            .bg(if cur {
                                head_cur
                            } else if in_sel_cols {
                                head_sel
                            } else {
                                paper
                            })
                            // 视图没有类型行，底边由它自己画；表 / 函数的底边
                            // 交给下面的类型行，两行合成一格，中间不留分隔线
                            .when(is_view, |s| s.border_b_1().border_color(line))
                            .child(
                                div()
                                    .flex_1()
                                    .min_w_0()
                                    .truncate()
                                    .text_size(px(12.))
                                    .font_semibold()
                                    .text_color(fg)
                                    .child(col.name.clone()),
                            )
                            .when(sorted, |s| {
                                s.child(div().flex_none().child(art::icon(
                                    art::Glyph::Asset(if asc {
                                        "OV_ASCENDING"
                                    } else {
                                        "OV_DESCENDING"
                                    }),
                                    11.,
                                    to_hsla(accent),
                                )))
                            })
                            .when(col_sort.is_some() && !sorted, |s| {
                                let a2 = col_sort.unwrap();
                                s.child(div().flex_none().child(art::icon(
                                    art::Glyph::Asset(if a2 {
                                        "OV_ASCENDING"
                                    } else {
                                        "OV_DESCENDING"
                                    }),
                                    11.,
                                    to_hsla(accent),
                                )))
                            })
                            .when(col_filtered, |s| {
                                s.child(div().flex_none().child(art::icon(
                                    art::Glyph::FilterSort,
                                    10.,
                                    to_hsla(accent),
                                )))
                            })
                            // 悬停列的右缘「…」：排序 / 筛选快捷菜单（参考界面同款）
                            .when(hovered, |s| {
                                let me = me.clone();
                                let me_open = me.clone();
                                s.child(
                                    div()
                                        .id(rid(&format!("thmenu/{cix}")))
                                        .flex_none()
                                        .test_support()
                                        .child(
                                    Button::new(rid(&format!("thmenubtn/{cix}")))
                                        .ghost()
                                        .with_size(gpui_kit::component::Size::XSmall)
                                        .flex_none()
                                        .h(px(16.))
                                        .px(px(1.))
                                        .child(
                                            Icon::new(ZedIcon::Ellipsis)
                                                .with_size(px(12.))
                                                .text_color(to_hsla(accent)),
                                        )
                                        .dropdown_menu(move |menu, _window, _cx| {
                                            menu.item(grid_action_item_id(
                                                &me,
                                                "升序排序",
                                                true,
                                                Some(rid(&format!("thmi/{cix}/asc"))),
                                                move |app, cx| {
                                                    app.grid_menu_sort(cix, Some(true), cx)
                                                },
                                            ))
                                            .item(grid_action_item_id(
                                                &me,
                                                "降序排序",
                                                true,
                                                Some(rid(&format!("thmi/{cix}/desc"))),
                                                move |app, cx| {
                                                    app.grid_menu_sort(cix, Some(false), cx)
                                                },
                                            ))
                                            .item(grid_action_item_id(
                                                &me,
                                                "移除所有排序",
                                                true,
                                                Some(rid(&format!("thmi/{cix}/nosort"))),
                                                move |app, cx| {
                                                    app.grid_menu_sort(cix, None, cx)
                                                },
                                            ))
                                            .separator()
                                            .item(grid_action_item_id(
                                                &me,
                                                "添加筛选",
                                                true,
                                                Some(rid(&format!("thmi/{cix}/filter"))),
                                                move |app, cx| {
                                                    if let Some(tab) = app.active_data_tab_mut() {
                                                        tab.filter.open = true;
                                                    }
                                                    app.filter_add_crit(cix, cx);
                                                },
                                            ))
                                        })
                                        .on_open_change({
                                            move |open, _window, cx| {
                                                let next = if *open { Some(dc) } else { None };
                                                me_open.update(cx, |this, cx| {
                                                    let Some(tab) = this.active_data_tab_mut()
                                                    else {
                                                        return;
                                                    };
                                                    if tab.head_menu == next {
                                                        return;
                                                    }
                                                    tab.head_menu = next;
                                                    cx.notify();
                                                });
                                            }
                                        }),
                                        ),
                                )
                            }),
                    )
                    .when(!is_view, |s| {
                        s.child(
                        h_flex()
                            .h(px(T_HEAD_TYPE_H))
                            .w_full()
                            .flex_none()
                            .px(px(7.))
                            .gap(px(3.))
                            .items_center()
                            .bg(if cur {
                                head_cur
                            } else if in_sel_cols {
                                head_sel
                            } else {
                                paper
                            })
                            .border_b_1()
                            .border_color(line)
                            .child(ty_icon(
                                col.numeric,
                                col.ty == "bool",
                                ty_fg,
                            ))
                            .child(
                                div()
                                    .min_w_0()
                                    .truncate()
                                    .text_size(px(10.5))
                                    .text_color(ty_fg)
                                    .child(col.ty.clone()),
                            ),
                        )
                    })
                    .when(cur || in_sel_cols, |s| {
                        // 强调条压住类型行底边，不额外占高度：否则表头比类型行
                        // 底边高 2px，行首槽的底边线会跟着掉下来，看起来错位
                        s.child(
                            div()
                                .absolute()
                                .left_0()
                                .right_0()
                                .bottom_0()
                                .h(px(2.))
                                .bg(to_hsla(accent)),
                        )
                    })
                    // 右缘 5px 是列宽拖拽把手；stop_propagation 防止同一次按下
                    // 又起一个列头重排
                    .child(
                        div()
                            .id(rid(&format!("colresize/{cix}")))
                            .absolute()
                            .right_0()
                            .top_0()
                            .bottom_0()
                            .w(px(5.))
                            .cursor_col_resize()
                            .on_mouse_down(
                                MouseButton::Left,
                                cx.listener(move |this, ev: &MouseDownEvent, _, cx| {
                                    cx.stop_propagation();
                                    this.grid_col_resize_begin(
                                        cix,
                                        ev.position.x.as_f32(),
                                        width,
                                        cx,
                                    );
                                }),
                            )
                            .test_support(),
                    )
                    .test_support()
                })
            )
            .when(col_pad_r > 0., |s| {
                s.child(div().w(px(col_pad_r)).h_full().flex_none())
            });

        let grid = v_flex()
            .w(px(total_w))
            .flex_none()
            .relative()
            .child(header.h(px(head_h)))
            .when(first_row > 0, |s| {
                s.child(div().flex_none().h(px(first_row as f32 * T_ROW_H)))
            })
            .on_mouse_up(
                MouseButton::Left,
                cx.listener(|this, _, _, _| this.grid_drag_end()),
            )
            .children((page_start + first_row..page_start + last_row).map(|disp| {
                let is_new = disp >= order.len();
                let selected = t.cell.0 == disp;
                // 多选时整行不铺色（当前行槽仍标蓝），行底色只服务于单选
                let row_tint = selected && !multi_sel;
                // 选区覆盖到的行，行首槽一起铺浅蓝（参考图里整块行槽同色）
                let in_sel_rows = t.sel.is_some_and(|s| {
                    let (r0, _, r1, _) = s.rect();
                    disp >= r0 && disp <= r1
                });
                h_flex()
                    .flex_none()
                    .h(px(T_ROW_H))
                    // 新增未应用的行铺淡绿（配合行首 *）
                    .when(is_new, |s| s.bg(new_row))
                    // 当前行铺浅蓝（同列头选区），跟 hover 的浅灰分得开：
                    // 两者都用灰时，滚轮移动当前行会和鼠标下的 hover 行糊成「两行灰底」
                    .when(row_tint, |s| s.bg(head_sel))
                    .when(!row_tint, move |s| s.hover(move |s| s.bg(hover)))
                    .border_b_1()
                    .border_color(line)
                    // 行首槽：选中行铺表头同款浅蓝 + 左端 3px 强调条（参考界面没有行号）；
                    // 点它选中整行，当前列保持不变
                    .child(
                        div()
                            .id(rid(&format!("rowgutter/{disp}")))
                            .w(px(T_GUTTER_W))
                            .h_full()
                            .flex_none()
                            .flex()
                            .items_center()
                            .justify_center()
                            .border_r_1()
                            .border_color(line)
                            .when(in_sel_rows && !selected, move |s| s.bg(head_sel))
                            .when(selected, move |s| s.bg(head_cur))
                            .on_mouse_down(
                                MouseButton::Left,
                                cx.listener(move |this, ev: &MouseDownEvent, _, cx| {
                                    this.grid_row_press(disp, ev.modifiers.shift, cx);
                                }),
                            )
                            // 从行首槽按住划出去：整行选区跟着扩
                            .on_mouse_move(cx.listener(
                                move |this, ev: &MouseMoveEvent, _, cx| {
                                    if ev.dragging() {
                                        this.grid_row_hover(disp, cx);
                                    }
                                },
                            ))
                            .child(if selected {
                                div().w(px(3.)).h_full().flex_none().bg(to_hsla(accent)).into_any_element()
                            } else if is_new {
                                // 新增未应用的行：行首一个小「*」，应用后消失
                                div()
                                    .text_size(px(9.))
                                    .text_color(to_hsla(accent))
                                    .child("*")
                                    .into_any_element()
                            } else {
                                div().into_any_element()
                            })
                            .test_support(),
                    )
                    .when(col_pad_l > 0., |s| {
                        s.child(div().w(px(col_pad_l)).h_full().flex_none())
                    })
                    .children(
                        disp_cols
                            .iter()
                            .enumerate()
                            .skip(first_col)
                            .take(last_col - first_col)
                            .map(|(dc, &cix)| {
                        let width = disp_w[dc];
                        let current = t.cell == (disp, cix);
                        let in_sel = t.sel.is_some_and(|s| s.contains(disp, dc));
                        let editing = self
                            .cell_editing
                            .as_ref()
                            .is_some_and(|e| e.at == (disp, cix));
                        let value = if disp < order.len() {
                            t.data
                                .get(order[disp])
                                .and_then(|r| r.get(cix))
                                .cloned()
                                .unwrap_or_default()
                        } else {
                            t.inserted
                                .get(disp - order.len())
                                .and_then(|r| r.get(cix))
                                .cloned()
                                .unwrap_or_default()
                        };
                        // 待新增行的空格继续显示「(N/A)」：编辑其中一格后，
                        // 其余列不该从占位提示突然变成空白
                        let na = is_new && value.is_empty();
                        // 改过的格铺淡琥珀：与基线按行身份对齐后逐格比。
                        // 新增行整体已是淡绿，不再叠琥珀
                        let changed = !is_new
                            && base_of
                                .get(order[disp])
                                .copied()
                                .flatten()
                                .is_some_and(|bi| {
                                    t.baseline.get(bi).and_then(|b| b.get(cix))
                                        != t.data.get(order[disp]).and_then(|r| r.get(cix))
                                });
                        div()
                            .id(rid(&format!("cell/{disp}/{cix}")))
                            .w(px(width))
                            .h_full()
                            .flex_none()
                            .px(px(7.))
                            .flex()
                            .items_center()
                            .border_r_1()
                            .border_color(line)
                            .cursor_pointer()
                            // 按下即起选区；shift 从原锚点扩到这一格
                            .on_mouse_down(
                                MouseButton::Left,
                                cx.listener(move |this, ev: &MouseDownEvent, _, cx| {
                                    if editing {
                                        cx.stop_propagation();
                                        return;
                                    }
                                    this.grid_cell_press(
                                        disp,
                                        dc,
                                        cix,
                                        ev.modifiers.shift,
                                        cx,
                                    );
                                }),
                            )
                            // 右键先把当前格挪过来，外层再按这一格开应用菜单
                            .on_mouse_down(
                                MouseButton::Right,
                                cx.listener(move |this, ev: &MouseDownEvent, _, cx| {
                                    if !editing {
                                        this.grid_cell_right_press(
                                            disp,
                                            dc,
                                            cix,
                                            ev.modifiers.shift,
                                            cx,
                                        );
                                    }
                                }),
                            )
                            // 按住左键划过：拖选
                            .on_mouse_move(cx.listener(
                                move |this, ev: &MouseMoveEvent, _, cx| {
                                    if ev.dragging() {
                                        this.grid_cell_hover(disp, dc, cx);
                                    }
                                },
                            ))
                            .on_click(cx.listener(move |this, _: &ClickEvent, window, cx| {
                                // 双击 = 就地编辑。判定按「同一格 + 系统双击
                                // 时间」：不能直接用平台的 click_count，它按
                                // 屏幕坐标跨控件累计 —— 双击对象列表开表后，
                                // 在网格同一位置单击一下会继承连击数，编辑器
                                // 未双击就被弹出来。
                                if this.is_cell_double_click((disp, cix)) {
                                    this.start_cell_edit(disp, cix, window, cx);
                                }
                                cx.notify();
                            }))
                            .test_support()
                            // 编辑态：白底 + accent 边框包住整格，输入文字与
                            // 单元格文字同字号同留白（Input 内边距为 0）
                            .when(editing, |s| {
                                let input = self
                                    .cell_editing
                                    .as_ref()
                                    .map(|e| e.input.clone())
                                    .unwrap();
                                let me = cx.entity().downgrade();
                                s.bg(bg)
                                    .border_1()
                                    .border_color(to_hsla(accent))
                                    .child(
                                        div()
                                            .flex_1()
                                            .min_w_0()
                                            .context_menu({
                                                let input = input.clone();
                                                let me = me.clone();
                                                move |menu, window, cx| {
                                                    cell_text_menu(menu, window, cx, &input, me.clone())
                                                }
                                            })
                                            .child(
                                                Input::new(&input)
                                                    .h(px(T_ROW_H - 4.))
                                                    .appearance(false)
                                                    .bordered(false)
                                                    // 右键交给外层应用菜单，原生菜单不弹
                                                    .context_menu(|menu, _, _| menu)
                                                    .text_size(px(12.)),
                                            ),
                                    )
                            })
                            .when(!editing, |s| {
                                // 选区块实心中蓝 + 白字，当前格再压成深蓝反白
                                s.when(changed && !in_sel && !current, |s| s.bg(dirty_cell))
                                    .when(in_sel && !current, |s| s.bg(sel_cell))
                                    .when(current, move |s| s.bg(cur_cell))
                                    .child(
                                        div()
                                            .min_w_0()
                                            .max_w_full()
                                            .truncate()
                                            .text_size(px(12.))
                                            .text_color(if in_sel || current {
                                                to_hsla(0xffffff)
                                            } else if na {
                                                subtle
                                            } else {
                                                fg
                                            })
                                            .child(if na {
                                                "(N/A)".to_string()
                                            } else {
                                                value
                                            }),
                                    )
                            })
                        })
                    )
                    .when(col_pad_r > 0., |s| {
                        s.child(div().w(px(col_pad_r)).h_full().flex_none())
                    })
                }))
            .when(last_row < local_rows, |s| {
                s.child(div().flex_none().h(px((local_rows - last_row) as f32 * T_ROW_H)))
            })
            // 空表占位行：没有数据也画一行灰色「(N/A)」，行首槽与当前格按
            // 选中样式铺色，参考界面同款。占位行可直接点选；双击某格 =
            // 先补一条待新增行再就地编辑，等于替用户点了「+」（始终为空
            // 的话提交 / Esc 时收回该行）。取数中的页签不画，避免闪一行
            // 假数据。
            .when(
                local_rows == 0 && !cols.is_empty() && t.load.is_none(),
                |s| {
                    s.child(
                        h_flex()
                            .flex_none()
                            .h(px(T_ROW_H))
                            .border_b_1()
                            .border_color(line)
                            .child(
                                div()
                                    .id(rid("emptyrowgutter"))
                                    .w(px(T_GUTTER_W))
                                    .h_full()
                                    .flex_none()
                                    .flex()
                                    .items_center()
                                    .justify_center()
                                    .border_r_1()
                                    .border_color(line)
                                    .bg(head_cur)
                                    .cursor_pointer()
                                    .on_click(cx.listener(move |this, _, _, cx| {
                                        // 空表只有占位行：点行首槽整行选中，粘贴从第一列铺开
                                        if this.cell_editing.is_some() {
                                            this.commit_cell_edit(cx);
                                        }
                                        this.grid_drag = None;
                                        if let Some(ix) = this.grid_ready()
                                            && let Some(tab) = this.opened.get_mut(ix)
                                        {
                                            let last = tab.cols.len().saturating_sub(1);
                                            tab.cell = (0, tab.cell.1);
                                            tab.sel = Some(GridSel {
                                                anchor: (0, 0),
                                                focus: (0, last),
                                            });
                                        }
                                        cx.notify();
                                    }))
                                    .test_support()
                                    .child(
                                        div()
                                            .w(px(3.))
                                            .h_full()
                                            .flex_none()
                                            .bg(to_hsla(accent)),
                                    ),
                            )
                            .when(col_pad_l > 0., |s| {
                                s.child(div().w(px(col_pad_l)).h_full().flex_none())
                            })
                            .children(
                                disp_cols
                                    .iter()
                                    .enumerate()
                                    .skip(first_col)
                                    .take(last_col - first_col)
                                    .map(|(dc, &cix)| {
                                let width = disp_w[dc];
                                let current = t.cell == (0, cix);
                                let in_sel = t.sel.is_some_and(|s| s.contains(0, dc));
                                div()
                                    .id(rid(&format!("emptycell/{cix}")))
                                    .w(px(width))
                                    .h_full()
                                    .flex_none()
                                    .px(px(7.))
                                    .flex()
                                    .items_center()
                                    .border_r_1()
                                    .border_color(line)
                                    .cursor_pointer()
                                    .when(in_sel && !current, move |s| s.bg(sel_cell))
                                    .when(current, move |s| s.bg(cur_cell))
                                    .on_mouse_down(
                                        MouseButton::Left,
                                        cx.listener(move |this, ev: &MouseDownEvent, _, cx| {
                                            this.grid_placeholder_press(
                                                dc,
                                                cix,
                                                ev.modifiers.shift,
                                                true,
                                                cx,
                                            );
                                        }),
                                    )
                                    .on_mouse_down(
                                        MouseButton::Right,
                                        cx.listener(move |this, ev: &MouseDownEvent, _, cx| {
                                            this.grid_placeholder_press(
                                                dc,
                                                cix,
                                                ev.modifiers.shift,
                                                false,
                                                cx,
                                            );
                                        }),
                                    )
                                    // 按住左键划过其余占位格：选区焦点跟手
                                    .on_mouse_move(cx.listener(move |this, _, _, cx| {
                                        this.grid_cell_hover(0, dc, cx);
                                    }))
                                    .on_click(cx.listener(move |this, _: &ClickEvent, window, cx| {
                                        // 同真数据格：同格 + 系统双击时间
                                        if this.is_cell_double_click((0, cix)) {
                                            this.start_placeholder_edit(dc, cix, window, cx);
                                        }
                                        cx.notify();
                                    }))
                                    .test_support()
                                    .child(
                                        div()
                                            .text_size(px(12.))
                                            .text_color(if current || in_sel {
                                                to_hsla(0xffffff)
                                            } else {
                                                subtle
                                            })
                                            .child("(N/A)"),
                                    )
                                })
                            )
                            .when(col_pad_r > 0., |s| {
                                s.child(div().w(px(col_pad_r)).h_full().flex_none())
                            }),
                    )
                },
            )
            // 拖动重排的插入位竖条：盖在整张网格最上层，从表头顶贯穿到
            // 表格底部；纯装饰没有命中框，不挡列头的鼠标事件
            .when_some(drop_x, |s, x| {
                s.child(
                    div()
                        .id(rid("grid-drop-line"))
                        .absolute()
                        .left(px(x - 1.))
                        .top_0()
                        .bottom_0()
                        .w(px(2.))
                        .bg(to_hsla(accent))
                        .test_support(),
                )
            });

        // 页码框：只显示当前页（翻页只有首页 / 上一页 / 下一页 / 最后一页）
        let page_box = div()
            .id("nav/pagebox")
            .w(px(32.))
            .h(px(18.))
            .mx(px(2.))
            .flex()
            .items_center()
            .justify_center()
            .border_1()
            .border_color(border)
            .bg(paper)
            .text_size(px(11.5))
            .text_color(fg)
            .child(format!("{}", page + 1));

        let nav = {
            let ghost = |id: &'static str, glyph: art::Glyph| {
                tool_icon(rid(&format!("nav/{id}")), glyph, subtle, hover, false)
            };
            // 记录编辑组（参考界面导航条左组）：+ 新增 / − 删除恒可用；
            // ✓ 应用 / × 撤销只在工作集有变化时可用；刷新 = 重新取数（= 撤销）。
            // 图标统一用 Zed 线稿：与右侧翻页箭头同size同色，禁用态压到 subtle。
            let edit_btn = |id: &'static str, glyph: ZedIcon, enabled: bool| {
                div()
                    .id(rid(&format!("nav/{id}")))
                    .size(px(22.))
                    .flex()
                    .items_center()
                    .justify_center()
                    .rounded(px(2.))
                    .when(enabled, |s| s.cursor_pointer().hover(move |s| s.bg(hover)))
                    .child(
                        Icon::new(glyph).with_size(px(13.)).text_color(if enabled {
                            muted
                        } else {
                            subtle
                        }),
                    )
                    .test_support()
            };
            let nav_btn = |id: &'static str,
                           icon: ZedIcon,
                           enabled: bool,
                           target: usize,
                           page_target: usize,
                           last: bool,
                           cx: &mut Context<DaroApp>| {
                div()
                    .id(rid(&format!("nav/{id}")))
                    .size(px(22.))
                    .flex()
                    .items_center()
                    .justify_center()
                    .rounded(px(2.))
                    .text_color(if enabled { muted } else { subtle })
                    .when(enabled, |s| s.cursor_pointer().hover(move |s| s.bg(hover)))
                    .when(enabled, |s| {
                        s.on_click(cx.listener(move |this, _, _, cx| {
                            if this.active_tab == 0 {
                                return;
                            }
                            let remote = this
                                .opened
                                .get(this.active_tab - 1)
                                .is_some_and(|t| t.page.is_some());
                            if remote {
                                if last {
                                    this.grid_last_page(cx);
                                } else {
                                    this.grid_page_to(page_target, cx);
                                }
                            } else if let Some(tab) =
                                this.opened.get_mut(this.active_tab - 1)
                            {
                                tab.cell = (target, tab.cell.1);
                                cx.notify();
                            }
                        }))
                    })
                    .child(Icon::new(icon).with_size(px(13.)).text_color(if enabled {
                        muted
                    } else {
                        subtle
                    }))
                    .test_support()
            };
            let tab_k: TabIdent = (t.conn_name.clone(), t.db, t.schema, t.cat, t.obj);
            // MongoDB 只读：增 / 删 / 应用按钮置灰（右键菜单另有入口，方法内也拦）
            let read_only = self.tab_read_only(t);
            // 导航条的「停止」和加载卡片上是同一个动作：只有「还能停」的取数在跑时
            // 才亮——写回后的重取不给停，按过停止之后也不再亮
            let stop_enabled = t
                .load
                .as_ref()
                .is_some_and(|l| l.cancellable && !l.cancel.load(AtomicOrdering::Relaxed));
            // 记录数：平时是纯显示，点一下进就地编辑（回车 / 失焦提交）
            let limit_box = if let Some(input) = t.limit_input.as_ref() {
                div()
                    .id("nav/limitbox")
                    .w(px(46.))
                    .h(px(18.))
                    .flex_none()
                    .flex()
                    .items_center()
                    .px(px(4.))
                    .border_1()
                    .border_color(to_hsla(accent))
                    .bg(paper)
                    .child(
                        div().flex_1().min_w_0().child(
                            Input::new(input)
                                .h(px(16.))
                                .appearance(false)
                                .bordered(false)
                                .text_size(px(11.5)),
                        ),
                    )
                    .test_support()
            } else {
                div()
                    .id("nav/limitbox")
                    .w(px(46.))
                    .h(px(18.))
                    .flex_none()
                    .flex()
                    .items_center()
                    .justify_center()
                    .rounded(px(2.))
                    .border_1()
                    .border_color(border)
                    .bg(paper)
                    .text_size(px(11.5))
                    .text_color(if t.limit_on { fg } else { subtle })
                    .when(t.limit_on, |s| {
                        s.cursor_pointer().hover(move |s| s.bg(hover)).on_click(
                            cx.listener({
                                let k = tab_k.clone();
                                move |this, _, window, cx| {
                                    this.start_limit_edit(k.clone(), window, cx)
                                }
                            }),
                        )
                    })
                    .child(format!("{}", t.limit_size))
                    .test_support()
            };
            // Checkbox 是 RenderOnce 组件、自身没有可查询的 ElementId，
            // 测试里点勾选框靠外层这层 test_support 包一层。
            let limit_panel = h_flex()
                .gap(px(6.))
                .items_center()
                .child(div().id("nav/limit").test_support().child(
                    Checkbox::new("nav/limit-chk")
                        .with_size(gpui_kit::component::Size::Small)
                        .checked(t.limit_on)
                        .label("限制记录")
                        .on_click({
                            let me = cx.entity();
                            let k = tab_k.clone();
                            move |checked, _, app| {
                                let k = k.clone();
                                me.update(app, |this, cx| {
                                    this.set_record_limit(k, *checked, cx)
                                });
                            }
                        }),
                ))
                .child(limit_box)
                .child(
                    div()
                        .text_size(px(12.))
                        .text_color(if t.limit_on { fg } else { subtle })
                        .child("条记录（每页）"),
                );
            let gear = div()
                .id("nav/opts")
                .size(px(22.))
                .flex_none()
                .flex()
                .items_center()
                .justify_center()
                .rounded(px(2.))
                .cursor_pointer()
                .hover(move |s| s.bg(hover))
                .when(t.limit_open, |s| s.bg(to_hsla(p.selection)))
                .on_click(cx.listener({
                    let k = tab_k.clone();
                    move |this, _, _, cx| this.toggle_record_limit(k.clone(), cx)
                }))
                .child(art::icon(art::Glyph::Asset("TB_Tools"), 13., muted))
                .test_support();

            // 数据视图切换（参考界面数据页右下角两枚）：网格视图恒选中；
            // 表单视图在 Lite 是企业版功能，入口保留、点击弹「敬请期待」。
            let (grid_glyph, form_glyph) = if self.dark {
                ("GLYPH_GRIDVIEW_DARK", "GLYPH_FORMVIEW_DARK")
            } else {
                ("GLYPH_GRIDVIEW", "GLYPH_FORMVIEW")
            };
            // 明暗两套都用主题 accent：亮色原来的淡蓝只对 One Light 成立，
            // 换成 Ayu / Gruvbox 后要跟着主题走。
            let active_border = to_hsla(p.accent);
            let view_btn = |id: &'static str, glyph: &'static str, active: bool| {
                h_flex()
                    .id(rid(&format!("nav/{id}")))
                    .w(px(24.))
                    .h(px(20.))
                    .flex_none()
                    .items_center()
                    .justify_center()
                    .rounded(px(3.))
                    .border_1()
                    .border_color(if active {
                        active_border
                    } else {
                        to_hsla(p.chrome)
                    })
                    .when(active, move |s| s.bg(to_hsla(p.selection)))
                    .when(!active, move |s| s.cursor_pointer().hover(move |s| s.bg(hover)))
                    .child(art::icon(art::Glyph::Asset(glyph), 14., subtle))
                    .test_support()
            };

            h_flex()
                .h(px(T_BAR_H))
                .flex_none()
                .items_center()
                .px(px(6.))
                .gap(px(2.))
                .bg(to_hsla(p.chrome))
                .border_t_1()
                .border_color(border)
                .child(
                    edit_btn("add", ZedIcon::Plus, !read_only)
                        .on_click(cx.listener(|this, _, _, cx| this.grid_insert_row(cx))),
                )
                .child(
                    edit_btn("del", ZedIcon::Dash, rows > 0 && !read_only)
                        .on_click(cx.listener(|this, _, _, cx| this.grid_delete_row(cx))),
                )
                .child(
                    edit_btn("ok", ZedIcon::Check, dirty && !read_only)
                        .on_click(cx.listener(|this, _, _, cx| this.grid_apply(cx))),
                )
                .child(
                    edit_btn("cancel", ZedIcon::Close, dirty)
                        .on_click(cx.listener(|this, _, _, cx| this.grid_revert(cx))),
                )
                .child(
                    edit_btn("refresh", ZedIcon::RotateCw, true)
                        .on_click(cx.listener(|this, _, _, cx| this.grid_revert(cx))),
                )
                .child(
                    edit_btn("stop", ZedIcon::Stop, stop_enabled).on_click(cx.listener({
                        let k = tab_k.clone();
                        move |this, _, _, cx| this.grid_stop_load(k.clone(), cx)
                    })),
                )
                .child(div().flex_1())
                .child(nav_btn("first", ZedIcon::SkipBack, page > 0, 0, 0, false, cx))
                .child(nav_btn(
                    "prev",
                    ZedIcon::ChevronLeft,
                    page > 0,
                    page.saturating_sub(1) * local_size,
                    page.saturating_sub(1),
                    false,
                    cx,
                ))
                .child(page_box)
                .child(nav_btn(
                    "next",
                    ZedIcon::ChevronRight,
                    page + 1 < pages,
                    ((page + 1) * local_size).min(rows.saturating_sub(1)),
                    page + 1,
                    false,
                    cx,
                ))
                .child(nav_btn(
                    "last",
                    ZedIcon::SkipForward,
                    page + 1 < pages,
                    rows.saturating_sub(1),
                    pages.saturating_sub(1),
                    true,
                    cx,
                ))
                .when(t.limit_open, |s| {
                    s.child(limit_panel).child(div().w(px(6.)).flex_none())
                })
                .child(gear)
                .child(div().w(px(1.)).h(px(14.)).mx(px(4.)).bg(border))
                .child(ghost("find", art::Glyph::Asset("BTN_SEARCH")))
                .child(div().w(px(1.)).h(px(14.)).mx(px(4.)).bg(border))
                .child(view_btn("grid", grid_glyph, true))
                .child(view_btn("form", form_glyph, false).on_click(cx.listener(
                    |this, _, _, cx| ent_coming_soon(this.dark, cx),
                )))
        };

        // 取数中的加载卡片：盖在网格正中（打开表 / 翻页 / 写回后重取都走这里）。
        // 行数和耗时读的是后台写的共享量，重绘心跳见 [DaroApp::track_table_load]。
        let load_card = t.load.as_ref().map(|l| {
            let ident: TabIdent = (t.conn_name.clone(), t.db, t.schema, t.cat, t.obj);
            let fetched = l.fetched.load(AtomicOrdering::Relaxed);
            let stopping = l.cancel.load(AtomicOrdering::Relaxed);
            div()
                .absolute()
                .left_0()
                .top_0()
                .w_full()
                .h_full()
                .flex()
                .items_center()
                .justify_center()
                .child(
                    v_flex()
                        .id("table-load-card")
                        .w(px(340.))
                        .gap(px(12.))
                        .px(px(16.))
                        .py(px(14.))
                        .bg(paper)
                        .border_1()
                        .border_color(border)
                        .rounded(px(3.))
                        .shadow_lg()
                        .child(
                            h_flex()
                                .items_center()
                                .gap(px(8.))
                                .child(loading_spinner())
                                .child(
                                    div()
                                        .text_size(px(13.))
                                        .text_color(fg)
                                        .child(format!(
                                            "{} ({:.1}s)",
                                            if l.counting { "正在统计总行数" } else { "正在获取" },
                                            l.started.elapsed().as_secs_f32()
                                        )),
                                ),
                        )
                        .when(!l.counting, |s| {
                            s.child(
                                h_flex()
                                    .items_center()
                                    .gap(px(10.))
                                    .child(
                                        div()
                                            .text_size(px(13.))
                                            .text_color(fg)
                                            .child("获取记录:"),
                                    )
                                    .child(div().flex_1())
                                    .child(
                                        div()
                                            .text_size(px(13.))
                                            .text_color(fg)
                                            .child(format!("{fetched}")),
                                    )
                                    .child(div().flex_1())
                                    .when(l.cancellable, |s| {
                                        s.child(
                                            ui::secondary_button(
                                                "table-load-stop",
                                                if stopping { "停止中…" } else { "停止" },
                                            )
                                            .on_click(cx.listener(move |this, _, _, cx| {
                                                this.grid_stop_load(ident.clone(), cx);
                                            })),
                                        )
                                    }),
                            )
                        }),
                )
                .into_any_element()
        });

        // 滚轮驱动激活格：回调是 'static 的，得先记住这个页签在 opened 里
        // 的位置和它的滚动句柄（`t` 是 render 期间的借用，不能进闭包）。
        let tab_ix = self.opened.iter().position(|x| std::ptr::eq(x, t));
        let wheel_app = cx.entity().clone();
        let wheel_scroll = t.scroll.clone();

        v_flex()
            .id("table-page")
            .role(Role::Group)
            .aria_label("数据页")
            .size_full()
            .bg(bg)
            .child(toolbar)
            .when(t.filter.open, |s| s.child(self.filter_pane(t, cx)))
            .child(
                div()
                    .id("table-grid-wrap")
                    .role(Role::Table)
                    .aria_label("数据网格")
                    .relative()
                    .flex_1()
                    .min_h_0()
                    // 在表头以外松手也要收状态：否则列宽 / 重排拖动会卡在
                    // 拖动中，插入竖线一直画在表上
                    .on_mouse_up(
                        MouseButton::Left,
                        cx.listener(|this, _, _, cx| this.grid_header_release(cx)),
                    )
                    .child(
                        div()
                            .id("table-grid-inner")
                            .size_full()
                            .overflow_scroll()
                            .track_scroll(&t.scroll)
                            // 滚轮不再滚视图，改成一格一行地移动激活格；
                            // 当前格要出视口时才由回调带走视图。
                            .when_some(tab_ix, move |d, ix| {
                                d.on_scroll(move |ev, window, cx| {
                                    let d = ev.delta.pixel_delta(window.line_height());
                                    let dy = d.y.as_f32();
                                    let dx = d.x.as_f32();
                                    // Shift+滚轮：普通鼠标只有垂直轴，而 gpui 在两个方向都可滚时
                                    // 只认 delta.x，不会把 delta.y 搬到水平（默认滚动仍是竖滚）。
                                    // 这里手动把垂直分量转成水平偏移，同时抵掉默认滚动加上的
                                    // 同量竖直偏移；两种 listener 执行顺序下结果都一致。
                                    if ev.modifiers.shift
                                        && dy.abs() > f32::EPSILON
                                        && dx.abs() <= dy.abs()
                                    {
                                        let off = wheel_scroll.offset();
                                        // offset 取负值表示内容左移；dy<0 时 +dy 才是水平滚动。
                                        // 竖直方向减掉同一分量，抵消默认滚动加上的竖滚。
                                        wheel_scroll
                                            .set_offset(point(off.x + px(dy), off.y - px(dy)));
                                        let _ = wheel_app.update(cx, |_, cx| cx.notify());
                                        return;
                                    }
                                    // 横向滚轮仍交给默认滚动（本来就有 delta.x）。
                                    if ev.modifiers.shift
                                        || dy.abs() < f32::EPSILON
                                        || dx.abs() > dy.abs()
                                    {
                                        return;
                                    }
                                    // ScrollHandle 的 y 向下滚为负 → 行号 +1。
                                    let dir = if dy < 0. { 1 } else { -1 };
                                    let _ = wheel_app.update(cx, |this, cx| {
                                        this.data_grid_wheel_step(
                                            ix,
                                            &wheel_scroll,
                                            dy,
                                            dir,
                                            page_start,
                                            local_rows,
                                            head_h,
                                            cx,
                                        );
                                    });
                                })
                            })
                            .test_support()
                            .context_menu(grid_context_menu(cx.entity().clone(), self.dark))
                            .child(grid),
                    )
                    .vertical_scrollbar(&t.scroll)
                    .horizontal_scrollbar(&t.scroll)
                    .when_some(load_card, |s, card| s.child(card)),
            )
            .when(self.cell_viewer.open, |s| {
                s.child(self.cell_viewer_panel(Self::data_viewer_value(t), cx))
            })
            .child(nav)
            .into_any_element()
    }

    /// 「设计表」页签：工具栏 + 子标签条 + 字段网格 + 底部属性面板 + 状态条。
    /// 密度与配色照 Flutter 版 table_designer_page.dart 的实测档
    /// （行 21 / 表头 30 / 行首槽 12 / 列宽 [200,120,60,60,60,60,300]，
    /// 表头白底、网格 1px 线、当前格铺 accent 反白、锚点行淡蓝 + 2px 强调条）。
    fn designer_page(&self, tab: &OpenTab, cx: &mut Context<Self>) -> AnyElement {
        // 根据对象类型分发到不同的设计器：表(0)走完整实现，视图/实体化视图/函数走简化版
        if tab.cat != 0 {
            return self.view_or_function_designer(tab, cx);
        }
        
        let p = self.pal();
        let (bg, border, soft, fg, muted, subtle, accent, selection) = (
            to_hsla(p.background),
            to_hsla(p.border),
            to_hsla(p.border_soft),
            to_hsla(p.foreground),
            to_hsla(p.muted_foreground),
            to_hsla(p.subtle_foreground),
            to_hsla(p.accent),
            to_hsla(p.selection),
        );
        let hover = to_hsla(p.hover);
        let paper = to_hsla(0xffffff);
        // 表头「当前列」底色：和数据页同一口径（亮色往白里调，暗色往底色调）
        let head_cur = to_hsla(blend(p.accent, p.background, 0.74));

        let ds = tab.dstate.as_ref().expect("设计页签必有状态");
        let did = tab.did;
        let conn = self
            .conns
            .iter()
            .find(|c| c.name == tab.conn_name)
            .cloned()
            .unwrap_or_else(|| EMPTY_CONN.clone());
        // SQL 预览里的表名：新建表用保存时输入的名字（未命名时如实留空），
        // 编辑已有表用目录项名
        let table = ds
            .new_name
            .as_ref()
            .map(|n| n.as_str())
            .filter(|n| !n.is_empty())
            .unwrap_or_else(|| {
                catalog::objects(&conn, tab.db, tab_schema(&conn, tab), tab.cat)
                    .get(tab.obj)
                    .copied()
                    .unwrap_or_default()
            });
        let is_mysql = matches!(conn.kind, mock::DbKind::MySql);
        let is_pg = matches!(conn.kind, mock::DbKind::PostgreSql);
        let dirty = design_dirty(ds);
        let invalid = design_validation(&ds.cols, &ds.indexes, &ds.fks, &ds.uniques, &ds.checks)
            .or_else(|| design_options_validation(&ds.options))
            .or_else(|| design_excludes_gate(&ds.excludes, conn.kind))
            .or_else(|| design_excludes_validation(&ds.excludes))
            .or_else(|| design_rules_gate(&ds.rules, conn.kind))
            .or_else(|| design_rules_validation(&ds.rules))
            .or_else(|| design_triggers_gate(&ds.triggers, conn.kind))
            .or_else(|| design_triggers_validation(&ds.triggers, conn.kind));
        let can_save = dirty && invalid.is_none();
        let sel = Self::design_sel(ds);
        // 主键序号 = 该列在 pk 集合里的次序（1 起），与 PRIMARY KEY 列序一致
        let pk_ord =
            |r: usize| ds.cols.iter().take(r + 1).filter(|c| c.pk).count();

        // 工具栏按钮：图标 + 文字（参考界面是「保存 | 添加字段 删除字段 | 主键 ▾」）
        let tbtn = |id: &'static str,
                    icon: AnyElement,
                    label: &'static str,
                    caret: bool,
                    enabled: bool|
         -> Stateful<Div> {
            h_flex()
                .id(rid(id))
                .h(px(22.))
                .flex_none()
                .px(px(5.))
                .gap(px(4.))
                .items_center()
                .rounded(px(2.))
                .when(enabled, |s| s.cursor_pointer().hover(move |s| s.bg(hover)))
                .opacity(if enabled { 1. } else { 0.85 })
                .child(icon)
                .child(div().text_size(px(12.)).text_color(fg).child(label))
                .when(caret, move |s| {
                    s.child(
                        Icon::new(ZedIcon::ChevronDown)
                            .with_size(px(9.))
                            .text_color(subtle),
                    )
                })
        };
        let gicon = |glyph: art::Glyph| -> AnyElement {
            art::icon(glyph, 16., to_hsla(p.muted_foreground))
        };
        let tsep = || div().w(px(1.)).h(px(15.)).mx(px(6.)).flex_none().bg(border);

        // 工具栏右侧：校验错误（没有就留白）。底部不再放描述性信息，
        // 「已修改」由页签标题前的 * 表示（见 tab_label）。
        let toolbar_tail = || {
            h_flex()
                .flex_1()
                .min_w_0()
                .justify_end()
                .pr(px(10.))
                .when(ds.loading, |s| {
                    s.child(
                        div()
                            .text_size(px(12.))
                            .text_color(muted)
                            .child("载入表结构…"),
                    )
                })
                .when_some(invalid.as_ref(), |s, err| {
                    s.child(
                        div()
                            .truncate()
                            .text_size(px(12.))
                            .text_color(to_hsla(0xDC2626))
                            .child(err.clone()),
                    )
                })
        };

        // 企业版「询问 AI」：参考界面每个设计器子页工具条末尾都挂着它，
        // 这里入口全通，点击弹「敬请期待」。
        let ai_ent = |cx: &mut Context<Self>| {
            h_flex()
                .id(rid("dai"))
                .h(px(22.))
                .flex_none()
                .px(px(5.))
                .gap(px(4.))
                .items_center()
                .rounded(px(2.))
                .cursor_pointer()
                .hover(move |s| s.bg(hover))
                .child(div().flex_none().child(gicon(art::Glyph::AskAi)))
                .child(div().text_size(px(12.)).text_color(fg).child("询问 AI"))
                .on_click(cx.listener(|this, _, _, cx| {
                    ent_coming_soon(this.dark, cx);
                }))
                .test_support()
        };

        // 工具栏按子页分流：参考界面「索引」页是「保存 | 添加索引 删除索引」，
        // 「外键」页是「保存 | 添加外键 删除外键」，字段页是
        // 「保存 | 添加字段 删除字段 | 主键 ▾」。AI 项按用户要求不放。
        let toolbar = if ds.sub == 2 {
            h_flex()
                .h(px(D_TOOLBAR_H))
                .flex_none()
                .items_center()
                .px(px(4.))
                .bg(to_hsla(p.chrome))
                .border_b_1()
                .border_color(soft)
                .child(
                    tbtn("dsave", gicon(art::Glyph::SaveFile), "保存", false, can_save)
                        .when(can_save, |s| {
                            s.on_click(cx.listener(move |this, _, _, cx| this.design_save(did, cx)))
                        })
                        .test_support(),
                )
                .child(tsep())
                .child(
                    tbtn(
                        "dfk-add",
                        gicon(art::Glyph::Asset("TB_New")),
                        "添加外键",
                        false,
                        true,
                    )
                    .on_click(cx.listener(move |this, _, window, cx| {
                        this.design_add_fk(did, window, cx)
                    }))
                    .test_support(),
                )
                .child(
                    tbtn(
                        "dfk-del",
                        gicon(art::Glyph::Asset("TB_Delete")),
                        "删除外键",
                        false,
                        !ds.fks.is_empty(),
                    )
                    .when(!ds.fks.is_empty(), |s| {
                        s.on_click(cx.listener(move |this, _, window, cx| {
                            let row = this
                                .opened
                                .iter()
                                .find(|t| t.did == did)
                                .and_then(|t| t.dstate.as_ref())
                                .map(Self::design_fk_sel)
                                .unwrap_or(0);
                            this.design_remove_fk(did, row, window, cx)
                        }))
                    })
                    .test_support(),
                )
                .child(tsep())
                .child(ai_ent(cx))
                .child(toolbar_tail())
        } else if ds.sub == 3 {
            h_flex()
                .h(px(D_TOOLBAR_H))
                .flex_none()
                .items_center()
                .px(px(4.))
                .bg(to_hsla(p.chrome))
                .border_b_1()
                .border_color(soft)
                .child(
                    tbtn("dsave", gicon(art::Glyph::SaveFile), "保存", false, can_save)
                        .when(can_save, |s| {
                            s.on_click(cx.listener(move |this, _, _, cx| this.design_save(did, cx)))
                        })
                        .test_support(),
                )
                .child(tsep())
                .child(
                    tbtn(
                        "dun-add",
                        gicon(art::Glyph::Asset("TB_New")),
                        "添加唯一键",
                        false,
                        true,
                    )
                    .on_click(cx.listener(move |this, _, window, cx| {
                        this.design_add_unique(did, window, cx)
                    }))
                    .test_support(),
                )
                .child(
                    tbtn(
                        "dun-del",
                        gicon(art::Glyph::Asset("TB_Delete")),
                        "删除唯一键",
                        false,
                        !ds.uniques.is_empty(),
                    )
                    .when(!ds.uniques.is_empty(), |s| {
                        s.on_click(cx.listener(move |this, _, window, cx| {
                            let row = this
                                .opened
                                .iter()
                                .find(|t| t.did == did)
                                .and_then(|t| t.dstate.as_ref())
                                .map(Self::design_unique_sel)
                                .unwrap_or(0);
                            this.design_remove_unique(did, row, window, cx)
                        }))
                    })
                    .test_support(),
                )
                .child(div().flex_1())
        } else if ds.sub == 4 {
            h_flex()
                .h(px(D_TOOLBAR_H))
                .flex_none()
                .items_center()
                .px(px(4.))
                .bg(to_hsla(p.chrome))
                .border_b_1()
                .border_color(soft)
                .child(
                    tbtn("dsave", gicon(art::Glyph::SaveFile), "保存", false, can_save)
                        .when(can_save, |s| {
                            s.on_click(cx.listener(move |this, _, _, cx| this.design_save(did, cx)))
                        })
                        .test_support(),
                )
                .child(tsep())
                .child(
                    tbtn("dck-add", gicon(art::Glyph::Asset("TB_New")), "添加检查", false, true)
                        .on_click(cx.listener(move |this, _, window, cx| {
                            this.design_add_check(did, window, cx)
                        }))
                        .test_support(),
                )
                .child(
                    tbtn(
                        "dck-del",
                        gicon(art::Glyph::Asset("TB_Delete")),
                        "删除检查",
                        false,
                        !ds.checks.is_empty(),
                    )
                    .when(!ds.checks.is_empty(), |s| {
                        s.on_click(cx.listener(move |this, _, window, cx| {
                            let row = this
                                .opened
                                .iter()
                                .find(|t| t.did == did)
                                .and_then(|t| t.dstate.as_ref())
                                .map(Self::design_check_sel)
                                .unwrap_or(0);
                            this.design_remove_check(did, row, window, cx)
                        }))
                    })
                    .test_support(),
                )
                .child(div().flex_1())
        } else if ds.sub == 5 {
            h_flex()
                .h(px(D_TOOLBAR_H))
                .flex_none()
                .items_center()
                .px(px(4.))
                .bg(to_hsla(p.chrome))
                .border_b_1()
                .border_color(soft)
                .child(
                    tbtn("dsave", gicon(art::Glyph::SaveFile), "保存", false, can_save)
                        .when(can_save, |s| {
                            s.on_click(cx.listener(move |this, _, _, cx| this.design_save(did, cx)))
                        })
                        .test_support(),
                )
                .child(tsep())
                .child(
                    tbtn("dex-add", gicon(art::Glyph::Asset("TB_New")), "添加排除", false, true)
                        .on_click(cx.listener(move |this, _, window, cx| {
                            this.design_add_exclude(did, window, cx)
                        }))
                        .test_support(),
                )
                .child(
                    tbtn(
                        "dex-del",
                        gicon(art::Glyph::Asset("TB_Delete")),
                        "删除排除",
                        false,
                        !ds.excludes.is_empty(),
                    )
                    .when(!ds.excludes.is_empty(), |s| {
                        s.on_click(cx.listener(move |this, _, window, cx| {
                            let row = this
                                .opened
                                .iter()
                                .find(|t| t.did == did)
                                .and_then(|t| t.dstate.as_ref())
                                .map(Self::design_exclude_sel)
                                .unwrap_or(0);
                            this.design_remove_exclude(did, row, window, cx)
                        }))
                    })
                    .test_support(),
                )
                .child(div().flex_1())
        } else if ds.sub == 6 {
            h_flex()
                .h(px(D_TOOLBAR_H))
                .flex_none()
                .items_center()
                .px(px(4.))
                .bg(to_hsla(p.chrome))
                .border_b_1()
                .border_color(soft)
                .child(
                    tbtn("dsave", gicon(art::Glyph::SaveFile), "保存", false, can_save)
                        .when(can_save, |s| {
                            s.on_click(cx.listener(move |this, _, _, cx| this.design_save(did, cx)))
                        })
                        .test_support(),
                )
                .child(tsep())
                .child(
                    tbtn("drule-add", gicon(art::Glyph::Asset("TB_New")), "添加规则", false, true)
                        .on_click(cx.listener(move |this, _, window, cx| {
                            this.design_add_rule(did, window, cx)
                        }))
                        .test_support(),
                )
                .child(
                    tbtn(
                        "drule-del",
                        gicon(art::Glyph::Asset("TB_Delete")),
                        "删除规则",
                        false,
                        !ds.rules.is_empty(),
                    )
                    .when(!ds.rules.is_empty(), |s| {
                        s.on_click(cx.listener(move |this, _, window, cx| {
                            let row = this
                                .opened
                                .iter()
                                .find(|t| t.did == did)
                                .and_then(|t| t.dstate.as_ref())
                                .map(Self::design_rule_sel)
                                .unwrap_or(0);
                            this.design_remove_rule(did, row, window, cx)
                        }))
                    })
                    .test_support(),
                )
                .child(div().flex_1())
        } else if ds.sub == 8 {
            h_flex()
                .h(px(D_TOOLBAR_H))
                .flex_none()
                .items_center()
                .px(px(4.))
                .bg(to_hsla(p.chrome))
                .border_b_1()
                .border_color(soft)
                .child(
                    tbtn("dsave", gicon(art::Glyph::SaveFile), "保存", false, can_save)
                        .when(can_save, |s| {
                            s.on_click(cx.listener(move |this, _, _, cx| this.design_save(did, cx)))
                        })
                        .test_support(),
                )
                .child(div().flex_1())
        } else if ds.sub == 1 {
            h_flex()
                .h(px(D_TOOLBAR_H))
                .flex_none()
                .items_center()
                .px(px(4.))
                .bg(to_hsla(p.chrome))
                .border_b_1()
                .border_color(soft)
                .child(
                    tbtn("dsave", gicon(art::Glyph::SaveFile), "保存", false, can_save)
                        .when(can_save, |s| {
                            s.on_click(cx.listener(move |this, _, _, cx| this.design_save(did, cx)))
                        })
                        .test_support(),
                )
                .child(tsep())
                .child(
                    tbtn(
                        "didx-add",
                        gicon(art::Glyph::Asset("TB_New")),
                        "添加索引",
                        false,
                        true,
                    )
                    .on_click(cx.listener(move |this, _, window, cx| {
                        this.design_add_index(did, window, cx)
                    }))
                    .test_support(),
                )
                .child(
                    tbtn(
                        "didx-del",
                        gicon(art::Glyph::Asset("TB_Delete")),
                        "删除索引",
                        false,
                        !ds.indexes.is_empty(),
                    )
                    .when(!ds.indexes.is_empty(), |s| {
                        s.on_click(cx.listener(move |this, _, window, cx| {
                            let row = this
                                .opened
                                .iter()
                                .find(|t| t.did == did)
                                .and_then(|t| t.dstate.as_ref())
                                .map(Self::design_index_sel)
                                .unwrap_or(0);
                            this.design_remove_index(did, row, window, cx)
                        }))
                    })
                    .test_support(),
                )
                .child(tsep())
                .child(ai_ent(cx))
                .child(toolbar_tail())
        } else {
            h_flex()
                .h(px(D_TOOLBAR_H))
                .flex_none()
                .items_center()
                .px(px(4.))
                .bg(to_hsla(p.chrome))
                .border_b_1()
                .border_color(soft)
                .child(
                    tbtn("dsave", gicon(art::Glyph::SaveFile), "保存", false, can_save)
                        .when(can_save, |s| {
                            s.on_click(cx.listener(move |this, _, _, cx| this.design_save(did, cx)))
                        })
                        .test_support(),
                )
                .child(tsep())
                .child(
                    tbtn("dadd", gicon(art::Glyph::Asset("TB_New")), "添加字段", false, true)
                        .on_click(cx.listener(move |this, _, window, cx| {
                            this.design_add_col(did, window, cx)
                        }))
                        .test_support(),
                )
                .child(
                    tbtn(
                        "ddel",
                        gicon(art::Glyph::Asset("TB_Delete")),
                        "删除字段",
                        false,
                        ds.cols.len() > 1,
                    )
                    .when(ds.cols.len() > 1, |s| {
                        s.on_click(
                            cx.listener(move |this, _, _, cx| this.design_del_col(did, cx)),
                        )
                    })
                    .test_support(),
                )
                .child(
                    tbtn(
                        "dkey",
                        gicon(art::Glyph::KeyGold),
                        "主键",
                        true,
                        !ds.cols.is_empty(),
                    )
                    .when(!ds.cols.is_empty(), |s| {
                        s.on_click(
                            cx.listener(move |this, _, _, cx| this.design_toggle_pk(did, cx)),
                        )
                    })
                    .test_support(),
                )
                .child(tsep())
                .child(ai_ent(cx))
                .child(toolbar_tail())
        };

        // 子标签条：活动页签铺内容底，非活动可 hover
        let tabbar = h_flex()
            .h(px(D_TABBAR_H))
            .flex_none()
            .items_stretch()
            .bg(to_hsla(p.chrome))
            .border_b_1()
            .border_color(border)
            .children(D_SUBTABS.iter().enumerate().map(|(i, label)| {
                let active = ds.sub == i;
                h_flex()
                    .id(rid(&format!("dsub/{i}")))
                    .px(px(11.5))
                    .items_center()
                    .when(active, |s| s.bg(bg))
                    .when(!active, |s| {
                        s.cursor_pointer().hover(move |s| s.bg(hover))
                    })
                    .on_click(cx.listener(move |this, _, _, cx| {
                        if let Some(t) = this.opened.iter_mut().find(|t| t.did == did)
                            && let Some(d) = t.dstate.as_mut()
                        {
                            d.sub = i;
                            cx.notify();
                        }
                    }))
                    .child(
                        div()
                            .text_size(px(12.))
                            .text_color(if active { fg } else { muted })
                            .child(*label),
                    )
                    .test_support()
            }));

        // ── 字段网格 ──────────────────────────────────────────
        // 列宽：默认 D_FIELD_WIDTHS，拖过表头分割线后按 (子页 0, 列) 取用户宽
        let fw = |ix: usize| -> f32 {
            ds.widths
                .get(&(0usize, ix))
                .copied()
                .unwrap_or(D_FIELD_WIDTHS[ix])
        };
        let total_w = D_GUTTER_W + (0..7).map(fw).sum::<f32>();
        let gutter = move |h: f32, current: bool| {
            div()
                .w(px(D_GUTTER_W))
                .h(px(h))
                .flex_none()
                .relative()
                .border_r_1()
                .border_b_1()
                .border_color(border)
                .when(current, |s| {
                    s.bg(selection).child(
                        div()
                            .absolute()
                            .right_0()
                            .top_0()
                            .bottom_0()
                            .w(px(D_ACCENT_BAR_W))
                            .bg(accent),
                    )
                })
        };
        let headers =
            ["名称", "类型", "长度", "小数点", "不是 null", "键", "注释"];
        let header_row = h_flex()
            .h(px(D_HEADER_H))
            .flex_none()
            .child(gutter(D_HEADER_H, false))
            .on_mouse_move(cx.listener(|this, ev: &MouseMoveEvent, _, cx| {
                if let Some(did) = this.did_of_active_design() {
                    this.design_resize_move(did, ev.position.x.as_f32(), cx);
                }
            }))
            .on_mouse_up(
                MouseButton::Left,
                cx.listener(|this, _, _, cx| {
                    if let Some(did) = this.did_of_active_design() {
                        this.design_resize_end(did, cx);
                    }
                }),
            )
            .children(headers.iter().enumerate().map(|(i, h)| {
                let cur_w = fw(i);
                div()
                    .w(px(cur_w))
                    .h(px(D_HEADER_H))
                    .flex_none()
                    .relative()
                    .border_r_1()
                    .border_b_1()
                    .border_color(border)
                    .when(i == ds.cur, |s| {
                        s.child(
                            div()
                                .absolute()
                                .left_0()
                                .right_0()
                                .top_0()
                                .bottom_0()
                                .bg(head_cur)
                                .border_b_2()
                                .border_color(accent),
                        )
                    })
                    .child(
                        div()
                            .absolute()
                            .left(px(5.))
                            .top_0()
                            .bottom_0()
                            .flex()
                            .items_center()
                            .child(div().text_size(px(12.)).text_color(fg).child(*h)),
                    )
                    .child(
                        div()
                            .id(rid(&format!("field-resize/{i}")))
                            .absolute()
                            .right_0()
                            .top_0()
                            .bottom_0()
                            .w(px(5.))
                            .cursor_col_resize()
                            .on_mouse_down(
                                MouseButton::Left,
                                cx.listener(move |this, ev: &MouseDownEvent, _, cx| {
                                    this.design_resize_begin(
                                        did,
                                        0,
                                        i,
                                        ev.position.x.as_f32(),
                                        cur_w,
                                        cx,
                                    );
                                }),
                            ),
                    )
            }));

        // 文本格 / 勾选格 / 键格的通用包装：定宽 + 1px 网格线 + 点击选中
        let anchor_row = sel;
        let cell_box = move |r: usize, col: usize| {
            div()
                .id(rid(&format!("dcell/{r}/{col}")))
                .w(px(fw(col)))
                .h(px(D_ROW_EXTENT))
                .flex_none()
                .relative()
                .when(r == anchor_row, |s| s.bg(selection))
                .border_r_1()
                .border_b_1()
                .border_color(soft)
        };
        let cell_pick = |this: &mut Self,
                         did: u64,
                         r: usize,
                         col: usize,
                         _: &ClickEvent,
                         _: &mut Window,
                         cx: &mut Context<Self>| {
            if let Some(t) = this.opened.iter_mut().find(|t| t.did == did)
                && let Some(d) = t.dstate.as_mut()
            {
                d.sel = r;
                d.cur = col;
                cx.notify();
            }
        };
        let mut rows: Vec<AnyElement> = Vec::new();
        for (r, c) in ds.cols.iter().enumerate() {
            let anchor = r == sel;
            let edits = ds.edits.get(r);
            let text_cell = |col: usize,
                             f: usize,
                             val: &str,
                             placeholder: &'static str|
             -> AnyElement {
                let current = anchor && col == ds.cur;
                let editor = edits.and_then(|e| e[f].clone());
                cell_box(r, col)
                    .when(current, |s| s.bg(accent))
                    .on_click(cx.listener(move |this, ev, window, cx| {
                        cell_pick(this, did, r, col, ev, window, cx)
                    }))
                    .child(match editor {
                        Some(e) => div()
                            .absolute()
                            .left(px(5.))
                            .right(px(2.))
                            .top_0()
                            .bottom_0()
                            .flex()
                            .items_center()
                            .child(
                                div().flex_1().min_w_0().child(
                                    Input::new(&e)
                                        .id(rid(&format!("dinput/{r}/{f}")))
                                        .h(px(18.))
                                        .appearance(false)
                                        .bordered(false)
                                        .text_size(px(12.)),
                                ),
                            )
                            .into_any_element(),
                        None => {
                            let empty = val.is_empty();
                            div()
                                .absolute()
                                .left(px(5.))
                                .top_0()
                                .bottom_0()
                                .flex()
                                .items_center()
                                .overflow_hidden()
                                .child(
                                    div()
                                        .text_size(px(12.))
                                        .text_color(if current {
                                            paper
                                        } else if empty {
                                            subtle
                                        } else {
                                            fg
                                        })
                                        .child(if empty {
                                            placeholder.to_string()
                                        } else {
                                            val.to_string()
                                        }),
                                )
                                .into_any_element()
                        }
                    })
                    .test_support()
                    .into_any_element()
            };
            let check_cell = {
                let checked = c.not_null;
                div()
                    .id(rid(&format!("dcell/{r}/4")))
                    .w(px(D_FIELD_WIDTHS[4]))
                    .h(px(D_ROW_EXTENT))
                    .flex_none()
                    .flex()
                    .items_center()
                    .justify_center()
                    .border_r_1()
                    .border_b_1()
                    .border_color(soft)
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.design_set_not_null(did, r, !checked, cx)
                    }))
                    .child(
                        // 勾选框恒 13：方框是命中目标，不随行高缩（同 Flutter 版）
                        div()
                            .size(px(13.))
                            .rounded(px(2.))
                            .border_1()
                            .border_color(if checked { accent } else { subtle })
                            .bg(bg)
                            .flex()
                            .items_center()
                            .justify_center()
                            .when(checked, |s| {
                                s.child(
                                    Icon::new(ZedIcon::Check)
                                        .with_size(px(10.))
                                        .text_color(accent),
                                )
                            }),
                    )
                    .test_support()
                    .into_any_element()
            };
            let key_cell = {
                let pk_on = c.pk;
                let ord = pk_ord(r);
                div()
                    .id(rid(&format!("dcell/{r}/5")))
                    .w(px(D_FIELD_WIDTHS[5]))
                    .h(px(D_ROW_EXTENT))
                    .flex_none()
                    .flex()
                    .items_center()
                    .justify_center()
                    .border_r_1()
                    .border_b_1()
                    .border_color(soft)
                    .on_click(cx.listener(move |this, _, _, cx| {
                        // 点键格 = 选中该行 + 切换主键（零延迟，同 Flutter 版）
                        if let Some(t) = this.opened.iter_mut().find(|t| t.did == did)
                            && let Some(d) = t.dstate.as_mut()
                        {
                            d.sel = r;
                        }
                        this.design_toggle_pk(did, cx);
                    }))
                    .when(pk_on, |s| {
                        s.child(
                            h_flex()
                                .gap(px(2.))
                                .items_center()
                                .child(art::icon(
                                    art::Glyph::KeyGold,
                                    14.,
                                    to_hsla(D_ICON_KEY),
                                ))
                                .child(
                                    div().text_size(px(12.)).text_color(fg).child(
                                        format!("{ord}"),
                                    ),
                                ),
                        )
                    })
                    .test_support()
                    .into_any_element()
            };
            rows.push(
                h_flex()
                    .h(px(D_ROW_EXTENT))
                    .flex_none()
                    .child(
                        div()
                            .id(rid(&format!("dgutter/{r}")))
                            .when(anchor, |s| {
                                // 行首槽的点击命中交给外层包装：这里直接铺样式
                                s.bg(selection).child(
                                    div().absolute().right_0().top_0().bottom_0()
                                        .w(px(D_ACCENT_BAR_W)).bg(accent),
                                )
                            })
                            .w(px(D_GUTTER_W))
                            .h(px(D_ROW_EXTENT))
                            .flex_none()
                            .relative()
                            .border_r_1()
                            .border_b_1()
                            .border_color(border)
                            .on_click(cx.listener(move |this, _, _, cx| {
                                if let Some(t) =
                                    this.opened.iter_mut().find(|t| t.did == did)
                                    && let Some(d) = t.dstate.as_mut()
                                {
                                    d.sel = r;
                                    cx.notify();
                                }
                            }))
                            .test_support(),
                    )
                    .child(text_cell(0, 0, &c.name, "列名"))
                    .child(text_cell(1, 6, &c.ty, "类型"))
                    .child(text_cell(2, 1, &design_len_display(&c.ty, &c.len), ""))
                    .child(text_cell(3, 2, if c.dec.is_empty() { "0" } else { &c.dec }, ""))
                    .child(check_cell)
                    .child(key_cell)
                    .child(text_cell(6, 3, &c.comment, ""))
                    .into_any_element(),
            );
        }

        let grid = v_flex()
            .child(header_row)
            .children(rows)
            .context_menu(designer_context_menu(cx.entity().clone(), did));

        // 属性面板：标签列 190（面板左起 11）+ 控件列自 201 起，
        // 与网格第一列(200)对齐 —— 同 Flutter 版 _propField 的口径
        let flat_disabled = |w: f32, v: &str| -> AnyElement {
            div()
                .w(px(w))
                .h(px(20.))
                .flex_none()
                .px(px(5.))
                .flex()
                .items_center()
                .rounded(px(2.))
                .border_1()
                .border_color(soft)
                .bg(bg)
                .overflow_hidden()
                .child(div().text_size(px(12.)).text_color(subtle).child(v.to_string()))
                .into_any_element()
        };
        let prop_row = |label: &str, w: f32, control: AnyElement| -> AnyElement {
            h_flex()
                .h(px(D_PROP_ROW_H))
                .flex_none()
                .items_center()
                .child(
                    div()
                        .w(px(D_PROP_LABEL_W))
                        .flex_none()
                        .overflow_hidden()
                        .child(
                            div()
                                .text_size(px(12.))
                                .text_color(fg)
                                .child(format!("{label}:")),
                        ),
                )
                .child(div().w(px(w)).flex_none().flex().child(control))
                .into_any_element()
        };
        // 属性面板的固有高：没拖过那条缝时按它排（行数 × 行高 + 上下留白 18，
        // 末尾一行说明按 28 估——多留几像素宁可空着也别切到底行），并被 232 的
        // 上限截住，与原来 max_h 的口径一致。
        let mut props_native = 0.;
        let props: AnyElement = if ds.cols.is_empty() {
            div().into_any_element()
        } else {
            let c = &ds.cols[sel];
            let editor_of = |f: usize| {
                ds.edits.get(sel).and_then(|e| e[f].clone()).map(|e| {
                    div()
                        .flex_1()
                        .min_w_0()
                        .flex()
                        .items_center()
                        .child(
                            Input::new(&e)
                                .id(rid(&format!("dprop-input/{f}")))
                                .h(px(20.))
                                .appearance(false)
                                .bordered(false)
                                .text_size(px(12.)),
                        )
                        .into_any_element()
                })
            };
            let mut prows: Vec<AnyElement> = Vec::new();
            // 默认
            prows.push(prop_row(
                "默认",
                D_PROP_FIELD_W,
                editor_of(4).unwrap_or_else(|| flat_disabled(D_PROP_FIELD_W, &c.default)),
            ));
            // 排序规则：两个下拉并排 200 + 204（右槽 PG 无对应语法，占位）
            prows.push(prop_row(
                "排序规则",
                404.,
                h_flex()
                    .child(flat_disabled(200., &c.collation))
                    .child(flat_disabled(204., ""))
                    .into_any_element(),
            ));
            // 维度（数组维数，仅 PG 参与 DDL；mock 档只读展示）
            prows.push(prop_row(
                "维度",
                D_PROP_FIELD_W,
                flat_disabled(D_PROP_FIELD_W, ""),
            ));
            if is_mysql {
                let on = c.auto_inc;
                prows.push(prop_row(
                    "自增",
                    D_PROP_FIELD_W,
                    h_flex()
                        .gap(px(6.))
                        .items_center()
                        .child(
                            div()
                                .id(rid(&format!("dprop/auto/{sel}")))
                                .size(px(13.))
                                .rounded(px(2.))
                                .border_1()
                                .border_color(if on { accent } else { subtle })
                                .bg(bg)
                                .flex()
                                .items_center()
                                .justify_center()
                                .cursor_pointer()
                                .when(on, |s| {
                                    s.child(
                                        Icon::new(ZedIcon::Check)
                                            .with_size(px(10.))
                                            .text_color(accent),
                                    )
                                })
                                .on_click(cx.listener(move |this, _, _, cx| {
                                    if let Some(t) =
                                        this.opened.iter_mut().find(|t| t.did == did)
                                        && let Some(d) = t.dstate.as_mut()
                                        && let Some(col) = d.cols.get_mut(sel)
                                    {
                                        col.auto_inc = !on;
                                        d.note = None;
                                        cx.notify();
                                    }
                                }))
                                .test_support(),
                        )
                        .child(
                            div()
                                .text_size(px(12.))
                                .text_color(muted)
                                .child("AUTO_INCREMENT"),
                        )
                        .into_any_element(),
                ));
            } else {
                prows.push(prop_row(
                    if is_pg { "虚拟类型" } else { "标识" },
                    D_PROP_FIELD_W,
                    editor_of(5).unwrap_or_else(|| flat_disabled(D_PROP_FIELD_W, "")),
                ));
                for label in ["递增", "开始值"] {
                    prows.push(prop_row(
                        label,
                        D_PROP_FIELD_W,
                        flat_disabled(D_PROP_FIELD_W, ""),
                    ));
                }
                if is_pg {
                    for label in ["最小", "最大", "缓存"] {
                        prows.push(prop_row(
                            label,
                            D_PROP_FIELD_W,
                            flat_disabled(D_PROP_FIELD_W, ""),
                        ));
                    }
                    prows.push(prop_row(
                        "循环",
                        D_PROP_FIELD_W,
                        div()
                            .size(px(13.))
                            .rounded(px(2.))
                            .border_1()
                            .border_color(subtle)
                            .bg(bg)
                            .into_any_element(),
                    ));
                }
            }
            let hint = if is_mysql {
                Some("MySQL / MariaDB 自增：生成 AUTO_INCREMENT。")
            } else if is_pg {
                Some("PostgreSQL 虚拟类型：填 ALWAYS / BY DEFAULT 启用 IDENTITY。")
            } else {
                Some("SQL Server 标识列：生成 IDENTITY(开始值, 递增)。")
            };
            props_native =
                (18. + D_PROP_ROW_H * prows.len() as f32 + if hint.is_some() { 28. } else { 0. })
                    .min(232.);
            div()
                .id("dprops")
                .test_support()
                .child(
                    v_flex()
                        .flex_none()
                        .max_h(px(232.))
                        .overflow_y_scrollbar()
                        .pl(px(D_PROP_PAD_L))
                        .pr(px(D_PROP_PAD_L))
                        .pt(px(10.))
                        .pb(px(8.))
                        .bg(bg)
                        .children(prows)
                        .when_some(hint, |s, h| {
                            s.child(
                                div()
                                    .pt(px(4.))
                                    .text_size(px(12.))
                                    .text_color(subtle)
                                    .child(h),
                            )
                        }),
                )
                .into_any_element()
        };

        let fields_tab = v_flex()
            .size_full()
            .child(
                div()
                    .id("dgrid-scroll")
                    .flex_1()
                    .min_h_0()
                    .overflow_scrollbar()
                    
                    .child(div().w(px(total_w)).child(grid)),
            )
            .children(self.d_split_pair(
                tab.did,
                D_SPLIT_FIELDS,
                props_native,
                props,
                cx,
            ))
            .into_any_element();

        // ── SQL 预览页（参考界面 cameras 屏口径）────────────────
        // 「更改」子页 = 增量脚本（ALTER … ADD/DROP + CREATE/DROP INDEX），
        //   末尾固定带触发器 / 规则的生成段，右上角复制按钮；
        // 「DDL」子页 = 「之前：/之后：」并排行号对比，改动行整行铺绿底。
        let dark = self.dark;
        let schema_name = catalog::schemas(&conn, tab.db).get(tab.schema).copied().unwrap_or("");
        let owner = if matches!(conn.kind, mock::DbKind::PostgreSql) {
            conn.user.as_str()
        } else {
            ""
        };
        let mut preview_sql = design_create_sql_at(
            conn.kind,
            schema_name,
            table,
            owner,
            &ds.cols,
            &ds.indexes,
            &ds.fks,
            &ds.uniques,
            &ds.checks,
            &ds.options,
            &ds.excludes,
            &ds.rules,
        );
        for stmt in design_triggers_sql_at(conn.kind, schema_name, table, &ds.triggers) {
            preview_sql.push('\n');
            preview_sql.push_str(&stmt);
        }
        // 「之前」一栏：打开设计器（或上次保存）时的基线快照，同一条流水线生成
        let mut baseline_sql = design_create_sql_at(
            conn.kind,
            schema_name,
            table,
            owner,
            &ds.baseline,
            &ds.baseline_indexes,
            &ds.baseline_fks,
            &ds.baseline_uniques,
            &ds.baseline_checks,
            &ds.baseline_options,
            &ds.baseline_excludes,
            &ds.baseline_rules,
        );
        for stmt in design_triggers_sql_at(conn.kind, schema_name, table, &ds.baseline_triggers) {
            baseline_sql.push('\n');
            baseline_sql.push_str(&stmt);
        }
        let change_sql = sql_preview::design_change_sql(conn.kind, schema_name, table, ds);

        // 「更改 | DDL」子页签：活动项蓝字 + 蓝下划线（贴着文字），点哪页换哪页
        let sql_subtab = |i: usize, label: &'static str, active: bool| -> AnyElement {
            h_flex()
                .id(rid(&format!("dsqlsub/{i}")))
                .test_support()
                .px(px(3.))
                .cursor_pointer()
                .on_click(cx.listener(move |this, _, _, cx| {
                    if let Some(t) = this.opened.iter_mut().find(|t| t.did == did)
                        && let Some(d) = t.dstate.as_mut()
                    {
                        d.sql_sub = i;
                        cx.notify();
                    }
                }))
                .child(
                    div()
                        .text_size(px(12.))
                        .pb(px(2.))
                        .text_color(if active { accent } else { fg })
                        .when(active, |s| s.border_b_2().border_color(accent))
                        .child(label),
                )
                .into_any_element()
        };
        let sql_strip = h_flex()
            .h(px(24.))
            .flex_none()
            .items_center()
            .px(px(10.))
            .gap(px(18.))
            .child(sql_subtab(0, "更改", ds.sql_sub == 0))
            .child(sql_subtab(1, "DDL", ds.sql_sub == 1));
        let sql_body: AnyElement = if ds.sql_sub == 1 {
            // 「DDL」子页：之前 / 之后 两栏并排 diff，改动行整行绿底
            let before_lines: Vec<&str> = baseline_sql.lines().collect();
            let after_lines: Vec<&str> = preview_sql.lines().collect();
            let (chg_b, chg_a) = sql_preview::diff_lines(&baseline_sql, &preview_sql);
            let gutter_w = 28.;
            let w_before = sql_preview::code_lines_w(&before_lines, gutter_w);
            let w_after = sql_preview::code_lines_w(&after_lines, gutter_w);
            // id 挂外层（滚动条包一层内层 div，否则 overflow_scrollbar 会拆掉
            // test_support 的观察包装，元素就从测试注册表里消失）
            let pane = |id: &'static str, lines: &[&str], chg: &[bool], w: f32| {
                div()
                    .id(rid(id))
                    .test_support()
                    .flex_1()
                    .min_w_0()
                    .child(
                        div().size_full().overflow_scrollbar().child(
                            v_flex().w(px(w)).children(lines.iter().enumerate().map(|(i, l)| {
                                sql_preview::diff_row(i + 1, l, chg[i], w, gutter_w, dark, fg)
                            })),
                        ),
                    )
            };
            v_flex()
                .size_full()
                .child(
                    h_flex()
                        .flex_none()
                        .px(px(10.))
                        .pt(px(6.))
                        .pb(px(3.))
                        .gap(px(10.))
                        .child(
                            div()
                                .flex_1()
                                .text_size(px(12.))
                                .text_color(fg)
                                .child("之前:"),
                        )
                        .child(
                            div()
                                .flex_1()
                                .text_size(px(12.))
                                .text_color(fg)
                                .child("之后:"),
                        ),
                )
                .child(
                    h_flex()
                        .flex_1()
                        .min_h_0()
                        .px(px(10.))
                        .pb(px(6.))
                        .gap(px(10.))
                        .child(pane("dsql-before", &before_lines, &chg_b, w_before))
                        .child(pane("dsql-after", &after_lines, &chg_a, w_after)),
                )
                .into_any_element()
        } else {
            // 「更改」子页：增量脚本 + 右上角复制按钮；无改动就留白
            let lines: Vec<&str> = change_sql.lines().collect();
            let w_change = sql_preview::code_lines_w(&lines, 0.);
            let copy_btn = h_flex()
                .id("dsql-copy")
                .test_support()
                .absolute()
                .top(px(8.))
                .right(px(14.))
                .p(px(4.))
                .cursor_pointer()
                .hover(|s| s.bg(hover))
                .on_click({
                    let sql = change_sql.clone();
                    cx.listener(move |_, _, _, cx| {
                        cx.write_to_clipboard(gpui::ClipboardItem::new_string(sql.clone()));
                    })
                })
                .child(art::icon(
                    art::Glyph::Asset("BTN_COPY_TO_CLIPBOARD"),
                    15.,
                    to_hsla(0x4da0e1),
                ));
            div()
                .relative()
                .size_full()
                .child(
                    div()
                        .id("dsql-scroll")
                        .test_support()
                        .size_full()
                        .child(
                    div()
                        .size_full()
                        .overflow_scrollbar()
                        .child(v_flex().w(px(w_change)).pt(px(6.)).children(
                            lines.iter().map(|l| sql_preview::plain_row(l, w_change, dark, fg)),
                        )),
                ),
                )
                .when(!change_sql.is_empty(), |s| s.child(copy_btn))
                .into_any_element()
        };
        let sql_tab = v_flex()
            .size_full()
            .child(sql_strip)
            .child(sql_body)
            .into_any_element();

        let content: AnyElement = match ds.sub {
            0 => fields_tab,
            1 => self.indexes_tab(tab.did, ds, is_mysql, self.dark, cx),
            2 => self.fks_tab(tab.did, ds, is_mysql, self.dark, cx),
            3 => self.uniques_tab(tab.did, ds, self.dark, cx),
            4 => self.checks_tab(tab.did, ds, self.dark, cx),
            5 => self.excludes_tab(tab.did, ds, self.dark, cx),
            6 => self.rules_tab(tab.did, ds, self.dark, cx),
            7 => self.triggers_tab(tab.did, ds, self.dark, cx),
            8 => self.options_tab(tab.did, ds, self.dark, cx),
            9 => self.comment_tab(ds, self.dark, cx),
            10 => sql_tab,
            i => self.design_placeholder_tab(i, table, &conn, fg, subtle, bg, border),
        };

        // 底部不再放状态条：计数在窗口最底栏（status_bar）、「已修改」是页签标题前的 *、
        // 校验错挂在工具栏右端（见上面的 toolbar_tail）。
        let page = v_flex()
            .size_full()
            .bg(bg)
            .child(toolbar)
            .child(tabbar)
            .child(div().flex_1().min_h_0().child(content));
        // 浮层子编辑器（索引「字段」七列表格 / 外键等的「…」面板）挂在外层相对容器上
        let popup = self.design_popup_panel(tab.did, ds, cx);
        div()
            .relative()
            .size_full()
            .child(page)
            .when(ds.popup.is_some(), |s| s.child(popup))
            .into_any_element()
    }

    /// 设计器占位子页：索引 / 外键 / 唯一键 / 检查 / 排除 / 规则 / 触发器 / 选项 / 注释
    /// 每个子页显示即将实现的功能说明，保持界面结构完整
    fn design_placeholder_tab(
        &self,
        tab_index: usize,
        table: &str,
        conn: &mock::Connection,
        fg: Hsla,
        subtle: Hsla,
        bg: Hsla,
        _border: Hsla,
    ) -> AnyElement {
        let description = match tab_index {
            1 => format!("索引设计器（{}）：管理表的索引定义，包括主键索引、唯一索引、普通索引等。", table),
            2 => format!("外键设计器（{}）：定义表之间的外键关系，设置引用约束与级联规则。", table),
            3 => format!("唯一键设计器（{}）：管理唯一约束，确保列或列组合的值唯一。", table),
            4 => format!("检查约束设计器（{}）：定义 CHECK 约束，限制列值必须满足的条件。", table),
            5 => {
                if matches!(conn.kind, mock::DbKind::PostgreSql) {
                    format!("排除约束设计器（{}）：PostgreSQL 特有的排除约束，用于防止重叠范围等场景。", table)
                } else {
                    format!("排除约束（{}）：此约束类型仅 PostgreSQL 支持。", table)
                }
            }
            6 => format!("规则设计器（{}）：管理数据库规则（查询重写规则）。", table),
            7 => format!("触发器设计器（{}）：定义 BEFORE/AFTER/INSTEAD OF 触发器及其执行逻辑。", table),
            8 => format!("选项配置（{}）：设置表的存储引擎、字符集、排序规则等选项。", table),
            9 => format!("注释编辑器（{}）：为表及其列添加或修改注释说明。", table),
            _ => format!("子页 {} 即将实现。", tab_index),
        };

        v_flex()
            .size_full()
            .bg(bg)
            .p(px(24.))
            .items_center()
            .justify_center()
            .child(
                div()
                    .text_size(px(14.))
                    .text_color(fg)
                    .mb(px(12.))
                    .child(description),
            )
            .child(
                div()
                    .text_size(px(12.))
                    .text_color(subtle)
                    .child("此功能将在后续版本中实现"),
            )
            .into_any_element()
    }

    /// 视图 / 实体化视图 / 函数设计器：简化版设计器，结构与表设计器类似但子页签不同
    fn view_or_function_designer(&self, tab: &OpenTab, cx: &mut Context<Self>) -> AnyElement {
        let p = self.pal();
        let (bg, border, soft, fg, muted) = (
            to_hsla(p.background),
            to_hsla(p.border),
            to_hsla(p.border_soft),
            to_hsla(p.foreground),
            to_hsla(p.muted_foreground),
        );
        let hover = to_hsla(p.hover);

        let ds = tab.dstate.as_ref().expect("设计页签必有状态");
        let did = tab.did;
        let conn = self
            .conns
            .iter()
            .find(|c| c.name == tab.conn_name)
            .cloned()
            .unwrap_or_else(|| EMPTY_CONN.clone());

        // 根据对象类型确定子页签。规则与高级里的检查选项 / 安全屏障都是
        // PostgreSQL 独有的（视图上也一样），其它引擎的视图仍是「定义 / SQL 预览」两段。
        let view_subs_pg: &[&str] = &["定义", "规则", "高级", "注释", "SQL 预览"];
        let view_subs: &[&str] = &["定义", "SQL 预览"];
        let subtabs: &[&str] = match tab.cat {
            1 => {
                if matches!(conn.kind, mock::DbKind::PostgreSql) {
                    view_subs_pg
                } else {
                    view_subs
                }
            }
            2 => &["定义", "高级", "注释", "SQL 预览"],
            3 => &["参数", "返回值", "函数体", "SQL 预览"],
            _ => &["SQL 预览"],
        };
        // PG 视图才有规则 / 高级两页（工具条按子页换 添加 / 删除规则）
        let view_pg = tab.cat == 1 && matches!(conn.kind, mock::DbKind::PostgreSql);
        let view_rules = view_pg && ds.sub == 1;

        // 「已修改」按对象类型分别判定：
        // - 函数：参数表 / 返回类型 / 函数体 任一动了
        // - 实体化视图：定义正文 / 高级选项 / 刷新方式
        // - 视图：定义正文 / 规则 / 高级（属主、检查选项、安全屏障）
        // 正文比基线（打开已有视图时基线 = 库里的定义），不是「非空就算改过」
        let body_edited = ds.view_body.trim() != ds.baseline_view_body.trim();
        let dirty = match tab.cat {
            3 => ds.params != ds.baseline_params || ds.ret_ty != ds.baseline_ret_ty || body_edited,
            2 => {
                ds.matview_concurrent != ds.baseline_matview_concurrent
                    || ds.matview_with_data != ds.baseline_matview_with_data
                    || ds.options != ds.baseline_options
                    || body_edited
            }
            1 => {
                body_edited
                    || ds.rules != ds.baseline_rules
                    || (view_pg
                        && (ds.options.owner != ds.baseline_options.owner
                            || ds.options.comment != ds.baseline_options.comment
                            || ds.view_check_option != ds.baseline_view_check_option
                            || ds.view_security_barrier != ds.baseline_view_security_barrier))
            }
            _ => false,
        };
        // 函数的参数校验（重名 / 类型缺失）挡住保存
        let invalid = if tab.cat == 3 {
            design_function_validation(conn.kind, &ds.params, &ds.ret_ty)
        } else {
            None
        };
        // 新建页签还没落名字，保存要能点开命名框（参考界面同款）
        let can_save = (dirty || ds.new_name.is_some()) && invalid.is_none();

        // 工具栏按钮（参考界面视图设计器口径：图标 + 文字，同查询页工具条密度）
        let dbtn = |id: &'static str,
                    glyph: art::Glyph,
                    label: &'static str,
                    enabled: bool|
         -> Stateful<Div> {
            h_flex()
                .id(rid(id))
                .h(px(23.))
                .flex_none()
                .px(px(4.))
                .gap(px(5.))
                .items_center()
                .rounded(px(2.))
                .when(enabled, |s| s.cursor_pointer().hover(move |s| s.bg(hover)))
                .opacity(if enabled { 1. } else { 0.4 })
                .child(art::icon(glyph, 16., muted))
                .child(div().text_size(px(12.5)).text_color(fg).child(label))
        };
        let tsep = || {
            div()
                .w(px(D_TOOLSEP_W))
                .h(px(23.))
                .flex_none()
                .flex()
                .items_center()
                .justify_center()
                .child(div().w(px(1.)).h(px(23.)).bg(border))
        };

        // 预览 / 解释 / 视图创建工具 / 美化 SQL 只给视图与实体化视图（有「定义」正文）
        let is_view_kind = matches!(tab.cat, 1 | 2);
        let toolbar = h_flex()
            .h(px(D_TOOLBAR_H))
            .flex_none()
            .items_center()
            .px(px(4.))
            .gap(px(4.))
            .bg(to_hsla(p.chrome))
            .border_b_1()
            .border_color(soft)
            .child(
                dbtn("dsave", art::Glyph::SaveFile, "保存", can_save).when(can_save, {
                    |s| s.on_click(cx.listener(move |this, _, _, cx| this.design_save(did, cx)))
                }).test_support(),
            )
            .child(tsep())
            .when(is_view_kind, |s| {
                s.child(
                    dbtn("dpreview", art::Glyph::PreviewEye, "预览", true)
                        .on_click(cx.listener(move |this, _, window, cx| {
                            this.design_preview(did, false, window, cx);
                        }))
                        .test_support(),
                )
                .child(
                    dbtn("dexplain", art::Glyph::ExplainPlan, "解释", true)
                        .on_click(cx.listener(move |this, _, window, cx| {
                            this.design_preview(did, true, window, cx);
                        }))
                        .test_support(),
                )
                .child(tsep())
                .child(
                    h_flex()
                        .id(rid("dbuilder"))
                        .h(px(23.))
                        .flex_none()
                        .px(px(4.))
                        .gap(px(5.))
                        .items_center()
                        .rounded(px(2.))
                        .cursor_pointer()
                        .hover(move |s| s.bg(hover))
                        .on_click(cx.listener(|this, _, _, cx| {
                            ent_coming_soon(this.dark, cx);
                        }))
                        .test_support()
                        .child(art::icon(art::Glyph::ViewBuilder, 16., muted))
                        .child(
                            div()
                                .text_size(px(12.5))
                                .text_color(fg)
                                .child("视图创建工具"),
                        ),
                )
                .child(
                    dbtn("dpretty", art::Glyph::Beautify, "美化 SQL", true)
                        .on_click(cx.listener(move |this, _, window, cx| {
                            this.design_prettify(did, window, cx);
                        }))
                        .test_support(),
                )
                // 视图规则页：再加一条分隔块和 添加 / 删除规则（同表页规则子页）
                .when(view_rules, |s| {
                    s.child(tsep())
                        .child(
                            dbtn(
                                "vrule-add",
                                art::Glyph::Asset("TB_New"),
                                "添加规则",
                                true,
                            )
                                .on_click(cx.listener(move |this, _, window, cx| {
                                    this.design_add_rule(did, window, cx)
                                }))
                                .test_support(),
                        )
                        .child(
                            dbtn(
                                "vrule-del",
                                art::Glyph::Asset("TB_Delete"),
                                "删除规则",
                                !ds.rules.is_empty(),
                            )
                            .when(!ds.rules.is_empty(), |s| {
                                s.on_click(cx.listener(move |this, _, window, cx| {
                                    let row = this
                                        .opened
                                        .iter()
                                        .find(|t| t.did == did)
                                        .and_then(|t| t.dstate.as_ref())
                                        .map(Self::design_rule_sel)
                                        .unwrap_or(0);
                                    this.design_remove_rule(did, row, window, cx)
                                }))
                            })
                            .test_support(),
                        )
                })
            })
            .when_some(invalid.as_ref(), |s, err| {
                s.child(
                    div()
                        .truncate()
                        .text_size(px(12.))
                        .text_color(to_hsla(0xDC2626))
                        .child(err.clone()),
                )
            });

        // 子标签条
        let tabbar = h_flex()
            .h(px(D_TABBAR_H))
            .flex_none()
            .items_end()
            .px(px(4.))
            .bg(to_hsla(p.chrome))
            .border_b_1()
            .border_color(soft)
            .children(subtabs.iter().enumerate().map(|(i, label)| {
                let active = ds.sub == i;
                div()
                    .id(rid(&format!("dsub/{}", i)))
                    .px(px(12.))
                    .h(px(20.))
                    .flex()
                    .items_center()
                    .border_b_1()
                    .border_color(soft)
                    .when(i > 0, |s| s.border_l_1())
                    .bg(if active { bg } else { to_hsla(p.chrome) })
                    .cursor_pointer()
                    .hover(|s| s.bg(to_hsla(0xf0f0f0)))
                    .on_click(cx.listener({
                        let did = did;
                        move |this, _, _, cx| {
                            if let Some(t) = this.opened.iter_mut().find(|t| t.did == did)
                                && let Some(d) = t.dstate.as_mut()
                            {
                                d.sub = i;
                                cx.notify();
                            }
                        }
                    }))
                    .child(div().text_size(px(12.)).text_color(fg).child(*label))
                    .test_support()
            }));

        // 内容区：按对象类型 + 子页签分派
        let content: AnyElement = match tab.cat {
            // 函数：参数 / 返回值 / 函数体 / SQL 预览
            3 => match ds.sub {
                0 => self.function_params_tab(tab, cx),
                1 => self.function_returns_tab(tab, cx),
                2 => self.view_body_tab(tab, cx),
                _ => self.designer_sql_preview(tab, cx),
            },
            // 实体化视图：定义 / 高级 / 注释 / SQL 预览
            2 => match ds.sub {
                0 => self.view_body_tab(tab, cx),
                1 => self.matview_advanced_tab(tab, cx),
                2 => self.matview_comment_tab(tab, cx),
                _ => self.designer_sql_preview(tab, cx),
            },
            // 视图：定义 / 规则（仅 PG）/ 高级 / 注释 / SQL 预览
            1 => match ds.sub {
                0 => self.view_body_tab(tab, cx),
                1 if view_rules => self.view_rules_tab(tab.did, ds, self.dark, cx),
                2 if view_pg => self.view_advanced_tab(tab.did, ds, self.dark, cx),
                3 if view_pg => self.view_comment_tab(tab, cx),
                _ => self.designer_sql_preview(tab, cx),
            },
            _ => self.designer_sql_preview(tab, cx),
        };

        // 底部不放状态条（计数在窗口最底栏，「已修改」看页签标题前的 *）
        // 底部预览面板：点过「预览」才出现（消息 / 预览 + 结果网格）
        let preview_panel: Option<AnyElement> = if is_view_kind {
            ds.preview
                .as_ref()
                .map(|dp| self.design_preview_panel(did, dp, cx))
        } else {
            None
        };

        v_flex()
            .size_full()
            .bg(bg)
            .child(toolbar)
            .child(tabbar)
            .child(div().flex_1().min_h_0().child(content))
            .when_some(preview_panel, |s, panel| s.child(panel))
            .into_any_element()
    }

    /// 视图 / 实体化视图 / 函数 的正文页（「定义」/「函数体」）：
    /// 代码编辑器（SQL 高亮 + 补全），正文写回 ds.view_body，SQL 预览据此生成。
    fn view_body_tab(&self, tab: &OpenTab, _cx: &mut Context<Self>) -> AnyElement {
        let p = self.pal();
        let bg = to_hsla(p.background);
        let subtle = to_hsla(p.subtle_foreground);
        let ds = tab.dstate.as_ref().expect("设计页签必有状态");
        match ds.view_editor.clone() {
            Some(editor) => div()
                .id(rid("dbody"))
                .test_support()
                .size_full()
                .bg(bg)
                .child(
                    div()
                        .size_full()
                        .child(
                            Editor::new(&editor)
                                .appearance(false)
                                .bordered(false)
                                .h_full(),
                        ),
                )
                .into_any_element(),
            None => v_flex()
                .size_full()
                .bg(bg)
                .p(px(24.))
                .child(
                    div()
                        .text_size(px(12.))
                        .text_color(subtle)
                        .child("编辑器尚未就绪"),
                )
                .into_any_element(),
        }
    }

    /// 视图 / 实体化视图设计器的「预览」/「解释」：跑「定义」正文的 SELECT
    /// （explain = true 时改跑它的执行计划），结果落到底部消息 / 预览面板
    /// （参考界面口径：预览执行正文本身，不是 DDL）。
    fn design_preview(
        &mut self,
        did: u64,
        explain: bool,
        _window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(tab) = self.opened.iter().find(|t| t.did == did) else {
            return;
        };
        let Some(ds) = tab.dstate.as_ref() else { return };
        let sql = ds.view_body.trim().to_string();
        let conn = self
            .conns
            .iter()
            .find(|c| c.name == tab.conn_name)
            .cloned()
            .unwrap_or_else(|| EMPTY_CONN.clone());
        let db = tab.db.to_string();
        let schema = tab_schema(&conn, tab).to_string();
        let target = backend::Target::of(&conn, &db, &schema);

        let started = Instant::now();
        let mut outcome = QueryOutcome {
            sql: sql.clone(),
            result: None,
            columns: Vec::new(),
            message: None,
            elapsed_ms: 0,
            cell: (0, 0),
            sel: None,
            explain,
            pinned: false,
            pin_seq: 0,
        };
        if sql.is_empty() {
            outcome.message = Some("定义正文为空，无可预览结果。".to_string());
        } else if let Some(t) = target.as_ref() {
            let stmt = if explain { t.explain_sql(&sql) } else { sql.clone() };
            outcome.sql = stmt.clone();
            match t.execute(&stmt, t.row_limit()) {
                Ok(out) => {
                    let msg = (!out.message.is_empty()).then_some(out.message);
                    match out.select {
                        Some(page) => {
                            outcome.result = Some(page.rows);
                            outcome.columns = page.columns;
                            outcome.message = msg;
                        }
                        None => {
                            outcome.message =
                                msg.or(Some("定义正文不是查询语句，无可预览结果。".to_string()));
                        }
                    }
                }
                Err(e) => outcome.message = Some(format!("错误：{e}")),
            }
        } else {
            outcome.message = Some(if explain {
                "演示连接没有真实数据库，无法生成执行计划。".to_string()
            } else {
                "演示连接不连真实数据库，无法预览。".to_string()
            });
        }
        outcome.elapsed_ms = started.elapsed().as_millis();

        // 消息页口径同查询页：语句原文 + `> 结果` + `> 查询时间`
        let mut log = String::new();
        if !outcome.sql.is_empty() {
            log.push_str(&format!(
                "{}\n",
                outcome.sql.replace(['\n', '\r'], " ")
            ));
        }
        match (&outcome.result, &outcome.message) {
            (Some(_), None) => log.push_str("> OK\n"),
            (Some(_), Some(m)) => {
                log.push_str("> OK\n");
                log.push_str(&format!("> {m}\n"));
            }
            (None, Some(m)) => log.push_str(&format!("> {m}\n")),
            (None, None) => {}
        }
        log.push_str(&format!(
            "> 查询时间: {}\n",
            query_secs_text(outcome.elapsed_ms)
        ));

        let pane = if outcome.result.is_some() { 1 } else { 0 };
        if let Some(ds) = self
            .opened
            .iter_mut()
            .find(|t| t.did == did)
            .and_then(|t| t.dstate.as_mut())
        {
            ds.preview = Some(DesignPreview {
                outcome,
                log,
                pane,
                scroll: ScrollHandle::new(),
            });
        }
        cx.notify();
    }

    /// 「美化 SQL」：格式化「定义」正文（与查询页同款 sql_format 口径）。
    /// 编辑器写回经变更订阅同步 ds.view_body，「已修改」照常亮。
    fn design_prettify(&mut self, did: u64, window: &mut Window, cx: &mut Context<Self>) {
        let Some(tab) = self.opened.iter_mut().find(|t| t.did == did) else {
            return;
        };
        let Some(ds) = tab.dstate.as_mut() else { return };
        let Some(editor) = ds.view_editor.clone() else {
            return;
        };
        let src = editor.read(cx).value().to_string();
        let out = sql_format::pretty(&src);
        if out != src {
            // replace_all 而不是 set_value：set_value 会清空撤销栈，美化后 ctrl-z 就没了
            editor.update(cx, |s, cx| s.replace_all(out, window, cx));
        }
        cx.notify();
    }

    /// 点预览网格的格子：整行铺当前行色（参考界面预览口径：灰底，不做反白）。
    fn design_pick_cell(&mut self, did: u64, r: usize, c: usize, cx: &mut Context<Self>) {
        if let Some(ds) = self
            .opened
            .iter_mut()
            .find(|t| t.did == did)
            .and_then(|t| t.dstate.as_mut())
            && let Some(pv) = ds.preview.as_mut()
        {
            pv.outcome.cell = (r, c);
            cx.notify();
        }
    }

    /// 视图设计器底部预览面板：消息 / 预览页签 + 正文。
    fn design_preview_panel(
        &self,
        did: u64,
        dp: &DesignPreview,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let p = self.pal();
        let (bg, border, soft, fg, muted) = (
            to_hsla(p.background),
            to_hsla(p.border),
            to_hsla(p.border_soft),
            to_hsla(p.foreground),
            to_hsla(p.muted_foreground),
        );
        let hover = to_hsla(p.hover);
        // 「解释」和「预览」共用这第二个页签：正文是执行计划时页签跟着改叫「解释」
        let is_plan = dp.outcome.explain;
        let second = if is_plan { "解释" } else { "预览" };

        let tabbar = h_flex()
            .h(px(D_TABBAR_H))
            .flex_none()
            .items_stretch()
            .bg(to_hsla(p.chrome))
            .border_t_1()
            .border_color(border)
            .children([(0usize, "消息"), (1, second)].into_iter().map(|(i, label)| {
                let active = dp.pane == i;
                div()
                    .id(rid(&format!("dptab/{i}")))
                    .px(px(11.5))
                    .flex()
                    .items_center()
                    .bg(if active { bg } else { to_hsla(p.chrome) })
                    .when(!active, |s| s.cursor_pointer().hover(move |s| s.bg(hover)))
                    .on_click(cx.listener(move |this, _, _, cx| {
                        if let Some(ds) = this
                            .opened
                            .iter_mut()
                            .find(|t| t.did == did)
                            .and_then(|t| t.dstate.as_mut())
                            && let Some(pv) = ds.preview.as_mut()
                        {
                            pv.pane = i;
                        }
                        cx.notify();
                    }))
                    .child(
                        div()
                            .text_size(px(12.))
                            .text_color(if active { fg } else { muted })
                            .child(label),
                    )
                    .test_support()
            }));

        let body: AnyElement = if dp.pane == 0 {
            div()
                .id(rid("dpmsg"))
                .test_support()
                .size_full()
                .overflow_scroll()
                .p(px(10.))
                .child(
                    div()
                        .text_size(px(12.))
                        .text_color(fg)
                        .child(dp.log.clone()),
                )
                .into_any_element()
        } else if is_plan && dp.outcome.columns.len() <= 1 {
            // PostgreSQL 的计划是一列文本行：参考界面原样铺在页签里，不套网格表头
            // （SQLite 传统 EXPLAIN / MySQL EXPLAIN 是多列表格，仍走下面的网格）
            let text = dp
                .outcome
                .result
                .as_deref()
                .unwrap_or(&[])
                .iter()
                .map(|r| r.first().cloned().unwrap_or_default())
                .collect::<Vec<_>>()
                .join("\n");
            div()
                .id(rid("dpplan"))
                .test_support()
                .size_full()
                .overflow_scroll()
                .p(px(10.))
                .child(
                    div()
                        .font_family("Consolas")
                        .text_size(px(11.5))
                        .text_color(fg)
                        .child(text),
                )
                .into_any_element()
        } else {
            self.design_preview_grid(did, dp, soft, fg, muted, cx)
        };

        v_flex()
            .id(rid("dpreview-panel"))
            .test_support()
            .h(px(D_PREVIEW_PANEL_H))
            .flex_none()
            .border_t_1()
            .border_color(border)
            .child(tabbar)
            .child(div().flex_1().min_h_0().overflow_hidden().child(body))
            .into_any_element()
    }

    /// 预览结果网格：列名单行表头 + 斑马纹行 + 灰色当前行（取样参考界面
    /// 视图预览：选中行浅灰铺满、行首槽压一块深灰，不做深蓝反白）。
    fn design_preview_grid(
        &self,
        did: u64,
        dp: &DesignPreview,
        soft: Hsla,
        fg: Hsla,
        muted: Hsla,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let p = self.pal();
        let out = &dp.outcome;
        let cols = &out.columns;
        let rows = out.result.as_deref().unwrap_or(&[]);
        let cell = out.cell;
        let col_widths: Vec<f32> = cols.iter().map(|c| c.width).collect();
        let total_w = Q_ROWNO_W + col_widths.iter().sum::<f32>();

        let zebra = if self.dark {
            blend(p.background, 0xffffff, 0.05)
        } else {
            0xf6f6f6
        };
        let row_sel = if self.dark {
            blend(p.background, 0xffffff, 0.12)
        } else {
            0xefefef
        };
        let gutter_sel = if self.dark { 0x5a5a5a } else { 0x8a8a8a };
        let row_hover = to_hsla(p.hover);

        // 同结果网格：行数可能很大，只建视口附近的行，上下空白撑高
        let row_count = rows.len();
        let (first_row, last_row) = visible_row_window(
            dp.scroll.offset().y.as_f32().abs(),
            Q_PREVIEW_HEAD_H,
            Q_ROW_H,
            measured_view_h(&dp.scroll, self.viewport_h),
            row_count,
        );
        let view_w = {
            let measured = dp.scroll.bounds().size.width.as_f32();
            if measured > 0. { measured } else { self.viewport_w }
        };
        let (first_col, last_col, col_pad_l, col_pad_r) = visible_col_window(
            dp.scroll.offset().x.as_f32().abs(),
            view_w,
            Q_ROWNO_W,
            &col_widths,
        );

        let header = h_flex()
            .h(px(Q_PREVIEW_HEAD_H))
            .flex_none()
            .child(
                div()
                    .w(px(Q_ROWNO_W))
                    .h_full()
                    .flex_none()
                    .bg(to_hsla(p.background))
                    .border_b_1()
                    .border_r_1()
                    .border_color(soft),
            )
            .when(col_pad_l > 0., |s| {
                s.child(div().w(px(col_pad_l)).h_full().flex_none())
            })
            .children(
                cols.iter()
                    .enumerate()
                    .skip(first_col)
                    .take(last_col - first_col)
                    .map(|(dc, col)| {
                div()
                    .w(px(col_widths[dc]))
                    .h_full()
                    .flex_none()
                    .flex()
                    .items_center()
                    .px(px(6.))
                    .bg(to_hsla(p.background))
                    .border_b_1()
                    .border_r_1()
                    .border_color(soft)
                    .child(
                        div()
                            .min_w_0()
                            .truncate()
                            .text_size(px(11.5))
                            .font_medium()
                            .text_color(fg)
                            .child(col.name.clone()),
                    )
                })
            )
            .when(col_pad_r > 0., |s| {
                s.child(div().w(px(col_pad_r)).h_full().flex_none())
            });

        let grid = v_flex()
            .w(px(total_w))
            .flex_none()
            .child(header)
            .when(first_row > 0, |s| {
                s.child(div().flex_none().h(px(first_row as f32 * Q_ROW_H)))
            })
            .children((first_row..last_row).map(|rix| {
                let row = &rows[rix];
                let selected = cell.0 == rix;
                h_flex()
                    .flex_none()
                    .h(px(Q_ROW_H))
                    .when(selected, |s| s.bg(to_hsla(row_sel)))
                    .when(!selected, |s| {
                        s.when(rix % 2 == 1, |s| s.bg(to_hsla(zebra)))
                            .hover(move |s| s.bg(row_hover))
                    })
                    .child(
                        div()
                            .w(px(Q_ROWNO_W))
                            .h_full()
                            .flex_none()
                            .when(selected, |s| s.bg(to_hsla(gutter_sel)))
                            .border_b_1()
                            .border_r_1()
                            .border_color(soft),
                    )
                    .when(col_pad_l > 0., |s| {
                        s.child(div().w(px(col_pad_l)).h_full().flex_none())
                    })
                    .children(
                        cols.iter()
                            .enumerate()
                            .skip(first_col)
                            .take(last_col - first_col)
                            .map(|(cix, col)| {
                        let value = row.get(cix).cloned().unwrap_or_default();
                        div()
                            .id(rid(&format!("dpcell/{rix}/{cix}")))
                            .w(px(col_widths[cix]))
                            .h_full()
                            .flex_none()
                            .px(px(6.))
                            .flex()
                            .items_center()
                            .when(col.numeric, |s| s.justify_end())
                            .border_b_1()
                            .border_r_1()
                            .border_color(soft)
                            .cursor_pointer()
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.design_pick_cell(did, rix, cix, cx);
                            }))
                            .test_support()
                            .child(
                                div()
                                    .min_w_0()
                                    .max_w_full()
                                    .truncate()
                                    .text_size(px(11.5))
                                    .text_color(fg)
                                    .child(value),
                            )
                    })
                    )
                    .when(col_pad_r > 0., |s| {
                        s.child(div().w(px(col_pad_r)).h_full().flex_none())
                    })
            }))
            .when(last_row < row_count, |s| {
                s.child(div().flex_none().h(px((row_count - last_row) as f32 * Q_ROW_H)))
            });

        let footer = h_flex()
            .id("dpfoot")
            .test_support()
            .h(px(Q_RESULT_FOOT_H))
            .flex_none()
            .items_center()
            .px(px(8.))
            .bg(to_hsla(p.chrome))
            .border_t_1()
            .border_color(soft)
            .child(div().flex_1())
            .child(
                div()
                    .text_size(px(11.))
                    .text_color(muted)
                    .child(format!("共 {row_count} 行")),
            );

        v_flex()
            .size_full()
            .child(
                div()
                    .id(rid("dpgrid"))
                    .test_support()
                    .flex_1()
                    .min_h_0()
                    .relative()
                    .child(
                        div()
                            .id(rid("dpgrid-inner"))
                            .size_full()
                            .overflow_scroll()
                            .track_scroll(&dp.scroll)
                            .child(grid),
                    )
                    .vertical_scrollbar(&dp.scroll)
                    .horizontal_scrollbar(&dp.scroll),
            )
            .child(footer)
            .into_any_element()
    }

    /// 函数设计器「参数」子页：名称 / 类型 / 模式 / 默认值 四列常驻编辑器
    /// + 每行删除按钮 + 底部「添加参数」。空的整行（种子行）不算真参数。
    fn function_params_tab(&self, tab: &OpenTab, cx: &mut Context<Self>) -> AnyElement {
        let p = self.pal();
        let (bg, border, soft, fg, subtle, accent, selection) = (
            to_hsla(p.background),
            to_hsla(p.border),
            to_hsla(p.border_soft),
            to_hsla(p.foreground),
            to_hsla(p.subtle_foreground),
            to_hsla(p.accent),
            to_hsla(p.selection),
        );
        let hover = to_hsla(p.hover);
        let ds = tab.dstate.as_ref().expect("设计页签必有状态");
        let did = tab.did;
        let conn = self
            .conns
            .iter()
            .find(|c| c.name == tab.conn_name)
            .cloned()
            .unwrap_or_else(|| EMPTY_CONN.clone());
        // 「模式」一列是自由文本，占位符提示当前方言可用的模式
        let mode_hint = design_param_modes(conn.kind).join(" / ");

        // 表头
        let headers = ["名称", "类型", "模式", "默认值"];
        let header_row = h_flex()
            .h(px(D_HEADER_H))
            .flex_none()
            .child(
                div()
                    .w(px(D_GUTTER_W))
                    .h(px(D_HEADER_H))
                    .flex_none()
                    .border_r_1()
                    .border_b_1()
                    .border_color(border),
            )
            .children(headers.iter().enumerate().map(|(i, h)| {
                div()
                    .w(px(D_PARAM_WIDTHS[i]))
                    .h(px(D_HEADER_H))
                    .flex_none()
                    .relative()
                    .border_r_1()
                    .border_b_1()
                    .border_color(border)
                    .child(
                        div()
                            .absolute()
                            .left(px(5.))
                            .top_0()
                            .bottom_0()
                            .flex()
                            .items_center()
                            .child(div().text_size(px(12.)).text_color(fg).child(*h)),
                    )
            }))
            .child(
                div()
                    .w(px(D_PARAM_WIDTHS[4]))
                    .h(px(D_HEADER_H))
                    .flex_none()
                    .border_b_1()
                    .border_color(border),
            );

        // 参数行
        let mut rows: Vec<AnyElement> = Vec::new();
        for (r, prm) in ds.params.iter().enumerate() {
            let anchor = r == ds.param_sel;
            let edits = ds.param_edits.get(r);
            let vals = [
                prm.name.clone(),
                prm.ty.clone(),
                prm.mode.clone(),
                prm.default.clone(),
            ];
            let placeholders = ["参数名", "类型", mode_hint.as_str(), "默认值"];
            let mut cells: Vec<AnyElement> = Vec::new();
            cells.push(
                div()
                    .w(px(D_GUTTER_W))
                    .h(px(D_ROW_EXTENT))
                    .flex_none()
                    .relative()
                    .border_r_1()
                    .border_b_1()
                    .border_color(border)
                    .when(anchor, |s| {
                        s.bg(selection).child(
                            div()
                                .absolute()
                                .right_0()
                                .top_0()
                                .bottom_0()
                                .w(px(D_ACCENT_BAR_W))
                                .bg(accent),
                        )
                    })
                    .into_any_element(),
            );
            for f in 0..4 {
                let val = vals[f].clone();
                let editor = edits.and_then(|e| e[f].clone());
                cells.push(
                    div()
                        .id(rid(&format!("pcell/{r}/{f}")))
                        .w(px(D_PARAM_WIDTHS[f]))
                        .h(px(D_ROW_EXTENT))
                        .flex_none()
                        .relative()
                        .border_r_1()
                        .border_b_1()
                        .border_color(soft)
                        .on_click(cx.listener(move |this, _, _, cx| {
                            this.design_pick_param_cell(did, r, cx)
                        }))
                        .child(match editor {
                            Some(e) => div()
                                .absolute()
                                .left(px(5.))
                                .right(px(2.))
                                .top_0()
                                .bottom_0()
                                .flex()
                                .items_center()
                                .child(
                                    div().flex_1().min_w_0().child(
                                        Input::new(&e)
                                            .id(rid(&format!("pinput/{r}/{f}")))
                                            .h(px(18.))
                                            .appearance(false)
                                            .bordered(false)
                                            .text_size(px(12.)),
                                    ),
                                )
                                .into_any_element(),
                            None => div()
                                .absolute()
                                .left(px(5.))
                                .top_0()
                                .bottom_0()
                                .flex()
                                .items_center()
                                .overflow_hidden()
                                .child(
                                    div()
                                        .text_size(px(12.))
                                        .text_color(if val.trim().is_empty() {
                                            subtle
                                        } else {
                                            fg
                                        })
                                        .child(if val.trim().is_empty() {
                                            placeholders[f].to_string()
                                        } else {
                                            val.clone()
                                        }),
                                )
                                .into_any_element(),
                        })
                        .test_support()
                        .into_any_element(),
                );
            }
            // 删除按钮
            cells.push(
                div()
                    .id(rid(&format!("pdel/{r}")))
                    .w(px(D_PARAM_WIDTHS[4]))
                    .h(px(D_ROW_EXTENT))
                    .flex_none()
                    .flex()
                    .items_center()
                    .justify_center()
                    .border_b_1()
                    .border_color(soft)
                    .cursor_pointer()
                    .hover(move |s| s.bg(hover))
                    .on_click(cx.listener(move |this, _, _, cx| {
                        this.design_del_param(did, r, cx)
                    }))
                    .child(
                        Icon::new(ZedIcon::Close)
                            .with_size(px(12.))
                            .text_color(to_hsla(D_ICON_DANGER)),
                    )
                    .test_support()
                    .into_any_element(),
            );
            rows.push(
                h_flex()
                    .h(px(D_ROW_EXTENT))
                    .flex_none()
                    .children(cells)
                    .into_any_element(),
            );
        }

        // 底部「添加参数」
        let add_btn = h_flex()
            .id(rid("padd"))
            .h(px(22.))
            .flex_none()
            .px(px(8.))
            .gap(px(4.))
            .items_center()
            .rounded(px(2.))
            .cursor_pointer()
            .hover(move |s| s.bg(hover))
            .on_click(cx.listener(move |this, _, window, cx| {
                this.design_add_param(did, window, cx)
            }))
            .child(art::icon(
                art::Glyph::Asset("TB_New"),
                13.,
                to_hsla(D_ICON_ADD),
            ))
            .child(div().text_size(px(12.)).text_color(fg).child("添加参数"))
            .test_support();

        v_flex()
            .size_full()
            .bg(bg)
            .flex_none()
            .child(header_row)
            .children(rows)
            .child(
                h_flex()
                    .h(px(30.))
                    .flex_none()
                    .items_center()
                    .px(px(6.))
                    .child(add_btn),
            )
            .into_any_element()
    }

    /// 函数设计器「返回值」子页：返回类型输入 + 方言说明。
    /// 留空 = 存储过程（MySQL），有值 = 函数（PG / MySQL）。
    fn function_returns_tab(&self, tab: &OpenTab, cx: &mut Context<Self>) -> AnyElement {
        let p = self.pal();
        let (bg, fg, muted, subtle) = (
            to_hsla(p.background),
            to_hsla(p.foreground),
            to_hsla(p.muted_foreground),
            to_hsla(p.subtle_foreground),
        );
        let ds = tab.dstate.as_ref().expect("设计页签必有状态");
        let did = tab.did;
        let conn = self
            .conns
            .iter()
            .find(|c| c.name == tab.conn_name)
            .cloned()
            .unwrap_or_else(|| EMPTY_CONN.clone());

        let hint = match conn.kind {
            mock::DbKind::PostgreSql => {
                "PostgreSQL：填类型生成 RETURNS <类型>；留空按 void（无返回值）处理。"
            }
            mock::DbKind::MySql => {
                "MySQL：填类型生成 CREATE FUNCTION … RETURNS <类型>；留空生成 CREATE PROCEDURE。"
            }
            mock::DbKind::SqlServer => {
                "SQL Server：只有存储过程，返回值请用「参数」页的 OUTPUT 模式。"
            }
            _ => "当前方言暂不支持函数 / 存储过程定义。",
        };

        v_flex()
            .size_full()
            .bg(bg)
            .p(px(16.))
            .gap(px(8.))
            .child(
                h_flex()
                    .flex_none()
                    .items_center()
                    .gap(px(8.))
                    .child(
                        div()
                            .w(px(70.))
                            .flex_none()
                            .text_size(px(12.))
                            .text_color(fg)
                            .child("返回类型"),
                    )
                    .child(
                        div()
                            .w(px(220.))
                            .flex_none()
                            .child(match ds.ret_edit.clone() {
                                Some(e) => Input::new(&e)
                                    .id(rid("ret-input"))
                                    .h(px(22.))
                                    .bordered(true)
                                    .text_size(px(12.))
                                    .into_any_element(),
                                None => div()
                                    .h(px(22.))
                                    .flex()
                                    .items_center()
                                    .text_size(px(12.))
                                    .text_color(subtle)
                                    .child("输入框尚未就绪")
                                    .into_any_element(),
                            }),
                    )
                    .child(
                        div()
                            .text_size(px(12.))
                            .text_color(muted)
                            .child(if ds.ret_ty.trim().is_empty() {
                                "（留空 = 无返回值）".to_string()
                            } else {
                                ds.ret_ty.clone()
                            }),
                    )
                    .child(
                        Button::new(rid("ret-clear"))
                            .ghost()
                            .with_size(gpui_kit::component::Size::XSmall)
                            .h(px(20.))
                            .px(px(6.))
                            .rounded(px(2.))
                            .text_color(to_hsla(p.muted_foreground))
                            .child("清空")
                            .on_click(cx.listener(move |this, _, window, cx| {
                                this.design_set_ret_ty(did, String::new(), window, cx)
                            })),
                    ),
            )
            .child(
                div()
                    .text_size(px(12.))
                    .text_color(muted)
                    .child(hint),
            )
            .child(
                div()
                    .text_size(px(12.))
                    .text_color(subtle)
                    .child(format!(
                        "提示：{} 参数",
                        ds.params.iter().filter(|x| !design_param_blank(x)).count()
                    )),
            )
            .child(
                // 当前连接 / 模式的说明（函数生成的 DDL 会带上模式限定名）
                div()
                    .text_size(px(12.))
                    .text_color(subtle)
                    .child(format!(
                        "连接：{} · 模式：{}",
                        conn.name,
                        if tab_schema(&conn, tab).is_empty() {
                            "（无）"
                        } else {
                            tab_schema(&conn, tab)
                        }
                    )),
            )
            .child(
                div()
                    .mt(px(4.))
                    .h(px(1.))
                    .bg(to_hsla(p.border)),
            )
            .child(
                div()
                    .text_size(px(12.))
                    .text_color(muted)
                    .child("SQL 预览页会按当前方言生成完整定义。"),
            )
            .into_any_element()
    }

    /// 实体化视图「高级」子页：所有者 / 表空间 / 填充因子 / 配备数据
    /// （版式照参考界面：左列标签宽约 250，字段 372×24，行距 36）。
    fn matview_advanced_tab(&self, tab: &OpenTab, cx: &mut Context<Self>) -> AnyElement {
        let p = self.pal();
        let (bg, fg, muted) = (
            to_hsla(p.background),
            to_hsla(p.foreground),
            to_hsla(p.muted_foreground),
        );
        let ds = tab.dstate.as_ref().expect("设计页签必有状态");
        let did = tab.did;
        let me = cx.entity();
        // 组合框外观：输入框 + 右侧向下箭头（箭头不接事件，点不到）
        let combo = |state: Option<Entity<InputState>>| -> AnyElement {
            match state {
                Some(state) => div()
                    .relative()
                    .w(px(372.))
                    .child(Input::new(&state).h(px(24.)).appearance(true).bordered(true))
                    .child(
                        div()
                            .absolute()
                            .right(px(7.))
                            .top(px(0.))
                            .h(px(24.))
                            .flex()
                            .items_center()
                            .child(
                                Icon::new(ZedIcon::ChevronDown)
                                    .with_size(px(9.))
                                    .text_color(muted),
                            ),
                    )
                    .into_any_element(),
                None => div().w(px(372.)).h(px(24.)).into_any_element(),
            }
        };
        // 普通输入框：只描边、不带下拉箭头（填充因子照参考界面原样）
        let plain = |state: Option<Entity<InputState>>| -> AnyElement {
            match state {
                Some(state) => div()
                    .w(px(372.))
                    .child(Input::new(&state).h(px(24.)).appearance(true).bordered(true))
                    .into_any_element(),
                None => div().w(px(372.)).h(px(24.)).into_any_element(),
            }
        };
        let label = |text: &'static str| {
            div()
                .w(px(250.))
                .flex_none()
                .text_size(px(12.5))
                .text_color(fg)
                .child(text)
        };
        v_flex()
            .size_full()
            .bg(bg)
            .p(px(4.))
            .pt(px(30.))
            .gap(px(12.))
            .child(
                h_flex()
                    .id(rid("mv/owner"))
                    .items_center()
                    .aria_label("所有者:")
                    .child(label("所有者:"))
                    .child(combo(ds.opt_edits[0].clone()))
                    .test_support(),
            )
            .child(
                h_flex()
                    .id(rid("mv/tablespace"))
                    .items_center()
                    .aria_label("表空间")
                    .child(label("表空间"))
                    .child(combo(ds.opt_edits[1].clone()))
                    .test_support(),
            )
            .child(
                h_flex()
                    .id(rid("mv/fillfactor"))
                    .items_center()
                    .aria_label("填充因子")
                    .child(label("填充因子"))
                    .child(plain(ds.opt_edits[3].clone()))
                    .test_support(),
            )
            .child(
                h_flex()
                    .id(rid("mv/with-data"))
                    .items_center()
                    .gap(px(6.))
                    .aria_label("配备数据")
                    .child(
                        Checkbox::new("matview-with-data")
                            .checked(ds.matview_with_data)
                            .on_click(move |checked, _, app_cx| {
                                let on = *checked;
                                me.update(app_cx, |this, cx| {
                                    this.design_set_matview_with_data(did, on, cx)
                                });
                            }),
                    )
                    .child(div().text_size(px(12.5)).text_color(fg).child("配备数据"))
                    .test_support(),
            )
            .into_any_element()
    }

    /// 实体化视图「注释」子页：一段注释文本（与表设计器注释格同口径）。
