    /// 视图的规则必须写 `TO 目标`（PG 的 `CREATE RULE … ON event TO 对象` 语法）；
    /// 表页沿用不带 TO 的旧口径。
    #[test]
    fn rule_sql_targets_object_when_to_supplied() {
        let rule = DesignRule {
            name: "r_ins".into(),
            event: "INSERT".into(),
            action: "INSTEAD".into(),
            statement: "INSERT INTO log SELECT 1".into(),
            ..Default::default()
        };
        assert_eq!(
            design_rule_sql(&rule, "\"public\".\"v_users\"").unwrap(),
            r#"CREATE RULE "r_ins" AS ON INSERT TO "public"."v_users" DO INSTEAD INSERT INTO log SELECT 1;"#
        );
        assert!(
            design_rule_sql(&rule, "")
                .unwrap()
                .contains("AS ON INSERT DO INSTEAD"),
            "表页不带 TO"
        );
        assert!(
            design_rule_sql(&DesignRule::default(), "x").is_none(),
            "空白行不出语句"
        );
    }

    /// 视图「高级」两栏的 DDL 落点：安全屏障挂在 `AS` 之前（WITH 子句属于视图名后），
    /// 检查选项挂在查询之后；都不选时保持裸的 `CREATE VIEW … AS SELECT …`。
    #[test]
    fn design_view_sql_pg_places_barrier_and_check_option() {
        assert_eq!(
            design_view_sql_pg("\"public\".\"menu\"", "SELECT id FROM menus", "", false),
            "CREATE VIEW \"public\".\"menu\" AS\nSELECT id FROM menus;\n"
        );
        assert_eq!(
            design_view_sql_pg(
                "\"public\".\"menu\"",
                "SELECT id FROM menus",
                "local",
                true,
            ),
            "CREATE VIEW \"public\".\"menu\" WITH (security_barrier=true) AS\n\
             SELECT id FROM menus WITH LOCAL CHECK OPTION;\n"
        );
        assert!(
            design_view_sql_pg("\"v\"", "SELECT 1", "CASCADED", false)
                .ends_with("SELECT 1 WITH CASCADED CHECK OPTION;\n")
        );
        assert!(
            design_view_sql_pg("\"v\"", "", "LOCAL", true).starts_with("-- 在「定义」页写入 SELECT"),
            "空定义只出注释，不带 WITH"
        );
    }

    /// PG 视图定义之后的三条附属语句：注释尾注 → 属主 ALTER → 规则，
    /// 空的那几栏整条不出现；截图里语句之间空一行、属主一行写完（`ALTER TABLE`）。
    #[test]
    fn design_view_pg_tail_orders_comment_owner_and_rules() {
        let rule = DesignRule {
            name: "r_ins".into(),
            event: "INSERT".into(),
            action: "INSTEAD".into(),
            statement: "INSERT INTO log SELECT 1".into(),
            ..Default::default()
        };
        assert_eq!(
            design_view_pg_tail("\"public\".\"menu\"", "postgres", "菜单视图", &[rule.clone()]),
            "\nCOMMENT ON VIEW \"public\".\"menu\" IS '菜单视图';\n\n\
             ALTER TABLE \"public\".\"menu\" OWNER TO \"postgres\";\n\n\
             CREATE RULE \"r_ins\" AS ON INSERT TO \"public\".\"menu\" \
             DO INSTEAD INSERT INTO log SELECT 1;"
        );
        assert_eq!(design_view_pg_tail("\"v\"", "", "   ", &[]), "", "空栏不出语句");
        assert_eq!(
            design_view_pg_tail("\"v\"", "", "备注", &[DesignRule::default()]),
            "\nCOMMENT ON VIEW \"v\" IS '备注';",
            "空白规则行不算规则"
        );
    }

    /// SQLite 的 sqlite_master 存整条 CREATE VIEW，「定义」页只要 AS 之后那段：
    /// 头部的 AS 要在引号外（视图名可带引号），正文里的 `x AS y` 别名不算头部。
    #[test]
    fn strip_create_view_keeps_body_and_ignores_inner_as() {
        assert_eq!(
            strip_create_view("CREATE VIEW menu AS SELECT id FROM menus"),
            "SELECT id FROM menus"
        );
        assert_eq!(
            strip_create_view("create view \"my view\" AS SELECT a AS b FROM t"),
            "SELECT a AS b FROM t",
            "带引号的视图名 + 正文别名"
        );
        assert_eq!(
            strip_create_view("  CREATE VIEW \"v\"\"x\" AS SELECT 1  "),
            "SELECT 1",
            "视图名里的转义双引号不能当收尾"
        );
        assert_eq!(
            strip_create_view("SELECT 1"),
            "SELECT 1",
            "不是 CREATE 形态就原样返回"
        );
        assert_eq!(strip_create_view(""), "", "读不到就留空");
    }

