    /// 树底星标过滤：只开星标也算筛选生效（回归：tree_filter_active 漏了
    /// starred_only，星标点亮后树完全不过滤）；「定位到活动连接」发现目标
    /// 被星标藏住时，把星标开关一并清掉。
    #[gpui_kit::test]
    fn tree_starred_only_filter_and_locate_clears_it(cx: &mut TestAppContext) {
        isolate_store("starfilter");
        let (handle, app) = open_app(cx);
        app.update(cx, |a, _| {
            assert!(!a.tree_filter_active(), "初始无筛选");
            a.starred.insert("测试 SQL Server".into());
            a.starred_only = true;
            assert!(a.tree_filter_active(), "只开星标也应进入过滤态");
            assert!(a.conn_passes_filters(1), "星标连接保留");
            assert!(!a.conn_passes_filters(0), "未星标连接被过滤");
            assert!(!a.conn_passes_filters(3), "未星标连接被过滤（末位）");
        });
        // 打开未星标连接的表再「定位到活动连接」：星标应被自动清掉
        app.update(cx, |a, _| a.sel = Act::Obj(0, 0, NO_SCHEMA, 0, 0));
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.open_object(Act::Obj(0, 0, NO_SCHEMA, 0, 0), cx)
            });
            app.update(cx, |a, cx| a.locate_active_conn(window, cx));
            app.update(cx, |a, _| {
                assert!(!a.starred_only, "定位到被星标藏住的连接时清掉星标开关");
                assert!(a.conn_passes_filters(0), "定位的连接重新可见");
            });
        })
        .unwrap();
    }

    /// 连接颜色标签：设色后树和页签取到同一份派生色板，连接行 / 子树行分档，
    /// 「无」能清掉、越界下标不炸，明暗主题各出一套底色。回归的是
    /// 「菜单里选了颜色，界面却毫无变化」。
    #[gpui_kit::test]
    fn conn_color_tint_reaches_tree_and_tabs(cx: &mut TestAppContext) {
        isolate_store("conntint");
        let (handle, app) = open_app(cx);
        app.update(cx, |a, _| {
            let name = a.conns[0].name.clone();
            assert!(a.conn_tint_for(&name).is_none(), "默认没设颜色");
            a.set_conn_color(&name, Some(0)); // 红
            let tint = a.conn_tint_for(&name).expect("设色后拿到色板");
            // 页签按 OpenTab.conn_name 取色，走的就是这一个入口
            assert!(a.conn_tint_for(name.as_str()).is_some());
            assert_eq!(
                format!("{:?}", tint.solid),
                format!("{:?}", to_hsla(CONN_COLORS[0].1)),
                "页签色条用原色"
            );

            let base_ink = TreeInk {
                fg: to_hsla(0),
                muted: to_hsla(0),
                hover: to_hsla(0),
                focus_bg: to_hsla(0),
                hl: to_hsla(0),
                row_bg: None,
                selected: Act::Root,
            };
            let head = base_ink.tinted_header(tint);
            let rows = base_ink.tinted_rows(tint);
            assert!(base_ink.row_bg.is_none(), "没颜色的连接不铺底");
            assert!(head.row_bg.is_some() && rows.row_bg.is_some());
            assert_ne!(
                format!("{:?}", head.row_bg),
                format!("{:?}", rows.row_bg),
                "连接行饱和档与子树淡档必须分开"
            );

            a.set_conn_color(&name, Some(99));
            assert!(a.conn_tint_for(&name).is_none(), "越界下标不染色也不炸");
            a.set_conn_color(&name, None);
            assert!(a.conn_tint_for(&name).is_none(), "「无」清掉颜色");

            a.set_conn_color(&name, Some(4)); // 蓝
            let light = a.conn_tint_for(&name).unwrap();
            a.dark = true;
            let dark = a.conn_tint_for(&name).unwrap();
            assert_ne!(
                format!("{:?}", light.row),
                format!("{:?}", dark.row),
                "暗主题另出一档底色"
            );
            a.dark = false;
        });

        // 真渲染一帧：树行底色、页签色条 / 淡底都要能画出来
        app.update(cx, |a, _| {
            let name = a.conns[0].name.clone();
            a.set_conn_color(&name, Some(0));
            a.sel = Act::Conn(0);
        });
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| a.open_object(Act::Obj(0, 0, NO_SCHEMA, 0, 0), cx));
            window.render_frame(cx);
            app.update(cx, |a, _| {
                assert!(!a.opened.is_empty(), "表页签已打开");
                assert!(
                    a.conn_tint_for(&a.opened[0].conn_name).is_some(),
                    "页签按所属连接取到颜色"
                );
            });
        })
        .unwrap();
    }

    /// 对象面板搜索：点 🔍 展开输入框，输入即过滤当前分类的对象；
    /// 过滤只影响显示，原始下标仍指向全量清单（双击 / 右键取名字不受影响）。
    #[gpui_kit::test]
    fn object_panel_search_filters_list(cx: &mut TestAppContext) {
        isolate_store("objsearch");
        let (handle, app) = open_app(cx);
        // 启动时无选中（对象面板为空），先选中一个库让清单有内容
        app.update(cx, |a, _| a.sel = Act::Db(0, 0));
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            window.click("obj-search", cx);
        })
        .unwrap();
        cx.update_window(handle, |_, window, cx| {
            assert!(window.try_find("obj-search-input").is_some(), "搜索框展开");
            app.update(cx, |a, _| assert!(a.obj_search_open));
            // 点 🔍 时已把焦点交给输入框，直接键入
            window.input("sys_user_role", cx);
        })
        .unwrap();
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, _| {
                assert_eq!(a.obj_query, "sys_user_role");
                let vis = a.pane_objects_visible();
                assert_eq!(vis.len(), 1, "只剩命中的表");
                assert_eq!(vis[0].1, "sys_user_role");
                assert_eq!(a.pane_objects()[vis[0].0], "sys_user_role", "原始下标可回查");
                assert!(a.pane_objects().len() > 1, "全量清单没被改动");
            });
            // 点右端 × 收起：清词复原
            window.click("obj-search-close", cx);
        })
        .unwrap();
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, _| {
                assert!(!a.obj_search_open);
                assert!(a.obj_query.is_empty(), "收起时清空搜索词");
                assert_eq!(a.pane_objects_visible().len(), a.pane_objects().len());
            });
            window.render_frame(cx);
            assert!(window.try_find("obj-search-input").is_none(), "输入框退场");
            // 收起后按键不该落进已隐藏的输入框
            window.input("zzz", cx);
        })
        .unwrap();
        cx.update_window(handle, |_, _, cx| {
            app.update(cx, |a, _| assert!(a.obj_query.is_empty(), "隐藏输入框不再接收键入"));
        })
        .unwrap();
    }

    /// 动作条跟着对象面板分类换文案与动作：视图只出视图那一套，导入导出 /
    /// AI 新建表只在表分类出现；「新建」在视图分类开的是视图设计器。
    #[gpui_kit::test]
    fn object_action_bar_follows_category(cx: &mut TestAppContext) {
        use gpui_kit::test::TestQueryExt as _;
        isolate_store("actionbar");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, _| {
                // 实体化视图只属 PG：演示连接换成 PG，五类才都在可见性门内
                a.conns[0].kind = DbKind::PostgreSql;
                a.sel = Act::Cat(0, 0, NO_SCHEMA, 1);
            });
            window.render_frame(cx);
            for label in ["打开视图", "设计视图", "新建视图", "删除视图", "导出向导"] {
                assert!(window.try_find_by_label(label).is_some(), "缺「{label}」");
            }
            assert!(window.try_find_by_label("打开表").is_none(), "不残留表那一套");
            assert!(window.try_find_by_label("导入向导").is_none(), "导入只对表成立");
            assert!(window.try_find_by_label("通过 AI 新建表").is_none(), "AI 新建表只在表分类");

            app.update(cx, |a, _| a.sel = Act::Cat(0, 0, NO_SCHEMA, 0));
            window.render_frame(cx);
            for label in ["打开表", "设计表", "新建表", "删除表", "导入向导", "导出向导"] {
                assert!(window.try_find_by_label(label).is_some(), "缺「{label}」");
            }
            assert!(window.try_find_by_label("通过 AI 新建表").is_some());
            assert!(window.try_find_by_label("打开视图").is_none());

            app.update(cx, |a, _| a.sel = Act::Cat(0, 0, NO_SCHEMA, 2));
            window.render_frame(cx);
            assert!(window.try_find_by_label("导出向导").is_some(), "实体化视图也能导出");
            assert!(window.try_find_by_label("导入向导").is_none());

            // 函数分类：设计 / 新建 / 删除 / 运行，没有「打开函数」（参考界面这一套）
            app.update(cx, |a, _| a.sel = Act::Cat(0, 0, NO_SCHEMA, 3));
            window.render_frame(cx);
            for label in ["设计函数", "新建函数", "删除函数", "运行函数"] {
                assert!(window.try_find_by_label(label).is_some(), "缺「{label}」");
            }
            assert!(window.try_find_by_label("打开函数").is_none(), "函数没有单独的打开");
            assert!(window.try_find_by_label("导出向导").is_none());

            // 选中视图对象后「新建」开的是视图设计器（cat 1），不是表
            app.update(cx, |a, _| a.sel = Act::Obj(0, 0, NO_SCHEMA, 1, 0));
            window.render_frame(cx);
            window.click("act-new", cx);
            window.render_frame(cx);
            app.update(cx, |a, _| {
                let t = a.opened.last().expect("新建视图要开设计页签");
                assert!(t.design);
                assert_eq!(t.cat, 1, "新建的是视图");
                assert_eq!(t.obj, usize::MAX, "未命名，无目录项");
            });
        })
        .unwrap();
    }

