    #[gpui_kit::test]
    fn query_opens_from_ribbon_no_dedup(cx: &mut TestAppContext) {
        isolate_store("qopen");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            window.click("新建查询", cx);
            window.render_frame(cx);

            assert!(window.try_find("qedit").is_some(), "编辑器区已渲染");
            // 参考界面：没跑过查询时整块结果面板都不出现（查询页只有编辑区）
            assert!(window.try_find("qhead").is_none(), "未执行时没有结果面板");
            assert!(window.try_find("qtab/0").is_none(), "没出结果前没有结果页签");
            app.update(cx, |a, cx| {
                assert_eq!(a.opened.len(), 1);
                assert_eq!(a.active_tab, 1);
                let t = &a.opened[0];
                assert!(t.query);
                let q = t.qstate.as_ref().unwrap();
                assert_eq!((q.seq, q.db, q.schema, q.pane, q.dirty), (1, 0, 0, 0, false));
                assert_eq!(q.conn, "本地 MySQL", "无选中连接时取第一个");
                assert_eq!(q.editor.read(cx).value().to_string(), "");
            });

            // 参考界面习惯：每次触发都开新页签，不去重
            window.click("新建查询", cx);
            window.render_frame(cx);
            app.update(cx, |a, _| {
                assert_eq!(a.opened.len(), 2);
                assert_eq!(a.active_tab, 2);
                assert_eq!(a.opened[1].qstate.as_ref().unwrap().seq, 2);
            });

            // 选中连接 1（SQL Server）再开：运行上下文跟着选中走，库取第一个
            app.update(cx, |a, cx| {
                a.sel = Act::Conn(1);
                a.open_query_tab(None, window, cx);
            });
            app.update(cx, |a, _| {
                assert_eq!(a.opened.len(), 3);
                let (t, q) = (&a.opened[2], a.opened[2].qstate.as_ref().unwrap());
                assert_eq!(q.conn, "测试 SQL Server");
                // 运行上下文落在连接配置的库（master），不是清单第一条
                assert_eq!(t.db, "master");
                assert_eq!((q.db, q.schema), (1, 0));
            });

            // 上下文切换：连接变了落到那条连接配置的库；库 / 模式按下标落位
            app.update(cx, |a, cx| {
                let qid = a.opened[2].qid;
                a.query_set_conn(qid, "本地 MySQL", cx);
                let q = a.opened[2].qstate.as_ref().unwrap();
                assert_eq!(q.conn, "本地 MySQL");
                assert_eq!((q.db, q.schema), (0, 0));
                a.query_set_db(qid, "sys", cx);
                assert_eq!(a.opened[2].qstate.as_ref().unwrap().db, 5);
                a.query_set_conn(qid, "测试 SQL Server", cx);
                assert_eq!(
                    a.opened[2].qstate.as_ref().map(|q| (q.db, q.schema)),
                    Some((1, 0)),
                    "SQL Server 配置的库是 master（清单第 2 条）"
                );
                assert_eq!(a.opened[2].db, "master");
                a.query_set_schema(qid, "dbo", cx);
                assert_eq!(a.opened[2].qstate.as_ref().unwrap().schema, 0);
            });
        })
        .unwrap();
    }

    /// 新建查询默认落在左侧树最后激活的库 / 模式上（打开库、选中表都算），
    /// 而不是永远回到连接表单里的初始库；树选中项属于别的连接时不串库。
    #[gpui_kit::test]
    fn query_default_follows_tree_db(cx: &mut TestAppContext) {
        isolate_store("qtree");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);

            // 树最后激活「本地 MySQL / bx_mall」（清单第 2 条）
            app.update(cx, |a, cx| {
                a.sel = Act::Db(0, 1);
                a.open_query_tab(None, window, cx);
            });
            app.update(cx, |a, _| {
                let (t, q) = (&a.opened[0], a.opened[0].qstate.as_ref().unwrap());
                assert_eq!(q.conn, "本地 MySQL");
                assert_eq!((q.db, t.db), (1, "bx_mall"));
            });

            // 选中的是表（带库 / 模式坐标）也一样落在它所在的库
            app.update(cx, |a, cx| {
                a.sel = Act::Obj(0, 3, NO_SCHEMA, 0, 0);
                a.open_query_tab(None, window, cx);
            });
            app.update(cx, |a, _| {
                let (t, q) = (&a.opened[1], a.opened[1].qstate.as_ref().unwrap());
                assert_eq!((q.db, t.db), (3, "mysql"));
            });

            // SQL Server：树上的模式下标一并带过去；「public」不在清单里就用第 0 个
            app.update(cx, |a, cx| {
                a.sel = Act::Obj(1, 2, 0, 0, 0);
                a.open_query_tab(None, window, cx);
            });
            app.update(cx, |a, _| {
                let (t, q) = (&a.opened[2], a.opened[2].qstate.as_ref().unwrap());
                assert_eq!(q.conn, "测试 SQL Server");
                assert_eq!((q.db, q.schema, t.db), (2, 0, "model"));
            });

            // 树选中项属于另一条连接：不串库，退回这条连接配置的库
            app.update(cx, |a, cx| {
                a.sel = Act::Db(1, 3);
                a.open_query_tab(Some(0), window, cx);
            });
            app.update(cx, |a, _| {
                let (t, q) = (&a.opened[3], a.opened[3].qstate.as_ref().unwrap());
                assert_eq!(q.conn, "本地 MySQL");
                assert_eq!((q.db, t.db), (0, "bx11"));
            });
        })
        .unwrap();
    }

    #[gpui_kit::test]
    fn query_open_sql_text_in_new_tab(cx: &mut TestAppContext) {
        isolate_store("qopenfile");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                // BOM 是 Windows 记事本导出的常见前缀，载入时去掉
                let qid = a
                    .open_sql_text_in_new_query(
                        "\u{feff}SELECT 42;\nSELECT 43;",
                        None,
                        window,
                        cx,
                    )
                    .expect("没有页签时也按第一条连接开新查询页");
                assert_eq!(a.opened.len(), 1);
                assert_eq!(a.active_tab, 1);
                let t = &a.opened[0];
                assert_eq!(t.qid, qid);
                let q = t.qstate.as_ref().unwrap();
                assert_eq!(
                    q.editor.read(cx).value().to_string(),
                    "SELECT 42;\nSELECT 43;"
                );
                assert!(!q.dirty, "文件载入的内容不算未保存编辑");
                assert_eq!(q.conn, "本地 MySQL");

                // 已打开的查询页切到别的连接：打开文件沿用它的运行上下文
                a.query_set_conn(qid, "测试 SQL Server", cx);
                assert_eq!(a.sql_file_target_conn(), Some(1));
                let qid2 = a
                    .open_sql_text_in_new_query("SELECT 1;", a.sql_file_target_conn(), window, cx)
                    .expect("再开一页");
                assert_eq!(a.opened.len(), 2);
                assert_eq!(a.active_tab, 2);
                let q2 = a.opened[1].qstate.as_ref().unwrap();
                assert_eq!(q2.conn, "测试 SQL Server", "沿用当前查询页签的连接");
                assert_eq!(q2.editor.read(cx).value().to_string(), "SELECT 1;");
                assert_eq!(a.opened[1].qid, qid2);

                // 没有连接时返回 None（文件菜单在这之前先弹提示）
                a.conns.clear();
                assert_eq!(a.sql_file_target_conn(), None);
                assert_eq!(
                    a.open_sql_text_in_new_query("SELECT 1;", None, window, cx),
                    None
                );
            });
        })
        .unwrap();
    }

    #[gpui_kit::test]
    fn query_open_sql_file_path_in_new_tab(cx: &mut TestAppContext) {
        isolate_store("qopenpath");
        let path = std::env::temp_dir().join(format!(
            "daro_open_sql_{}_{}.sql",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_nanos())
                .unwrap_or(0)
        ));
        std::fs::write(&path, "\u{feff}SELECT 7;\nSELECT 8;").unwrap();
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.open_sql_path_in_editor(path.clone(), window, cx);
                assert_eq!(a.opened.len(), 1, "双击 / 拖入都落到新查询页签");
                let q = a.opened[0].qstate.as_ref().unwrap();
                assert_eq!(
                    q.editor.read(cx).value().to_string(),
                    "SELECT 7;\nSELECT 8;"
                );
                assert!(!q.dirty);
            });
        })
        .unwrap();
        let _ = std::fs::remove_file(&path);
    }

    #[gpui_kit::test]
    fn query_run_select_write_empty(cx: &mut TestAppContext) {
        isolate_store("qrun");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.open_query_tab(None, window, cx);
            });
        })
        .unwrap();

        // 点编辑器拿焦点，键入一条 SELECT
        cx.update_window(handle, |_, window, cx| {
            window.click("qedit", cx);
            window.input("SELECT 1", cx);
        })
        .unwrap();

        // 订阅回调走 effect 队列，冲刷发生在 update 边界 —— 模型断言另起一轮
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, cx| {
                let q = a.opened[0].qstate.as_ref().unwrap();
                assert_eq!(q.editor.read(cx).value().to_string(), "SELECT 1");
                assert!(q.dirty, "编辑过 → 页签标题前 *");
            });

            // 点「运行」主按钮（观察容器转发真点击）
            window.click_at("qrun-wrap", point(px(10.), px(11.)), cx);
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                let q = a.opened[0].qstate.as_ref().unwrap();
                assert_eq!(q.outcomes.len(), 1);
                let o = &q.outcomes[0];
                assert_eq!(o.sql, "SELECT 1");
                assert_eq!(o.result.as_ref().map(|r| r.len()), Some(mock::mock_row_count("SELECT 1")));
                assert_eq!(q.pane, 2, "执行完切到结果页签");
                let status = DaroApp::query_status_text(q);
                assert!(status.starts_with("执行成功 · "), "{status}");
                assert!(status.contains(" 行 · "), "{status}");
                assert!(q.started_at.is_some() && q.finished_at.is_some(), "摘要页有起止时间");
                let log = q.log.read(cx).value().to_string();
                assert!(log.starts_with("SELECT 1\n> OK\n> 查询时间: "), "{log}");
            });
            assert!(window.try_find("qtab/0").is_some(), "消息页签");
            assert!(window.try_find("qtab/1").is_some(), "摘要页签");
            assert!(window.try_find("qtab/2").is_some(), "结果 1 页签");
            assert!(window.try_find("qgrid-scroll/0").is_some());
            assert!(window.try_find("qcell/0/0/0").is_some());
            assert!(window.try_find("qfoot").is_some(), "结果底条");
            assert!(window.try_find("qmsg").is_none(), "网格页不渲染消息容器");

            // 结果页签条点回「消息」：网格退场、日志容器进场
            window.click("qtab/0", cx);
            window.render_frame(cx);
            assert!(window.try_find("qmsg").is_some());
            let msg = window.try_find("qmsg").unwrap();
            let log = window.try_find("qlog").expect("消息日志铺满容器");
            assert!(
                log.bounds().size.height >= msg.bounds().size.height - px(24.),
                "日志高度 {} 没铺满容器 {}",
                log.bounds().size.height,
                msg.bounds().size.height
            );
            assert!(window.try_find("qcell/0/0/0").is_none());
            app.update(cx, |a, _| {
                assert_eq!(a.opened[0].qstate.as_ref().unwrap().pane, 0)
            });

            // 「摘要」：本轮统计 + 每句一览 + 仅显示错误
            window.click("qtab/1", cx);
            window.render_frame(cx);
            assert!(window.try_find("qsummary").is_some(), "摘要页");
            assert!(window.try_find("qsum/only").is_some(), "仅显示错误");
            assert!(window.try_find("qcell/0/0/0").is_none(), "摘要页不渲染网格");

            // 结果页内层：数据 / 信息
            window.click("qtab/2", cx);
            window.render_frame(cx);
            assert!(window.try_find("qrsub/0").is_some(), "数据页签");
            assert!(window.try_find("qrsub/1").is_some(), "信息页签");
            window.click("qrsub/1", cx);
            window.render_frame(cx);
            assert!(window.try_find("qinfo").is_some(), "结果信息页");
            let (q_elapsed, q_conn) = app.update(cx, |a, _| {
                let q = a.opened[0].qstate.as_ref().unwrap();
                (q.outcomes[0].elapsed_ms, q.conn.clone())
            });
            for id in [
                "qinfo/ts",
                "qinfo/query",
                "qinfo/fetch",
                "qinfo/conn",
                "qinfo/db",
                "qinfo/schema",
                "qinfo/sql",
            ] {
                let node = window.try_find(id).unwrap_or_else(|| panic!("信息页缺 {id}"));
                assert!(node.bounds().size.width > px(0.), "{id} 宽度为 0");
                assert!(node.bounds().size.height > px(0.), "{id} 高度为 0");
            }
            assert_eq!(
                window.try_find("qinfo/conn").unwrap().label().as_deref(),
                Some(q_conn.as_str()),
                "连接名列显示当前连接"
            );
            assert_eq!(
                window.try_find("qinfo/query").unwrap().label().as_deref(),
                Some(query_secs_text(q_elapsed).as_str()),
                "查询时间只显示数值"
            );
            assert_eq!(
                window.try_find("qinfo/sql").unwrap().label().as_deref(),
                Some("SELECT 1"),
                "SQL 原文"
            );
            assert!(window.try_find("qcell/0/0/0").is_none());
            app.update(cx, |a, _| {
                assert_eq!(a.opened[0].qstate.as_ref().unwrap().result_sub, 1)
            });
            window.click("qrsub/0", cx);
            window.render_frame(cx);
            assert!(window.try_find("qcell/0/0/0").is_some(), "切回数据页");

            // 写操作：不出网格、不建结果页签，执行完直接展示摘要页（参考界面口径）
            app.update(cx, |a, cx| {
                let editor = a.opened[0].qstate.as_ref().unwrap().editor.clone();
                editor.update(cx, |s, cx| s.set_value("UPDATE t SET x = 1", window, cx));
            });
            window.click_at("qrun-wrap", point(px(10.), px(11.)), cx);
            window.render_frame(cx);
            app.update(cx, |a, _| {
                let q = a.opened[0].qstate.as_ref().unwrap();
                assert_eq!(q.outcomes.len(), 1);
                assert!(q.outcomes[0].result.is_none(), "mock 不执行写操作");
                assert_eq!(q.pane, 1, "全是写操作执行完落摘要页");
                let status = DaroApp::query_status_text(q);
                assert!(status.starts_with("演示数据 · 写操作未执行 · "), "{status}");
            });
            assert!(window.try_find("qtab/0").is_some(), "消息页签");
            assert!(window.try_find("qtab/1").is_some(), "摘要页签");
            assert!(window.try_find("qtab/2").is_none(), "写操作不建结果页签");
            assert!(window.try_find("qsummary").is_some(), "摘要页回报这条写操作");
            assert!(window.try_find("qcell/0/0/0").is_none());

            // 混合脚本：非查询语句不占结果页签，页签号按 outcomes 下标跳号；
            // 默认仍落最后一条有网格的结果。
            app.update(cx, |a, cx| {
                let editor = a.opened[0].qstate.as_ref().unwrap().editor.clone();
                editor.update(cx, |s, cx| {
                    s.set_value("SELECT 1;\nUPDATE t SET x = 1;\nSELECT 2;", window, cx)
                });
            });
            window.click_at("qrun-wrap", point(px(10.), px(11.)), cx);
            window.render_frame(cx);
            app.update(cx, |a, _| {
                let q = a.opened[0].qstate.as_ref().unwrap();
                assert_eq!(q.outcomes.len(), 3);
                assert!(q.outcomes[1].result.is_none(), "中间的写操作没有结果网格");
                assert_eq!(q.pane, 4, "落最后一条结果：outcomes[2] → pane 4");
            });
            assert_eq!(window.try_find("qtab/2").unwrap().label(), Some("结果 1"));
            assert!(window.try_find("qtab/3").is_none(), "写操作不建结果页签");
            assert_eq!(window.try_find("qtab/4").unwrap().label(), Some("结果 2"));
            assert!(window.try_find("qcell/2/0/0").is_some(), "结果页照常出网格");

            // 空脚本：出提示、清结果、撤页签条
            app.update(cx, |a, cx| {
                let editor = a.opened[0].qstate.as_ref().unwrap().editor.clone();
                editor.update(cx, |s, cx| s.set_value("   ", window, cx));
            });
            window.click_at("qrun-wrap", point(px(10.), px(11.)), cx);
            window.render_frame(cx);
            app.update(cx, |a, _| {
                let q = a.opened[0].qstate.as_ref().unwrap();
                assert!(q.outcomes.is_empty());
                assert_eq!(q.prompt, Some("请输入 SQL 语句"));
                assert_eq!(DaroApp::query_status_text(q), "请输入 SQL 语句");
            });
            assert!(window.try_find("qtab/0").is_none(), "清掉结果页签条");
            assert!(window.try_find("qmsg").is_none());
        })
        .unwrap();
    }

    /// 非查询 / 失败的语句没有结果网格：页签条只列有网格的语句，页签号仍按
    /// outcomes 下标（会跳号）；固定了无网格的旧结果也不白占一个页签。
    #[test]
    fn pane_tabs_skip_statements_without_result_grid() {
        let make = |sql: &str, result: Option<Vec<Vec<String>>>, pinned: bool, pin_seq: u64| {
            QueryOutcome {
                sql: sql.into(),
                result,
                columns: Vec::new(),
                message: None,
                elapsed_ms: 0,
                cell: (0, 0),
                sel: None,
                explain: false,
                pinned,
                pin_seq,
            }
        };
        let grid = || Some(vec![vec!["1".to_string()]]);
        let outcomes = vec![
            make("SELECT 1", grid(), false, 0),
            make("ALTER TABLE t ADD INDEX ix(a)", None, false, 0),
            make("SELECT 2", grid(), false, 0),
            make("UPDATE t SET x = 1", None, true, 1),
        ];
        let tabs = pane_tabs(&outcomes);
        assert_eq!(
            tabs.iter()
                .map(|(i, l, p)| (*i, l.as_str(), *p))
                .collect::<Vec<_>>(),
            vec![
                (0, "消息", false),
                (1, "摘要", false),
                (2, "结果 1", false),
                (4, "结果 2", false),
            ],
            "写操作不建页签，固定的无网格结果也不占位"
        );
        let only_ddl = pane_tabs(&[make("ALTER TABLE t ADD INDEX ix(a)", None, false, 0)]);
        assert_eq!(
            only_ddl
                .iter()
                .map(|(i, l, _)| (*i, l.as_str()))
                .collect::<Vec<_>>(),
            vec![(0, "消息"), (1, "摘要")],
            "整轮都是写操作时只剩消息 / 摘要两枚页签"
        );
    }

    /// 结果面板拖高：按下分隔条下拖，面板长高、编辑器压矮；上下都有夹紧。
    #[gpui_kit::test]
    fn query_result_panel_resizes_by_dragging_splitter(cx: &mut TestAppContext) {
        isolate_store("qpaneldrag");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| a.open_query_tab(None, window, cx));
        })
        .unwrap();
        cx.update_window(handle, |_, window, cx| {
            window.click("qedit", cx);
            window.input("SELECT 1", cx);
        })
        .unwrap();

        cx.update_window(handle, |_, window, cx| {
            window.click_at("qrun-wrap", point(px(10.), px(11.)), cx);
            window.render_frame(cx);
            let h0 = app.update(cx, |a, _| a.opened[0].qstate.as_ref().unwrap().panel_h);
            let grab = |window: &mut Window| {
                let b = window.find("qsplit").bounds();
                // 取证点取分隔条中段：左端那几像素被侧栏分栏缝压着，按下会被它吃掉。
                point(
                    b.origin.x + b.size.width * 0.5,
                    b.origin.y + b.size.height * 0.5,
                )
            };
            // 分隔条是结果面板的上沿：上拖跟手上移，面板等量长高、编辑器压矮。
            let from = grab(window);
            window.drag(from, point(from.x, from.y - px(120.)), cx);
            window.render_frame(cx);
            let h1 = app.update(cx, |a, _| a.opened[0].qstate.as_ref().unwrap().panel_h);
            assert!(
                (h1 - h0 - 120.).abs() <= 2.,
                "上拖 120 → 面板长高 120：{h0} → {h1}"
            );
            let y1 = window.find("qsplit").bounds().origin.y;
            assert!(
                (y1 - (from.y - px(120.))).abs() <= px(2.),
                "分隔条没跟手停在松手处：{} → {}",
                from.y,
                y1
            );
            app.update(cx, |a, _| {
                assert!(a.q_panel_drag.is_none(), "松手后拖动瞬态收掉");
            });
            assert!(
                window.try_find("qpanel-capture").is_none(),
                "拖动结束撤掉捕获层"
            );

            // 再下拖 200：压回 100 以上，只到下限 120（300+120-200=220，未夹紧）
            let from2 = grab(window);
            window.drag(from2, point(from2.x, from2.y + px(200.)), cx);
            window.render_frame(cx);
            let h2 = app.update(cx, |a, _| a.opened[0].qstate.as_ref().unwrap().panel_h);
            assert!((h2 - (h1 - 200.)).abs() <= 2., "下拖 200 → 面板压矮 200：{h1} → {h2}");
            let y2 = window.find("qsplit").bounds().origin.y;
            assert!(
                (y2 - (from2.y + px(200.))).abs() <= px(2.),
                "下拖后分隔条没跟手：{} → {}",
                from2.y,
                y2
            );
        })
        .unwrap();

        // 夹紧：往上拖到底停在给编辑器留余量的上限，往下拖到底停在下限 120。
        let qid = app.update(cx, |a, _| a.opened[0].qid);
        app.update(cx, |a, cx| {
            let h = a.opened[0].qstate.as_ref().unwrap().panel_h;
            a.q_panel_resize_begin(qid, 0., h, cx);
            a.q_panel_resize_move(-(a.viewport_h * 4.), cx);
            let max = a.opened[0].qstate.as_ref().unwrap().panel_h;
            assert!(
                max <= a.viewport_h - 200.,
                "上限挤不掉编辑器: {max} / 窗口 {}",
                a.viewport_h
            );
            a.q_panel_resize_move(a.viewport_h * 4., cx);
            let min = a.opened[0].qstate.as_ref().unwrap().panel_h;
            assert!((min - 120.).abs() <= 0.5, "下限 120: {min}");
            a.q_panel_resize_end(cx);
            assert!(a.q_panel_drag.is_none(), "收尾清瞬态");
        });
    }

    /// 设计器里网格与属性面板之间那八条缝：按下就拖，缝跟着指针走，属性面板等量
    /// 增减；拖出来的高按子页各存一份，切来切去互不干扰。
    #[gpui_kit::test]
    fn designer_props_seam_resizes_per_subpage(cx: &mut TestAppContext) {
        isolate_store("propseam");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.open_designer(Act::Obj(0, 0, NO_SCHEMA, 0, 0), window, cx)
            });
            window.render_frame(cx);

            let stored = |a: &DaroApp, slot: u32| -> Option<f32> {
                a.opened[0].dstate.as_ref().unwrap().props_h.get(&slot).copied()
            };
            // 没拖过：不落盘，属性面板保持固有高
            app.update(cx, |a, _| {
                assert!(stored(a, D_SPLIT_FIELDS).is_none(), "未拖过不留值");
            });
            let grab = |window: &mut Window, slot: u32| {
                let b = window.find(format!("dsplit-{slot}")).bounds();
                // 取中段：左端那几像素被侧栏分栏缝压着，按下会被它吃掉。
                point(
                    b.origin.x + b.size.width * 0.5,
                    b.origin.y + b.size.height * 0.5,
                )
            };

            // 缝是属性面板的上沿：上拖 120 缝跟着上移，面板等量长高
            let y0 = window.find("dsplit-0").bounds().origin.y;
            let from = grab(window, 0);
            window.drag(from, point(from.x, from.y - px(120.)), cx);
            window.render_frame(cx);
            let y1 = window.find("dsplit-0").bounds().origin.y;
            assert!(
                (y1 - (from.y - px(120.))).abs() <= px(2.),
                "缝没跟手上移：{y0} → {y1}"
            );
            let h_up = app.update(cx, |a, _| stored(a, D_SPLIT_FIELDS).unwrap());
            assert!(h_up > 0., "上拖后面板高落盘: {h_up}");
            app.update(cx, |a, _| assert!(a.d_prop_drag.is_none(), "松手后拖动瞬态收掉"));
            assert!(
                window.try_find("dprop-capture").is_none(),
                "拖动结束撤掉捕获层"
            );

            // 再下拖 120 回到原处：说明加减没记错方向，也没漏累积
            let from2 = grab(window, 0);
            window.drag(from2, point(from2.x, from2.y + px(120.)), cx);
            window.render_frame(cx);
            let y2 = window.find("dsplit-0").bounds().origin.y;
            let h_back = app.update(cx, |a, _| stored(a, D_SPLIT_FIELDS).unwrap());
            assert!(
                (y2 - y0).abs() <= px(3.),
                "来回一趟缝没回到原处：{y0} → {y2}"
            );
            assert!(
                (h_back - (h_up - 120.)).abs() <= 3.,
                "面板高没跟着回到固有值：{h_up} → {h_back}"
            );

            // 换到「索引」子页拖一把：那边另存一份，字段页那份不动
            window.click("dsub/1", cx);
            window.render_frame(cx);
            assert!(window.try_find("dsplit-1").is_some(), "索引子页也有可拖的缝");
            let from3 = grab(window, 1);
            window.drag(from3, point(from3.x, from3.y - px(80.)), cx);
            window.render_frame(cx);
            app.update(cx, |a, _| {
                let idx = stored(a, D_SPLIT_INDEX).unwrap();
                let fields = stored(a, D_SPLIT_FIELDS).unwrap();
                assert!(idx > 0., "索引页单独存一份: {idx}");
                assert_eq!(fields, h_back, "字段页那份没被动过");
            });

            // 夹紧：推到极远都停在上下限，上限别把整块网格挤没
            let did = app.update(cx, |a, _| a.opened[0].did);
            app.update(cx, |a, cx| {
                let h = stored(a, D_SPLIT_INDEX).unwrap();
                a.d_prop_resize_begin(did, D_SPLIT_FIELDS, 0., h, cx);
                a.d_prop_resize_move(a.viewport_h * 4., cx);
                let min = stored(a, D_SPLIT_FIELDS).unwrap();
                assert!((min - D_PROPS_MIN_H).abs() <= 0.5, "下限 {min}");
                a.d_prop_resize_move(-(a.viewport_h * 4.), cx);
                let max = stored(a, D_SPLIT_FIELDS).unwrap();
                assert!(
                    max <= a.viewport_h - 200.,
                    "上限挤不掉网格: {max} / 窗口 {}",
                    a.viewport_h
                );
                a.d_prop_resize_end(cx);
                assert!(a.d_prop_drag.is_none(), "收尾清瞬态");
            });
        })
        .unwrap();
    }

    /// 固定结果：重新执行时冻结保留并排到最左，页签改名「固定 N」；
    /// 新结果另起「结果 1」；取消固定后回到普通顺序与编号。
    #[gpui_kit::test]
    fn query_pin_result_keeps_across_rerun(cx: &mut TestAppContext) {
        isolate_store("qpin");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| a.open_query_tab(None, window, cx));
        })
        .unwrap();

        // 跑一条 SELECT
        cx.update_window(handle, |_, window, cx| {
            window.click("qedit", cx);
            window.input("SELECT 1", cx);
            window.click_at("qrun-wrap", point(px(10.), px(11.)), cx);
            window.render_frame(cx);
        })
        .unwrap();
        app.update(cx, |a, _| {
            let q = a.opened[0].qstate.as_ref().unwrap();
            assert_eq!(q.outcomes.len(), 1);
            assert_eq!(q.pane, 2);
            assert!(!q.outcomes[0].pinned);
        });
        cx.update_window(handle, |_, window, _| {
            assert_eq!(window.try_find("qtab/2").unwrap().label(), Some("结果 1"));
        })
        .unwrap();

        // 点「固定」：页签改名并排到最左，当前页不变
        cx.update_window(handle, |_, window, cx| {
            window.click("qr/pin", cx);
            window.render_frame(cx);
        })
        .unwrap();
        app.update(cx, |a, _| {
            let q = a.opened[0].qstate.as_ref().unwrap();
            assert!(q.outcomes[0].pinned, "固定后状态落在结果上");
            assert_eq!((q.outcomes[0].pin_seq, q.pin_counter), (1, 1));
            assert_eq!(q.pane, 2, "固定不切换页签");
        });
        cx.update_window(handle, |_, window, _| {
            assert_eq!(window.try_find("qtab/2").unwrap().label(), Some("固定 1"));
            let pin_x = window.try_find("qtab/2").unwrap().bounds().origin.x;
            let msg_x = window.try_find("qtab/0").unwrap().bounds().origin.x;
            assert!(pin_x < msg_x, "固定页签应在消息前：{pin_x} < {msg_x}");
        })
        .unwrap();

        // 改 SQL 再跑：固定结果冻结在最左，新结果另起「结果 1」
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, cx| {
                let editor = a.opened[0].qstate.as_ref().unwrap().editor.clone();
                editor.update(cx, |s, cx| s.set_value("SELECT 2", window, cx));
            });
            window.click_at("qrun-wrap", point(px(10.), px(11.)), cx);
            window.render_frame(cx);
        })
        .unwrap();
        app.update(cx, |a, _| {
            let q = a.opened[0].qstate.as_ref().unwrap();
            assert_eq!(q.outcomes.len(), 2);
            assert_eq!(q.outcomes[0].sql, "SELECT 1", "固定结果冻结保留");
            assert!(q.outcomes[0].pinned);
            assert_eq!(q.outcomes[1].sql, "SELECT 2");
            assert!(!q.outcomes[1].pinned);
            assert_eq!(q.pane, 3, "当前页指到新结果");
        });
        cx.update_window(handle, |_, window, _| {
            assert_eq!(window.try_find("qtab/2").unwrap().label(), Some("固定 1"));
            assert_eq!(
                window.try_find("qtab/3").unwrap().label(),
                Some("结果 1"),
                "固定页签不占普通结果编号"
            );
            let pin_x = window.try_find("qtab/2").unwrap().bounds().origin.x;
            let msg_x = window.try_find("qtab/0").unwrap().bounds().origin.x;
            let new_x = window.try_find("qtab/3").unwrap().bounds().origin.x;
            assert!(pin_x < msg_x, "固定页签在最左：{pin_x} < {msg_x}");
            assert!(msg_x < new_x, "新结果排在消息 / 摘要之后：{msg_x} < {new_x}");
        })
        .unwrap();

        // 取消固定：回到普通顺序与编号
        cx.update_window(handle, |_, window, cx| {
            window.click("qtab/2", cx);
            window.render_frame(cx);
            window.click("qr/pin", cx);
            window.render_frame(cx);
        })
        .unwrap();
        app.update(cx, |a, _| {
            let q = a.opened[0].qstate.as_ref().unwrap();
            assert!(!q.outcomes[0].pinned);
            assert_eq!(q.outcomes[0].pin_seq, 0);
            assert_eq!(q.pane, 2);
        });
        cx.update_window(handle, |_, window, _| {
            assert_eq!(window.try_find("qtab/2").unwrap().label(), Some("结果 1"));
            assert_eq!(window.try_find("qtab/3").unwrap().label(), Some("结果 2"));
            let msg_x = window.try_find("qtab/0").unwrap().bounds().origin.x;
            let r1_x = window.try_find("qtab/2").unwrap().bounds().origin.x;
            assert!(msg_x < r1_x, "取消固定后结果回到消息之后：{msg_x} < {r1_x}");
        })
        .unwrap();
    }

    #[gpui_kit::test]
    fn query_run_selected_only(cx: &mut TestAppContext) {
        isolate_store("qsel");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.open_query_tab(None, window, cx);
            });
            window.click("qedit", cx);
            window.input("SELECT 11;\nSELECT 22;", cx);
            window.render_frame(cx);
            assert!(
                window.try_find_by_label("运行").is_some(),
                "无选区时主按钮是「运行」"
            );
            assert!(
                window.try_find_by_label("解释").is_some(),
                "无选区时解释按钮是「解释」"
            );
        })
        .unwrap();

        cx.update_window(handle, |_, window, cx| {
            // 光标回行首 + shift-end：只选中第一条
            window.press("ctrl-home", cx);
            window.press("shift-end", cx);
            window.render_frame(cx);
        })
        .unwrap();
        // 观察者回调挂在 effect 队列上，推一轮把选区状态落到 QueryState
        cx.run_until_parked();

        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, cx| {
                let q = a.opened[0].qstate.as_ref().unwrap();
                assert_eq!(
                    q.editor.read(cx).selected_text().to_string(),
                    "SELECT 11;",
                    "选区落在第一条语句上"
                );
            });
            window.render_frame(cx);
            window.render_frame(cx);
            app.update(cx, |a, _| {
                let q = a.opened[0].qstate.as_ref().unwrap();
                assert!(q.has_selection, "选区状态已写回");
            });
            assert!(
                window.try_find_by_label("运行已选择的").is_some(),
                "有选区时主按钮自动变成「运行已选择的」"
            );
            assert!(
                window.try_find_by_label("解释已选择的").is_some(),
                "有选区时解释按钮自动变成「解释已选择的」"
            );
            assert!(
                window.try_find("qrun-caret").is_none(),
                "有选区时不再给运行下拉箭头（参考截图）"
            );

            // 有选区时主按钮 = 「运行已选择的」：只跑选区
            window.click_at("qrun-wrap", point(px(10.), px(11.)), cx);
            app.update(cx, |a, _| {
                let q = a.opened[0].qstate.as_ref().unwrap();
                assert_eq!(q.outcomes.len(), 1, "只执行了选中的那条");
                assert_eq!(q.outcomes[0].sql, "SELECT 11");
                assert!(q.outcomes[0].result.is_some());
            });
        })
        .unwrap();
    }

    /// 运行下拉按参考截图：运行 / 运行当前语句 / 遇到错误时继续；
    /// Ctrl+R 跑选区或整篇，Ctrl+Shift+R 跑光标所在语句。
    #[gpui_kit::test]
    fn query_run_menu_current_statement_and_shortcuts(cx: &mut TestAppContext) {
        isolate_store("qrunmenu");
        let (handle, app) = open_app(cx);
        cx.update(|cx| wire_global_keys(app.clone(), handle, cx));
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| a.open_query_tab(None, window, cx));
            window.click("qedit", cx);
            window.input("SELECT 11;\nSELECT 22;", cx);
            window.render_frame(cx);
        })
        .unwrap();

        // 无选区：箭头在，菜单三项齐全
        cx.update_window(handle, |_, window, cx| {
            assert!(window.try_find("qrun-caret").is_some(), "无选区时运行按钮带下拉");
            window.click("qrun-caret", cx);
            window.render_frame(cx);
            assert!(window.try_find("qpm/run").is_some(), "运行");
            assert!(window.try_find("qpm/run-stmt").is_some(), "运行当前语句");
            assert!(window.try_find("qpm/run-continue").is_some(), "遇到错误时继续");
        })
        .unwrap();

        // 「遇到错误时继续」是可勾选项：点一下写回状态并收起菜单
        cx.update_window(handle, |_, window, cx| {
            assert!(
                !app.update(cx, |a, _| a.opened[0]
                    .qstate
                    .as_ref()
                    .unwrap()
                    .continue_on_error),
                "默认不勾：遇错即停（参考界面口径）"
            );
            window.click("qpm/run-continue", cx);
            window.render_frame(cx);
            assert!(app.update(cx, |a, _| a.opened[0]
                .qstate
                .as_ref()
                .unwrap()
                .continue_on_error));
            assert!(window.try_find("qpopup").is_none(), "勾选后菜单收起");
        })
        .unwrap();

        // 光标停在第二条：Ctrl+Shift+R 只跑当前语句
        cx.update_window(handle, |_, window, cx| {
            window.click("qedit", cx);
            window.press("ctrl-shift-r", cx);
            window.render_frame(cx);
        })
        .unwrap();
        cx.run_until_parked();
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, _| {
                let q = a.opened[0].qstate.as_ref().unwrap();
                assert_eq!(q.outcomes.len(), 1, "只跑光标所在的那条");
                assert_eq!(q.outcomes[0].sql, "SELECT 22");
            });

            // 无选区：Ctrl+R 跑整篇
            window.press("ctrl-r", cx);
            window.render_frame(cx);
        })
        .unwrap();
        cx.run_until_parked();
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, _| {
                let q = a.opened[0].qstate.as_ref().unwrap();
                assert_eq!(
                    q.outcomes.iter().map(|o| o.sql.as_str()).collect::<Vec<_>>(),
                    vec!["SELECT 11", "SELECT 22"],
                    "Ctrl+R 跑整篇"
                );
            });

            // 有选区：Ctrl+R 只跑选区
            window.click("qedit", cx);
            window.press("ctrl-home", cx);
            window.press("shift-end", cx);
        })
        .unwrap();
        cx.run_until_parked();
        cx.update_window(handle, |_, window, cx| {
            window.press("ctrl-r", cx);
            window.render_frame(cx);
        })
        .unwrap();
        cx.run_until_parked();
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, _| {
                let q = a.opened[0].qstate.as_ref().unwrap();
                assert_eq!(q.outcomes.len(), 1, "有选区时 Ctrl+R 只跑选区");
                assert_eq!(q.outcomes[0].sql, "SELECT 11");
            });
        })
        .unwrap();
    }

    // ── 数据网格列头排序（E节）─────────────────────────────────────

    #[test]
    fn table_sort_pure_functions() {
        use std::cmp::Ordering;
        // 数值列按数值比："999" 要排在 "1002" 前面
        assert_eq!(compare_cells("999", "1002", true), Ordering::Less);
        assert_eq!(compare_cells("1002", "999", true), Ordering::Greater);
        assert_eq!(compare_cells("42", "42.0", true), Ordering::Equal);
        // 数值列里混进非数值：退回字符串比
        assert_eq!(compare_cells("abc", "abd", true), Ordering::Less);
        assert_eq!(compare_cells("b", "a", false), Ordering::Greater);

        // 无排序：恒等映射
        let data: Vec<Vec<String>> = (0..5)
            .map(|r| {
                (0..mock::MOCK_COLUMNS.len())
                    .map(|c| mock::mock_cell("orders", r, c).to_string())
                    .collect()
            })
            .collect();
        let cols: Vec<db_types::ColMeta> = mock::MOCK_COLUMNS
            .iter()
            .map(|m| db_types::ColMeta::new(m.name, m.ty, m.numeric))
            .collect();
        assert_eq!(sorted_row_order(&data, &cols, None), vec![0, 1, 2, 3, 4]);

        // flags 列（值 = 行号 % 3）升序：0/1/2 三组，组内保持原行序（稳定）
        let rows = mock::mock_row_count("orders");
        let data: Vec<Vec<String>> = (0..rows)
            .map(|r| {
                (0..mock::MOCK_COLUMNS.len())
                    .map(|c| mock::mock_cell("orders", r, c).to_string())
                    .collect()
            })
            .collect();
        let flag = |row: &Vec<String>| row[6].parse::<i64>().unwrap();
        let asc = sorted_row_order(&data, &cols, Some((6, true)));
        assert_eq!(asc.len(), rows);
        for w in asc.windows(2) {
            let (a, b) = (flag(&data[w[0]]), flag(&data[w[1]]));
            assert!(a <= b, "升序被破坏: {w:?}");
            if a == b {
                assert!(w[0] < w[1], "同值行乱了原相对次序: {w:?}");
            }
        }
        // 降序：键反序，组内仍按原行序
        let desc = sorted_row_order(&data, &cols, Some((6, false)));
        for w in desc.windows(2) {
            let (a, b) = (flag(&data[w[0]]), flag(&data[w[1]]));
            assert!(a >= b, "降序被破坏: {w:?}");
            if a == b {
                assert!(w[0] < w[1], "同值行乱了原相对次序: {w:?}");
            }
        }
        // 同一输入恒定
        assert_eq!(asc, sorted_row_order(&data, &cols, Some((6, true))));
        // 列下标越界：防御性恒等
        assert_eq!(sorted_row_order(&data[..4], &cols, Some((99, true))), vec![0, 1, 2, 3]);
    }

    /// 表格首列（行首槽）：点一下选中整行，当前列保持不变。
    #[gpui_kit::test]
    fn table_grid_gutter_selects_row(cx: &mut TestAppContext) {
        isolate_store("gridgutter");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.open_object(Act::Obj(0, 0, NO_SCHEMA, 0, 0), cx);
            });
            window.render_frame(cx);

            // 几何：行首槽顶边和列头底边严丝合缝（强调条压边、不占额外高度）
            let head = window.find("th/0");
            let gutter = window.find("rowgutter/0");
            let dy = gutter.bounds().origin.y.as_f32() - head.bounds().bottom().as_f32();
            assert!(dy.abs() < 0.5, "行首槽与表头底边错位: dy={dy}");

            // 先把当前格挪到第 3 列，点行首槽后列位不能跟着变
            window.click("cell/0/2", cx);
            app.update(cx, |a, _| assert_eq!(a.opened[0].cell, (0, 2)));
            window.render_frame(cx);

            window.click("rowgutter/1", cx);
            app.update(cx, |a, _| {
                assert_eq!(a.opened[0].cell, (1, 2), "点行首槽选中整行、当前列不变");
            });

            // shift 点行首槽：从锚点行 1 扩到 3，整行铺满
            let last = app.read_with(cx, |a, _| a.opened[0].cols.len() - 1);
            window.click_with_modifiers(
                "rowgutter/3",
                Modifiers {
                    shift: true,
                    ..Default::default()
                },
                cx,
            );
            app.update(cx, |a, _| {
                let t = &a.opened[0];
                assert_eq!(t.sel.map(|s| s.rect()), Some((1, 0, 3, last)), "shift 扩整行");
                assert_eq!(t.cell, (3, 2), "当前列仍不动");
            });

            // 从行首槽拖到另一行：整行选区跟着扩
            window.drag_to("rowgutter/0", "rowgutter/2", cx);
            app.update(cx, |a, _| {
                let t = &a.opened[0];
                assert_eq!(t.sel.map(|s| s.rect()), Some((0, 0, 2, last)), "拖行首槽扩整行");
                assert_eq!(t.cell, (2, 2));
            });
        })
        .unwrap();
    }

    /// 列头悬停「…」：只在悬停列画按钮；移入相邻列时 leave 晚于 enter
    /// 到达也不能把新列的悬停清掉。
    #[gpui_kit::test]
    fn table_header_hover_shows_column_menu(cx: &mut TestAppContext) {
        isolate_store("gridheadhover");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.open_object(Act::Obj(0, 0, NO_SCHEMA, 0, 0), cx);
            });
            window.render_frame(cx);

            assert!(
                window.try_find("thmenu/1").is_none(),
                "没悬停不画「…」按钮"
            );
            window.hover("th/1", cx);
            window.render_frame(cx);
            assert!(window.try_find("thmenu/1").is_some(), "悬停列画「…」按钮");
            assert!(window.try_find("thmenu/0").is_none(), "按钮只画一列");
            app.update(cx, |a, _| assert_eq!(a.opened[0].head_hover, Some(1)));

            window.hover("th/2", cx);
            window.render_frame(cx);
            assert!(window.try_find("thmenu/2").is_some(), "悬停迁移到新列");
            assert!(window.try_find("thmenu/1").is_none(), "旧列按钮收掉");
            app.update(cx, |a, _| assert_eq!(a.opened[0].head_hover, Some(2)));

            // 点「…」要真把菜单弹出来；再点一次收掉（无头层浮层不参与命中，菜单项的点击走真窗取证）
            window.click("thmenu/2", cx);
            window.render_frame(cx);
            assert!(window.try_find("thmi/2/asc").is_some(), "菜单弹出且有升序项");
            assert!(window.try_find("thmi/2/filter").is_some(), "菜单里有添加筛选");
            window.click("thmenu/2", cx);
            window.render_frame(cx);
            assert!(
                window.try_find("thmi/2/asc").is_none(),
                "再点一次「…」菜单收掉"
            );
        })
        .unwrap();
    }

    #[test]
    fn table_grid_selection_math_and_drop_slot() {
        let s = GridSel {
            anchor: (5, 3),
            focus: (1, 0),
        };
        assert_eq!(s.rect(), (1, 0, 5, 3));
        assert!(s.contains(3, 2));
        assert!(!s.contains(0, 2));

        // 落点以相邻列中线为界：[100, 60, 80]
        assert_eq!(grid_drop_slot(&[100., 60., 80.], 0, 20.), 0);
        assert_eq!(grid_drop_slot(&[100., 60., 80.], 0, 40.), 1);
        assert_eq!(grid_drop_slot(&[100., 60., 80.], 0, 110.), 2);
        assert_eq!(grid_drop_slot(&[100., 60., 80.], 2, -20.), 2);
        assert_eq!(grid_drop_slot(&[100., 60., 80.], 2, -50.), 1);
        assert_eq!(grid_drop_slot(&[100., 60., 80.], 2, -130.), 0);
    }

    /// Delete 只清选中格内容（含行首整行选中）；删记录走 Ctrl+Delete。
    /// 走真实键位绑定（同 main 的 wire_global_keys），不是直接调方法。
    #[gpui_kit::test]
    fn table_grid_delete_clears_cells_and_ctrl_delete_removes_rows(cx: &mut TestAppContext) {
        isolate_store("griddelete");
        let (handle, app) = open_app(cx);
        cx.update(|cx| wire_global_keys(app.clone(), handle, cx));
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.open_object(Act::Obj(0, 0, NO_SCHEMA, 0, 0), cx);
            });
            window.render_frame(cx);
        })
        .unwrap();
        let rows = app.update(cx, |a, _| a.opened[0].data.len());
        assert!(rows >= 3, "演示表至少三行");

        // 单格选中 + Delete：只清这一格，行数不变
        cx.update_window(handle, |_, window, cx| {
            window.click("cell/2/1", cx);
            window.press("delete", cx);
        })
        .unwrap();
        app.update(cx, |a, _| {
            let t = &a.opened[0];
            assert_eq!(t.data.len(), rows, "Delete 不删行");
            assert_eq!(t.data[2][1], "", "选中格清空");
            assert!(t.dirty(), "清空内容算未应用的修改");
        });

        // 行首槽整行选中 + Delete：整行内容清空，仍不删行
        cx.update_window(handle, |_, window, cx| {
            window.click("rowgutter/1", cx);
            window.press("delete", cx);
        })
        .unwrap();
        app.update(cx, |a, _| {
            let t = &a.opened[0];
            assert_eq!(t.data.len(), rows, "整行选中时 Delete 也不删行");
            assert!(t.data[1].iter().all(String::is_empty), "整行清空");
        });

        // 块选 + Ctrl+Delete：删掉选区覆盖的两行
        cx.update_window(handle, |_, window, cx| {
            window.click("cell/0/0", cx);
            window.click_with_modifiers(
                "cell/1/1",
                Modifiers {
                    shift: true,
                    ..Default::default()
                },
                cx,
            );
            window.press("ctrl-delete", cx);
        })
        .unwrap();
        app.update(cx, |a, _| {
            assert_eq!(a.opened[0].data.len(), rows - 2, "选区覆盖的行整行删除");
        });
    }

    /// 拖选 / shift 扩选 / 全选 / 复制粘贴。
    #[gpui_kit::test]
    fn table_grid_multiselect_copy_paste(cx: &mut TestAppContext) {
        isolate_store("gridsel");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.open_object(Act::Obj(0, 0, NO_SCHEMA, 0, 0), cx);
            });
            window.render_frame(cx);
        })
        .unwrap();

        // 拖选：cell/0/0 → cell/2/2
        cx.update_window(handle, |_, window, cx| {
            window.drag_to("cell/0/0", "cell/2/2", cx);
        })
        .unwrap();
        app.update(cx, |a, _| {
            let t = &a.opened[0];
            assert_eq!(t.cell, (2, 2), "拖选后最深格跟到松手处");
            assert_eq!(t.sel.map(|s| s.rect()), Some((0, 0, 2, 2)));
        });

        // shift 点击：从原锚点扩到 (4,3)
        cx.update_window(handle, |_, window, cx| {
            window.click_with_modifiers(
                "cell/4/3",
                Modifiers {
                    shift: true,
                    ..Default::default()
                },
                cx,
            );
        })
        .unwrap();
        app.update(cx, |a, _| {
            let t = &a.opened[0];
            assert_eq!(t.cell, (4, 3));
            assert_eq!(t.sel.map(|s| s.rect()), Some((0, 0, 4, 3)));
        });

        // 复制选区：TSV，行 / 列都按显示序
        let expected = app.update(cx, |a, _| {
            let t = &a.opened[0];
            (0..5)
                .map(|r| {
                    (0..4)
                        .map(|c| t.data[r][c].clone())
                        .collect::<Vec<_>>()
                        .join("\t")
                })
                .collect::<Vec<_>>()
                .join("\n")
        });
        app.update(cx, |a, cx| a.grid_copy(cx));
        let copied = app.update(cx, |_, cx| {
            cx.read_from_clipboard().and_then(|i| i.text()).unwrap()
        });
        assert_eq!(copied, expected);

        // 粘贴：2×2 文本覆盖到 cell/6/1 起
        cx.update_window(handle, |_, window, cx| {
            window.click("cell/6/1", cx);
            cx.write_to_clipboard(gpui::ClipboardItem::new_string("x\ty\nz\tw".into()));
        })
        .unwrap();
        app.update(cx, |a, cx| a.grid_paste(cx));
        app.update(cx, |a, _| {
            let t = &a.opened[0];
            assert_eq!(t.data[6][1], "x");
            assert_eq!(t.data[6][2], "y");
            assert_eq!(t.data[7][1], "z");
            assert_eq!(t.data[7][2], "w");
            assert_eq!(t.cell, (6, 1), "当前格落在粘贴区左上角");
            assert_eq!(
                t.sel.map(|s| s.rect()),
                Some((6, 1, 7, 2)),
                "粘贴区整体框住，一眼看到落了哪几格"
            );
            assert!(t.dirty(), "粘贴改了工作集");
        });

        // 全选：整个网格（不只当前页）
        app.update(cx, |a, cx| a.grid_select_all(cx));
        let rows_total = app.update(cx, |a, _| {
            let t = &a.opened[0];
            let rows = t.data.len() + t.inserted.len();
            assert_eq!(
                t.sel.map(|s| s.rect()),
                Some((0, 0, rows - 1, t.cols.len() - 1))
            );
            rows
        });

        // 复制为 INSERT：块选里的每一行都进 VALUES，不再只取当前行
        app.update(cx, |a, cx| a.copy_as_insert(cx));
        let sql = app.update(cx, |_, cx| {
            cx.read_from_clipboard().and_then(|i| i.text()).unwrap()
        });
        assert_eq!(
            sql.matches("), (").count() + 1,
            rows_total,
            "INSERT 覆盖整个块选：{sql}"
        );
    }

    /// 外部文本粘贴超出末行：多出来的部分补成待新增行，不再被吞掉。
    #[gpui_kit::test]
    fn grid_paste_extends_past_last_row(cx: &mut TestAppContext) {
        isolate_store("gridpastegrow");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.open_object(Act::Obj(0, 0, NO_SCHEMA, 0, 0), cx);
            });
            window.render_frame(cx);
        })
        .unwrap();
        let rows = app.update(cx, |a, _| a.opened[0].data.len());
        assert!(rows > 0);
        app.update(cx, |a, _| {
            a.opened[0].cell = (rows - 1, 0);
            a.opened[0].sel = None;
        });
        cx.update_window(handle, |_, _, cx| {
            cx.write_to_clipboard(gpui::ClipboardItem::new_string("x\ty\nz\tw".into()));
        })
        .unwrap();
        app.update(cx, |a, cx| a.grid_paste(cx));
        app.update(cx, |a, _| {
            let t = &a.opened[0];
            assert_eq!(t.data[rows - 1][0], "x", "末行照常覆盖");
            assert_eq!(t.data[rows - 1][1], "y");
            assert_eq!(t.inserted.len(), 1, "超出末行的部分补成待新增行");
            assert_eq!(t.inserted[0][0], "z");
            assert_eq!(t.inserted[0][1], "w");
            assert!(t.dirty());
        });
    }

    /// 待应用状态：状态栏汇总裁剪改 / 增 / 删；Ctrl+Z 按步回退，Ctrl+Y 再前进。
    /// 改格、粘贴、加行、删行各算一步；空操作不当一步。
    #[gpui_kit::test]
    fn grid_undo_redo_steps_and_pending_summary(cx: &mut TestAppContext) {
        isolate_store("gridundo");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.open_object(Act::Obj(0, 0, NO_SCHEMA, 0, 0), cx);
            });
            window.render_frame(cx);
        })
        .unwrap();
        let (base_value, base_rows) =
            app.update(cx, |a, _| (a.opened[0].data[0][1].clone(), a.opened[0].data.len()));
        assert_eq!(app.update(cx, |a, _| a.grid_undo_state()), (false, false));

        // 就地编辑改一格
        cx.update_window(handle, |_, window, cx| {
            window.double_click("cell/0/1", cx);
        })
        .unwrap();
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, cx| {
                let input = a.cell_editing.as_ref().unwrap().input.clone();
                input.update(cx, |s, cx| s.set_value("hello undo", window, cx));
            });
            window.press("enter", cx);
        })
        .unwrap();
        app.update(cx, |a, cx| {
            assert_eq!(a.opened[0].data[0][1], "hello undo");
            assert_eq!(a.grid_undo_state(), (true, false));
            assert_eq!(a.opened[0].grid_pending(), (1, 0, 0));
            let (_, status) = a.table_page_status(&a.opened[0]);
            assert!(status.contains("待应用：1 格已改"), "{status}");
            a.grid_undo(cx);
            let t = &a.opened[0];
            assert_eq!(t.data[0][1], base_value, "撤销退回原值");
            assert!(!t.dirty(), "全撤后回到基线");
            assert_eq!(a.grid_undo_state(), (false, true));
            let (_, status) = a.table_page_status(t);
            assert!(!status.contains("待应用"), "退回基线后不再报待应用：{status}");
        });

        // 重做：改动回来；再撤销，重做栈清空
        app.update(cx, |a, cx| a.grid_redo(cx));
        app.update(cx, |a, _| {
            assert_eq!(a.opened[0].data[0][1], "hello undo");
            assert_eq!(a.grid_undo_state(), (true, false));
        });

        // 粘贴两格：一步撤销整块退回
        cx.update_window(handle, |_, window, cx| {
            window.click("cell/1/0", cx);
            cx.write_to_clipboard(gpui::ClipboardItem::new_string("p1\tp2".into()));
        })
        .unwrap();
        app.update(cx, |a, cx| a.grid_paste(cx));
        app.update(cx, |a, cx| {
            assert_eq!(a.opened[0].data[1][0], "p1");
            assert_eq!(a.opened[0].data[1][1], "p2");
            a.grid_undo(cx);
            assert_ne!(a.opened[0].data[1][0], "p1", "粘贴块一步撤回");
            assert_eq!(
                a.opened[0].data[0][1], "hello undo",
                "只退最近一步，前面的改动还在"
            );
        });

        // 加行 / 删行各一步
        app.update(cx, |a, cx| a.grid_insert_row(cx));
        app.update(cx, |a, _| assert_eq!(a.opened[0].inserted.len(), 1));
        app.update(cx, |a, cx| a.grid_undo(cx));
        app.update(cx, |a, _| assert!(a.opened[0].inserted.is_empty(), "撤销收回新行"));

        app.update(cx, |a, _| a.opened[0].cell = (2, 0));
        let row2 = app.update(cx, |a, _| a.opened[0].data[2].clone());
        app.update(cx, |a, cx| a.grid_delete_row(cx));
        app.update(cx, |a, _| assert_eq!(a.opened[0].data.len(), base_rows - 1));
        app.update(cx, |a, cx| a.grid_undo(cx));
        app.update(cx, |a, _| {
            assert_eq!(a.opened[0].data.len(), base_rows, "撤销恢复被删的行");
            assert_eq!(a.opened[0].data[2], row2);
        });

        // 设成原值不算一步：撤销计数不变
        let before_steps = app.update(cx, |a, _| a.opened[0].undo.len());
        let ident = app.update(cx, |a, _| {
            let t = &a.opened[0];
            (t.conn_name.clone(), t.db, t.schema, t.cat, t.obj)
        });
        let cur = app.update(cx, |a, _| a.opened[0].data[0][0].clone());
        app.update(cx, |a, cx| a.grid_menu_set_value(&ident, 0, 0, cur, cx));
        app.update(cx, |a, _| {
            assert_eq!(a.opened[0].undo.len(), before_steps, "原值不留空撤销步");
        });

        // 删除整块后 Ctrl+Y 能重放
        app.update(cx, |a, cx| a.grid_redo(cx));
        app.update(cx, |a, _| {
            assert_eq!(a.opened[0].undo.len(), before_steps + 1);
        });
    }


    #[gpui_kit::test]
    fn table_grid_reorder_resize_persist_client_side(cx: &mut TestAppContext) {
        isolate_store("gridlayout");
        let (handle, app) = open_app(cx);
        let (cols_before, data_before) = cx
            .update_window(handle, |_, window, cx| {
                window.render_frame(cx);
                app.update(cx, |a, cx| {
                    a.open_object(Act::Obj(0, 0, NO_SCHEMA, 0, 0), cx);
                });
                window.render_frame(cx);
                app.update(cx, |a, _| (a.opened[0].cols.clone(), a.opened[0].data.clone()))
            })
            .unwrap();

        // 列头拖动 th/1 → th/2：列 1 落到显示位置 2
        cx.update_window(handle, |_, window, cx| {
            window.drag_to("th/1", "th/2", cx);
        })
        .unwrap();
        app.update(cx, |a, _| {
            let t = &a.opened[0];
            assert_eq!(&t.col_order[..4], [0, 2, 1, 3]);
            assert_eq!(t.cols, cols_before, "列形不动");
            assert_eq!(t.data, data_before, "数据不动");
            assert!(t.sort.is_none(), "拖列头不触发排序");
        });
        // 渲染跟着显示序走：第 2 列现在排在第 1 列右边
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            let c1 = window.find("cell/0/1").bounds().origin.x;
            let c2 = window.find("cell/0/2").bounds().origin.x;
            assert!(c2 < c1, "重排后列 2 渲染在列 1 左边: c1={c1:?} c2={c2:?}");
        })
        .unwrap();

        // 列宽拖动：拖 colresize/1 右缘 40px
        let auto_w = app.update(cx, |a, _| grid_auto_col_widths(&a.opened[0])[1]);
        cx.update_window(handle, |_, window, cx| {
            let b = window.find("colresize/1").bounds();
            let from = point(b.origin.x + px(2.), b.origin.y + px(10.));
            let to = point(from.x + px(40.), from.y);
            window.drag(from, to, cx);
        })
        .unwrap();
        app.update(cx, |a, _| {
            let t = &a.opened[0];
            let w = t.col_widths.get(&1).copied().expect("拖过的列有缓存宽");
            assert!(
                (w - (auto_w + 40.)).abs() <= 2.,
                "列宽应≈自适应+40: auto={auto_w} w={w}"
            );
            assert_eq!(t.cols, cols_before, "拖列宽不动列形");
        });

        // 落盘：同一张表重开应用还能拿回缓存
        let key = app.update(cx, |a, _| a.grid_layout_key(&a.opened[0]).unwrap());
        let store = load_store().expect("connections.json 应已写出");
        let layout = store.table_layouts.get(&key).expect("有布局缓存");
        assert_eq!(&layout.order[..4], [0, 2, 1, 3]);
        assert!(layout.widths.contains_key(&1));
    }

    /// 左右侧栏都能拖分栏缝改宽：中栏留够余量、上下限夹紧、松手收状态并落盘。
    #[gpui_kit::test]
    fn side_panels_resize_by_dragging_edges(cx: &mut TestAppContext) {
        isolate_store("sidewidth");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            // 左栏右缘往右拖 60px：250 → 310
            let b = window.find("side-splitter/left").bounds();
            let from = point(b.origin.x + px(2.), b.origin.y + px(10.));
            window.drag(from, point(from.x + px(60.), from.y), cx);
        })
        .unwrap();
        app.update(cx, |a, _| {
            assert!((a.left_w - 310.).abs() <= 2., "左栏拖宽 60: {}", a.left_w);
            assert!(a.side_drag.is_none(), "松手后拖动瞬态收掉");
        });

        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            // 右栏左缘往左拖 40px：315 → 355（右栏拖的是反向边）
            let b = window.find("side-splitter/right").bounds();
            let from = point(b.origin.x + px(2.), b.origin.y + px(10.));
            window.drag(from, point(from.x - px(40.), from.y), cx);
            window.render_frame(cx);
            let center_w = window.find("side-center").bounds().size.width.as_f32();
            assert!(center_w >= CENTER_MIN_W - 1., "中栏仍留够宽: {center_w}");
        })
        .unwrap();
        app.update(cx, |a, _| {
            assert!((a.right_w - 355.).abs() <= 2., "右栏拖宽 40: {}", a.right_w);
            assert!(a.side_drag.is_none(), "松手后拖动瞬态收掉");
        });

        // 夹紧：把指针推到很远 / 拉到很负，两侧都只停在上下限。
        app.update(cx, |a, cx| {
            a.side_resize_begin(Side::Left, 0., cx);
            a.side_resize_move(2000., cx);
            assert!(a.left_w <= LEFT_MAX_W + 0.5, "左栏上限: {}", a.left_w);
            a.side_resize_move(-2000., cx);
            assert!(a.left_w >= LEFT_MIN_W - 0.5, "左栏下限: {}", a.left_w);
            a.side_resize_end(cx);

            a.side_resize_begin(Side::Right, 0., cx);
            a.side_resize_move(-2000., cx);
            assert!(a.right_w <= RIGHT_MAX_W + 0.5, "右栏上限: {}", a.right_w);
            a.side_resize_end(cx);
        });

        // 宽度随 connections.json 落盘，重启按这两个值还原。
        let (left_w, right_w) = app.update(cx, |a, _| (a.left_w, a.right_w));
        let store = load_store().expect("connections.json 应已写出");
        assert!((store.left_w - left_w).abs() <= 1., "左栏宽度落盘");
        assert!((store.right_w - right_w).abs() <= 1., "右栏宽度落盘");
    }

    /// 拖动重排的竖线要落在「插入缝隙」上，并且从表头顶一直画到表体
    #[gpui_kit::test]
    fn table_grid_drag_line_marks_insert_gap(cx: &mut TestAppContext) {
        isolate_store("griddropline");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.open_object(Act::Obj(0, 0, NO_SCHEMA, 0, 0), cx);
            });
            window.render_frame(cx);
        })
        .unwrap();

        // 按住显示列 1 的列头向右拖过列 2 的中线：列 1 会落到列 2 之后，
        // 竖线应画在列 2 与列 3 之间的缝上
        let (start_x, target_x, gap_x, head_top) = cx
            .update_window(handle, |_, window, _| {
                let b1 = window.find("th/1").bounds();
                let b2 = window.find("th/2").bounds();
                let b3 = window.find("th/3").bounds();
                let start_x = (b1.origin.x + b1.size.width * 0.5).as_f32();
                (
                    start_x,
                    start_x + b2.size.width.as_f32() * 0.75,
                    b3.origin.x.as_f32(),
                    b1.origin.y.as_f32(),
                )
            })
            .unwrap();
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, cx| {
                a.grid_col_drag_begin(1, start_x, cx);
                a.grid_header_move(target_x, cx);
                assert_eq!(a.col_drag.as_ref().unwrap().slot, 2, "越过列 2 中线");
            });
            window.render_frame(cx);
            let line = window.find("grid-drop-line").bounds();
            assert!(
                (line.origin.x.as_f32() - gap_x).abs() <= 1.5,
                "竖线落在列 2/3 的缝上: line={:?} gap={gap_x}",
                line.origin
            );
            assert!(
                (line.origin.y.as_f32() - head_top).abs() <= 0.5,
                "竖线从表头顶开始: line={:?} head={head_top}",
                line.origin.y
            );
            assert!(
                line.size.height.as_f32() >= 60.,
                "竖线穿过表体: h={:?}",
                line.size.height
            );
        })
        .unwrap();

        // 刚起拖还没跨过邻列：竖线贴被拖列的前进侧（列 0 拖向右 → 列 0 右缘）
        cx.update_window(handle, |_, window, cx| {
            let b0 = window.find("th/0").bounds();
            let b1 = window.find("th/1").bounds();
            let start_x = (b0.origin.x + b0.size.width * 0.5).as_f32();
            app.update(cx, |a, cx| {
                a.grid_col_drag_begin(0, start_x, cx);
                a.grid_header_move(start_x + 6., cx);
            });
            window.render_frame(cx);
            let line = window.find("grid-drop-line").bounds();
            assert!(
                (line.origin.x.as_f32() - b1.origin.x.as_f32()).abs() <= 1.5,
                "起拖阶段竖线贴在列 0 右缘: line={:?} edge={:?}",
                line.origin,
                b1.origin
            );
        })
        .unwrap();

        // 松手后竖线收掉
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, cx| a.grid_header_up(cx));
            window.render_frame(cx);
        })
        .unwrap();
        app.update(cx, |a, _| assert!(a.col_drag.is_none(), "松手后拖动状态清掉"));
    }

    #[gpui_kit::test]
    fn table_grid_cell_edit(cx: &mut TestAppContext) {
        isolate_store("gridedit");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.open_object(Act::Obj(0, 0, NO_SCHEMA, 0, 0), cx);
            });
            window.render_frame(cx);
            // 单击只选格，不进编辑
            window.click("cell/0/3", cx);
            app.update(cx, |a, _| {
                assert_eq!(a.opened[0].cell, (0, 3), "单击挪当前格");
                assert!(a.cell_editing.is_none(), "单击不进编辑");
            });
            // 相邻两格各点一下（测试台每下 click_count=1）不能并成双击；
            // 判双击只看「同一格」
            window.click("cell/0/1", cx);
            window.click("cell/0/2", cx);
            app.update(cx, |a, _| {
                assert!(a.cell_editing.is_none(), "不同格的两下单击不进编辑");
            });
            // 双击 cell/0/1 进就地编辑（测试台的双击也是同格两下点击，
            // 与真机走同一条时间窗判定）
            window.double_click("cell/0/1", cx);
        })
        .unwrap();

        // 编辑器事件订阅的激活走 effect 队列，冲刷发生在 update 边界 ——
        // 建编辑器、键入 / 断言要分轮（同 query_run_select_write_empty 的口径）
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, cx| {
                let e = a.cell_editing.as_ref().expect("双击后应有编辑器");
                assert_eq!(e.at, (0, 1));
                let text = e.input.read(cx).value().to_string();
                assert!(!text.is_empty(), "mock 首行该有值");
                assert_eq!(
                    e.input.read(cx).selected_range(),
                    0..text.len(),
                    "进编辑即全选，不能把光标丢在文字末尾"
                );
            });
            app.update(cx, |a, cx| {
                let input = a.cell_editing.as_ref().unwrap().input.clone();
                input.update(cx, |s, cx| s.set_value("hello", window, cx));
            });
            window.press("enter", cx);
        })
        .unwrap();

        cx.update_window(handle, |_, _, cx| {
            app.update(cx, |a, _| {
                let t = &a.opened[0];
                assert_eq!(t.data[0][1], "hello", "回车提交写回工作集");
                assert!(t.dirty(), "改值后 dirty");
                assert!(a.cell_editing.is_none(), "回车后编辑器收起");
            });
        })
        .unwrap();

        // 取消：改值不写回（Esc 全局动作在 main 里注册，测试直调取消）
        cx.update_window(handle, |_, window, cx| {
            window.double_click("cell/0/2", cx);
        })
        .unwrap();
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, cx| {
                let input = a.cell_editing.as_ref().expect("再次双击进编辑").input.clone();
                input.update(cx, |s, cx| s.set_value("nope", window, cx));
                a.cancel_cell_edit(cx);
                let t = &a.opened[0];
                assert_ne!(t.data[0][2], "nope", "取消不写回");
                assert!(t.dirty(), "第一次的提交还在");
                assert!(a.cell_editing.is_none());
            });
        })
        .unwrap();
    }

    /// 编辑中的格子右键弹应用自己的文本菜单：菜单拿焦点不许把编辑器
    /// 顺手提交掉，点菜单项的动作要落在输入框上（原生菜单顶掉后的唯一入口）。
    #[gpui_kit::test]
    fn cell_edit_right_click_shows_app_text_menu(cx: &mut TestAppContext) {
        isolate_store("cellctxmenu");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| a.open_object(Act::Obj(0, 0, NO_SCHEMA, 0, 0), cx));
            window.render_frame(cx);
            window.double_click("cell/0/1", cx);
        })
        .unwrap();
        let text = cx
            .update_window(handle, |_, _, cx| {
                app.read_with(cx, |a, cx| {
                    let e = a.cell_editing.as_ref().expect("双击进编辑");
                    assert_eq!(e.at, (0, 1));
                    e.input.read(cx).value().to_string()
                })
            })
            .unwrap();
        assert!(!text.is_empty(), "mock 首行该有值");

        // 编辑态那一格要先画出来，右键的命中要落在包着输入框的 ContextMenu 上；
        // open_menu 把建菜单推到 defer，退出这次 update_window 才会 flush 效果
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            window.right_click("cell/0/1", cx);
        })
        .unwrap();
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            window.render_frame(cx);
            assert!(
                window.try_find("popup-menu").is_some(),
                "右键编辑格要弹应用自己的文本菜单"
            );
            app.read_with(cx, |a, _| {
                assert!(a.cell_editing.is_some(), "菜单拿走焦点不提交编辑器");
                assert!(a.cell_menu_open, "菜单打开期间失焦提交让位");
            });
        })
        .unwrap();

        // 点「粘贴」（id = 3：撤销 0 / 剪切 1 / 复制 2 / 粘贴 3）：剪贴板内容
        // 落进输入框，编辑器仍然开着、焦点交回输入框。右键会把光标挪到格内
        // 落点（这格文字只有一两个字符，落点常在文末），所以粘贴是追加。
        cx.update(|cx| cx.write_to_clipboard(gpui::ClipboardItem::new_string("XYZ".into())));
        cx.update_window(handle, |_, window, cx| {
            window.click(3usize, cx);
            window.render_frame(cx);
            window.render_frame(cx);
        })
        .unwrap();
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, cx| {
                let e = a.cell_editing.as_ref().expect("点菜单项不收起编辑器");
                assert_eq!(
                    e.input.read(cx).value().as_ref(),
                    format!("{text}XYZ"),
                    "粘贴动作落在输入框上"
                );
                assert!(
                    e.input.read(cx).focus_handle(cx).is_focused(window),
                    "动作之后焦点交回输入框"
                );
                assert!(!a.cell_menu_open, "菜单关掉后清标记");
            });
        })
        .unwrap();
    }

    /// 非编辑态右键任意格：弹参考界面口径的应用菜单（不是系统菜单），
    /// 右键的那格成为当前格；设为 NULL / 复制字段名 / 添加记录直接生效。
    #[gpui_kit::test]
    fn grid_right_click_opens_cell_menu(cx: &mut TestAppContext) {
        isolate_store("gridctxmenu");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| a.open_object(Act::Obj(0, 0, NO_SCHEMA, 0, 0), cx));
            window.render_frame(cx);
            window.right_click("cell/1/1", cx);
        })
        .unwrap();
        // 右键先把当前格挪过来；菜单建在 defer，下一轮才画
        app.update(cx, |a, _| {
            let t = &a.opened[0];
            assert_eq!(t.cell, (1, 1), "右键的格成为当前格");
            assert_eq!(t.sel.map(|s| s.rect()), Some((1, 1, 1, 1)));
        });
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            window.render_frame(cx);
            assert!(window.try_find("popup-menu").is_some(), "右键弹应用菜单");
        })
        .unwrap();

        // 1 = 「设置为 NULL」：直接写工作集
        cx.update_window(handle, |_, window, cx| {
            window.click(1usize, cx);
            window.render_frame(cx);
            window.render_frame(cx);
        })
        .unwrap();
        app.update(cx, |a, _| {
            let t = &a.opened[0];
            assert_eq!(t.data[1][1], "NULL", "设置为 NULL 落进工作集");
            assert!(t.dirty(), "改值后 dirty");
        });

        // 10 = 「复制字段名称」
        let col_name = app.update(cx, |a, _| a.opened[0].cols[2].name.clone());
        cx.update_window(handle, |_, window, cx| window.right_click("cell/2/2", cx))
            .unwrap();
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            window.render_frame(cx);
            window.click(10usize, cx);
        })
        .unwrap();
        let copied = app.update(cx, |_, cx| {
            cx.read_from_clipboard().and_then(|i| i.text())
        });
        assert_eq!(copied.as_deref(), Some(col_name.as_str()));

        // 6 = 「添加记录」
        let before = app.update(cx, |a, _| a.opened[0].inserted.len());
        cx.update_window(handle, |_, window, cx| window.right_click("cell/0/0", cx))
            .unwrap();
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            window.render_frame(cx);
            window.click(6usize, cx);
            window.render_frame(cx);
            window.render_frame(cx);
        })
        .unwrap();
        app.update(cx, |a, _| {
            assert_eq!(
                a.opened[0].inserted.len(),
                before + 1,
                "添加记录追加待新增行"
            );
        });
    }

    #[gpui_kit::test]
    fn table_grid_insert_delete_apply_revert(cx: &mut TestAppContext) {
        isolate_store("gridins");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.open_object(Act::Obj(0, 0, NO_SCHEMA, 0, 0), cx);
            });
            window.render_frame(cx);
        })
        .unwrap();
        let rows = app.update(cx, |a, _| a.opened[0].data.len());

        // + 新增：网格尾追加空行并选中，dirty 点亮
        app.update(cx, |a, cx| a.grid_insert_row(cx));
        app.update(cx, |a, _| {
            let t = &a.opened[0];
            assert_eq!(t.inserted.len(), 1);
            assert!(t.inserted[0].iter().all(|v| v.is_empty()));
            assert_eq!(t.cell, (rows, 0), "选中新行");
            assert!(t.dirty());
        });

        // 新行贴在最后一页，可就地编辑（订阅激活分轮，同上一个用例）
        let cid = format!("cell/{rows}/3");
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            window.double_click(cid, cx);
        })
        .unwrap();
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, cx| {
                let input = a.cell_editing.as_ref().expect("新行可编辑").input.clone();
                input.update(cx, |s, cx| s.set_value("9.5".to_string(), window, cx));
            });
            app.update(cx, |a, cx| a.commit_cell_edit(cx));
            app.update(cx, |a, _| {
                assert_eq!(a.opened[0].inserted[0][3], "9.5", "新行单元格可写");
            });
        })
        .unwrap();

        // ✓ 应用：inserted 并进 data、基线刷新、dirty 熄灭
        app.update(cx, |a, cx| a.grid_apply(cx));
        app.update(cx, |a, _| {
            let t = &a.opened[0];
            assert_eq!(t.data.len(), rows + 1);
            assert!(t.inserted.is_empty());
            assert_eq!(t.data[rows][3], "9.5");
            assert!(!t.dirty(), "应用后无变更");
        });

        // − 删除当前行（刚应用的新行）：工作集移除，dirty 重新点亮
        app.update(cx, |a, cx| a.grid_delete_row(cx));
        app.update(cx, |a, _| {
            let t = &a.opened[0];
            assert_eq!(t.data.len(), rows);
            assert!(t.dirty(), "删行未应用 → dirty");
        });

        // × 撤销 / 刷新：退回基线，删的行复原
        app.update(cx, |a, cx| a.grid_revert(cx));
        app.update(cx, |a, _| {
            let t = &a.opened[0];
            assert_eq!(t.data.len(), rows + 1);
            assert_eq!(t.data[rows][3], "9.5");
            assert!(!t.dirty());
        });
    }

    #[gpui_kit::test]
    fn table_header_click_sorts(cx: &mut TestAppContext) {
        isolate_store("thsort");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.open_object(Act::Obj(0, 0, NO_SCHEMA, 0, 0), cx);
            });
            window.render_frame(cx);

            // 初始无排序，状态栏 SQL 无 ORDER BY
            app.update(cx, |a, _| {
                let t = &a.opened[0];
                assert_eq!(t.sort, None);
                let (sql, _) = a.table_page_status(t);
                assert!(!sql.contains("ORDER BY"), "{sql}");
            });

            // 点列头 0：升序 → 再点：降序；换列 1：重置升序
            window.click("th/0", cx);
            app.update(cx, |a, _| {
                let t = &a.opened[0];
                assert_eq!(t.sort, Some((0, true)));
                let (sql, _) = a.table_page_status(t);
                assert!(sql.contains("ORDER BY `id` ASC"), "{sql}");
            });
            window.click("th/0", cx);
            app.update(cx, |a, _| {
                let t = &a.opened[0];
                assert_eq!(t.sort, Some((0, false)));
                let (sql, _) = a.table_page_status(t);
                assert!(sql.contains("ORDER BY `id` DESC"), "{sql}");
            });
            window.click("th/1", cx);
            app.update(cx, |a, _| {
                let t = &a.opened[0];
                assert_eq!(t.sort, Some((1, true)));
                let (sql, _) = a.table_page_status(t);
                assert!(sql.contains("ORDER BY `org_id` ASC"), "{sql}");
            });

            // 排序态下点格：cell 存显示序位，点选与翻页口径不乱
            window.click("cell/2/3", cx);
            app.update(cx, |a, _| {
                let t = &a.opened[0];
                assert_eq!(t.cell, (2, 3));
                let (_, rec) = a.table_page_status(t);
                assert!(rec.starts_with("第 3 条记录"), "{rec}");
            });

            // 换页签回来排序态还在（排序随页签存亡）
            app.update(cx, |a, _| {
                a.active_tab = 0;
            });
            window.render_frame(cx);
            app.update(cx, |a, _| {
                a.active_tab = 1;
            });
            window.render_frame(cx);
            assert!(window.try_find("th/1").is_some(), "表头回得来");
            app.update(cx, |a, _| {
                assert_eq!(a.opened[0].sort, Some((1, true)));
            });
        })
        .unwrap();
    }

    /// 数据页签的取数 SQL 从主内容区那段开始排：树面板那一格留空
    /// （参考界面底栏口径），记录数在 SQL 右侧。
    #[gpui_kit::test]
    fn table_status_sql_sits_in_main_area(cx: &mut TestAppContext) {
        isolate_store("statussql");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.open_object(Act::Obj(0, 0, NO_SCHEMA, 0, 0), cx);
            });
            window.render_frame(cx);
        })
        .unwrap();
        cx.update_window(handle, |_, window, _| {
            let left = window.find("status-left").bounds();
            let sql = window.find("status-sql").bounds();
            let rec = window.find("status-rec").bounds();
            assert!(
                sql.origin.x >= left.origin.x + left.size.width,
                "取数 SQL 应在树面板右侧：left={left:?} sql={sql:?}"
            );
            assert!(sql.size.width > px(0.), "SQL 段要有宽度：{sql:?}");
            assert!(
                rec.origin.x >= sql.origin.x + sql.size.width,
                "记录数在 SQL 右侧：sql={sql:?} rec={rec:?}"
            );
        })
        .unwrap();
    }

    #[gpui_kit::test]
    fn f5_refresh_reverts_grid_via_key_binding(cx: &mut TestAppContext) {
        isolate_store("f5refresh");
        let (handle, app) = open_app(cx);
        // 与 main 同一条装配（绑定 f5 + 全局动作 + defer 进窗口）
        cx.update(|cx| wire_global_keys(app.clone(), handle, cx));
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| a.open_object(Act::Obj(0, 0, NO_SCHEMA, 0, 0), cx));
            window.render_frame(cx);
            app.update(cx, |a, _| {
                let t = a.opened.first_mut().unwrap();
                assert!(!t.design && !t.query, "前置：数据页签");
                t.data[0][1] = "dirty".into();
                t.inserted.push(vec![String::new(); t.data[0].len()]);
                assert!(t.dirty());
            });
            window.press("f5", cx);
        })
        .unwrap();
        // 动作经 defer 进窗口，effect 冲刷后再断言
        cx.update_window(handle, |_, _, cx| {
            app.update(cx, |a, _| {
                let t = &a.opened[0];
                assert!(!t.dirty(), "F5 后工作集退回基线");
                assert_eq!(t.data, t.baseline);
                assert!(t.inserted.is_empty());
            });
        })
        .unwrap();

        // 设计页签上 F5 不动工作集（无「数据」可重取）
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, cx| {
                a.open_designer(Act::Obj(0, 0, NO_SCHEMA, 0, 0), window, cx)
            });
            window.render_frame(cx);
            app.update(cx, |a, _| {
                let ix = a.active_tab - 1;
                let t = &mut a.opened[ix];
                assert!(t.design);
                let ds = t.dstate.as_mut().unwrap();
                ds.cols[0].name = "renamed".into();
                assert!(ds.cols != ds.baseline, "设计器工作集已脏");
            });
            window.press("f5", cx);
        })
        .unwrap();
        cx.update_window(handle, |_, _, cx| {
            app.update(cx, |a, _| {
                let t = &a.opened[a.active_tab - 1];
                let ds = t.dstate.as_ref().unwrap();
                assert_eq!(ds.cols[0].name, "renamed", "设计器工作集不被 F5 清");
            });
        })
        .unwrap();
    }

    #[gpui_kit::test]
    fn new_table_designer_flow(cx: &mut TestAppContext) {
        isolate_store("newtable");
        let (handle, app) = open_app(cx);
        let mut did = 0;
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            // 动作条入口：树里选中一张表 → 「新建表」开空模型设计页签
            app.update(cx, |a, _| a.sel = Act::Obj(0, 0, NO_SCHEMA, 0, 0));
            window.render_frame(cx);
            window.click("act-new", cx);
            window.render_frame(cx);
            app.update(cx, |a, _| {
                assert_eq!(a.opened.len(), 1);
                assert_eq!(a.active_tab, 1, "新页签激活");
                let t = &a.opened[0];
                assert!(t.design);
                assert_eq!(t.obj, usize::MAX, "新表无目录项");
                let ds = t.dstate.as_ref().unwrap();
                assert_eq!(ds.new_name.as_deref(), Some(""), "未命名新表");
                assert_eq!(ds.cols.len(), 1, "预置一行空字段");
                assert_eq!(ds.cols, ds.baseline, "初始无变更");
                assert_eq!(ds.edits.len(), 1, "常驻编辑器随行建齐");
                assert_eq!(a.tab_label(t), "新建表", "命名前标题就叫新建表");
                assert!(
                    DaroApp::tab_glyph(t) == art::Glyph::DesignTable,
                    "新建表页签用表设计图标"
                );
                did = t.did;
            });
            // 每次触发都开新页签，不去重（参考界面同款）
            app.update(cx, |a, cx| {
                a.open_new_designer(Act::Obj(0, 0, NO_SCHEMA, 0, 0), window, cx)
            });
            app.update(cx, |a, _| {
                assert_eq!(a.opened.len(), 2);
                assert_eq!(a.active_tab, 2);
            });
            // 关掉第二个，回到第一个做保存链路
            app.update(cx, |a, _| a.close_tab(1));
            app.update(cx, |a, _| {
                assert_eq!(a.active_tab, 1);
            });
            // 填上字段名 → 工作集脏、标题带 *；保存 → 弹「表名」输入框（独立
            // 窗口），主窗口模型不动；模拟输入框确定 → 记名 + 基线对齐
            app.update(cx, |a, _| {
                let t = a.opened.first_mut().unwrap();
                let ds = t.dstate.as_mut().unwrap();
                ds.cols[0].name = "id".into();
                ds.cols[0].pk = true;
            });
            window.render_frame(cx);
            app.update(cx, |a, _| {
                let t = &a.opened[0];
                let ds = t.dstate.as_ref().unwrap();
                assert_ne!(ds.cols, ds.baseline, "改字段后为脏");
                assert_eq!(a.tab_label(t), "*新建表", "脏标进标题");
            });
            app.update(cx, |a, cx| a.design_save(did, cx));
            app.update(cx, |a, _| {
                let ds = a.opened[0].dstate.as_ref().unwrap();
                assert_eq!(ds.new_name.as_deref(), Some(""), "弹窗期间主窗口不动");
                assert_ne!(ds.cols, ds.baseline, "弹窗期间不落基线");
            });
            app.update(cx, |a, _| a.finish_new_design_save(did, "t1".into()));
            app.update(cx, |a, _| {
                let t = &a.opened[0];
                let ds = t.dstate.as_ref().unwrap();
                assert_eq!(ds.new_name.as_deref(), Some("t1"));
                assert_eq!(ds.cols, ds.baseline, "保存后基线对齐");
                assert_eq!(ds.note, Some("已创建（演示数据，不落库）"));
                let label = a.tab_label(t);
                assert!(label.starts_with("t1 @"), "{label}");
                assert!(label.ends_with(" (设计)"), "{label}");
            });
            // 已命名的再保存走既有路径（不弹窗）
            app.update(cx, |a, cx| a.design_save(did, cx));
            app.update(cx, |a, _| {
                let ds = a.opened[0].dstate.as_ref().unwrap();
                assert_eq!(ds.note, Some("已保存（演示数据，不落库）"));
            });
        })
        .unwrap();
    }

    /// 真 SQLite 驱动的端到端接线：目录 → 打表 → 改 / 删 / 增 → ✓ 写回真库 → 查询页执行。
    #[gpui_kit::test]
    fn sqlite_real_table_apply_and_query(cx: &mut TestAppContext) {
        isolate_store("sqlite-real");
        let db = std::env::temp_dir().join(format!("daro_rs_sqlite_{}.db", std::process::id()));
        let _ = std::fs::remove_file(&db);
        let path = db.to_string_lossy().to_string();
        crate::sqlite_driver::open("sqlite-seed", &path).unwrap();
        crate::sqlite_driver::execute_stmt(
            "sqlite-seed",
            "CREATE TABLE member (id INTEGER PRIMARY KEY, name TEXT, score REAL)",
            1,
        )
        .unwrap();
        crate::sqlite_driver::execute_stmt(
            "sqlite-seed",
            "INSERT INTO member (name, score) VALUES ('阿离', 88.5), ('老张', 60)",
            1,
        )
        .unwrap();
        crate::sqlite_driver::close("sqlite-seed");

        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.conns = vec![mock::Connection::new(
                    "本地 SQLite",
                    DbKind::SQLite,
                    "",
                    0,
                    path.clone(),
                    "",
                    "",
                    "",
                    false,
                )];
                a.groups.clear();
                a.sel = Act::Conn(0);
                a.open_connection(0, cx);
            });
        })
        .unwrap();
        settle(cx, handle);
        app.update(cx, |a, _| assert!(a.conns[0].connected));

        // 目录：单库（main），表清单来自真库（树没展开时自己发一次对象请求）
        app.update(cx, |a, _| {
            let conn = &a.conns[0];
            assert_eq!(catalog::databases(conn).len(), 1);
            assert!(!catalog::has_schemas(conn.kind));
            let _ = catalog::objects(conn, "main", "", 0);
        });
        settle(cx, handle);
        app.update(cx, |a, _| {
            assert_eq!(catalog::objects(&a.conns[0], "main", "", 0), &["member"]);
        });

        // 打开表：真列 + 真行 + rowid
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, cx| a.open_object(Act::Obj(0, 0, NO_SCHEMA, 0, 0), cx));
        })
        .unwrap();
        settle(cx, handle);
        app.update(cx, |a, _| {
            let t = &a.opened[0];
            assert_eq!(
                t.cols.iter().map(|c| c.name.as_str()).collect::<Vec<_>>(),
                ["id", "name", "score"]
            );
            assert_eq!(t.data.len(), 2);
            assert!(t.row_keys.iter().all(|k| !k.is_empty()), "真行带 rowid");
            assert!(!t.dirty());
        });

        // 改单元格 → ✓ 写回真库
        app.update(cx, |a, cx| {
            a.opened[0].data[0][1] = "阿离改".into();
            a.grid_apply(cx);
        });
        settle(cx, handle);
        app.update(cx, |a, _| {
            let page =
                crate::sqlite_driver::select_table("本地 SQLite", "main", "member", None, &[], 0, 10)
                    .unwrap();
            assert_eq!(page.rows[0][1], "阿离改");
            assert!(!a.opened[0].dirty());
        });

        // 删除第二行 → ✓
        app.update(cx, |a, cx| {
            a.opened[0].cell = (1, 0);
            a.grid_delete_row(cx);
            a.grid_apply(cx);
        });
        settle(cx, handle);
        app.update(cx, |a, _| {
            let page =
                crate::sqlite_driver::select_table("本地 SQLite", "main", "member", None, &[], 0, 10)
                    .unwrap();
            assert_eq!(page.rows.len(), 1);
            assert_eq!(a.opened[0].data.len(), 1);
        });

        // + 新增 → 填值 → ✓
        app.update(cx, |a, cx| {
            a.grid_insert_row(cx);
            a.opened[0].inserted[0] = vec!["3".into(), "新成员".into(), "77".into()];
            a.grid_apply(cx);
        });
        settle(cx, handle);
        app.update(cx, |a, _| {
            let page =
                crate::sqlite_driver::select_table("本地 SQLite", "main", "member", None, &[], 0, 10)
                    .unwrap();
            assert_eq!(page.rows.len(), 2);
            assert!(page.rows.iter().any(|r| r[1] == "新成员"));
            assert!(!a.opened[0].dirty());
        });

        // 查询页：真执行 SELECT，结果列 / 行来自驱动
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, cx| a.open_query_tab(None, window, cx));
            window.render_frame(cx);
        })
        .unwrap();
        let qid = cx
            .update_window(handle, |_, window, cx| {
                app.update(cx, |a, cx| {
                    let editor = a.opened.last().unwrap().qstate.as_ref().unwrap().editor.clone();
                    editor.update(cx, |s, cx| {
                        s.set_value("SELECT count(*) AS n FROM member".to_string(), window, cx)
                    });
                });
                let qid = app.update(cx, |a, _| a.opened.last().unwrap().qid);
                app.update(cx, |a, cx| a.query_run(qid, false, window, cx));
                app.update(cx, |a, _| {
                    let q = a.opened.last().unwrap().qstate.as_ref().unwrap();
                    assert!(q.job.is_some(), "真库脚本转到后台跑，页签先挂上任务");
                    assert!(q.outcomes.is_empty(), "回执没回来前不留旧结果");
                });
                qid
            })
            .unwrap();
        // 回执来自后台执行器：测试里手动抽干（真窗口靠事件循环）
        cx.run_until_parked();
        app.update(cx, |a, _| {
            let q = a.opened.last().unwrap().qstate.as_ref().unwrap();
            assert!(q.job.is_none(), "回执落地后任务摘除");
            assert_eq!(q.outcomes.len(), 1);
            let o = &q.outcomes[0];
            assert_eq!(o.result.as_deref(), Some(&[vec!["2".to_string()]][..]));
            assert_eq!(o.columns[0].name, "n");
            assert!(o.message.is_none());
        });

        crate::sqlite_driver::close("本地 SQLite");
        let _ = std::fs::remove_file(&db);
    }

    /// PostgreSQL 档全链路（真机：datawalk 开发服务器上的独立测试库
    /// `daro_pg_test`，每轮先删后建）。UI 与 SQLite 走同一条分发路径，这里验
    /// 的是换成 PG 之后每一步落点都对：目录 → 打开表 → 分页 / 排序 / 筛选
    /// 下推 → 改 / 删 / 增写回 → 查询页后台执行。
    #[gpui_kit::test]
    #[ignore = "打 datawalk 开发库，需要网络可达"]
    fn pg_real_catalog_page_apply_and_query(cx: &mut TestAppContext) {
        use crate::pg_driver::tests::{TEST_DB, reset_test_db};
        isolate_store("pg-real");
        let p = reset_test_db().expect("读不到 datawalk 的开发连接串");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.conns = vec![mock::Connection::new(
                    "真机 PG",
                    DbKind::PostgreSql,
                    p.host.clone(),
                    p.port,
                    TEST_DB.to_string(),
                    p.user.clone(),
                    p.password.clone(),
                    "",
                    false,
                )];
                a.groups.clear();
                a.sel = Act::Conn(0);
                a.open_connection(0, cx);
            });
        })
        .unwrap();
        settle(cx, handle);
        // 目录一层层来：先把下一层（模式 / 对象 / 列）排上队，再抽干
        app.update(cx, |a, _| {
            assert!(a.conns[0].connected, "连接成功");
            if let Some(e) = catalog::take_error() {
                panic!("目录读取失败：{e}");
            }
            let _ = catalog::schemas(&a.conns[0], TEST_DB);
        });
        settle(cx, handle);
        app.update(cx, |a, _| {
            let conn = &a.conns[0];
            for cat in 0..5 {
                let _ = catalog::objects(conn, TEST_DB, "public", cat);
            }
            let _ = catalog::table_columns(conn, TEST_DB, "public", "member");
        });
        settle(cx, handle);

        // 目录：库 / 模式 / 四类对象 / 列元数据全部来自真库
        let (db_ix, schema_ix, member_ix) = app.update(cx, |a, _| {
            let conn = &a.conns[0];
            let dbs = catalog::databases(conn);
            let db_ix = dbs.iter().position(|d| *d == TEST_DB).expect("测试库在库清单里");
            let schemas = catalog::schemas(conn, TEST_DB);
            let schema_ix = schemas.iter().position(|s| *s == "public").expect("public 在模式清单里");
            assert!(!schemas.iter().any(|s| s.starts_with("pg_")), "系统模式不列：{schemas:?}");

            let tables = catalog::objects(conn, TEST_DB, "public", 0);
            for t in ["member", "gen", "nopath", "pair", "wide"] {
                assert!(tables.contains(&t), "{t} 应在表清单：{tables:?}");
            }
            assert!(catalog::objects(conn, TEST_DB, "public", 1).contains(&"v_member"));
            assert!(catalog::objects(conn, TEST_DB, "public", 2).contains(&"mv_member"));
            assert!(catalog::objects(conn, TEST_DB, "public", 3).contains(&"add2"));
            assert!(catalog::objects(conn, TEST_DB, "public", 4).is_empty(), "查询节点不由目录出");

            let cols = catalog::table_columns(conn, TEST_DB, "public", "member");
            assert_eq!(
                cols.iter().map(|c| c.name.as_str()).collect::<Vec<_>>(),
                ["id", "name", "score", "joined", "note"]
            );
            assert!(cols[0].pk, "id 是主键");
            assert!(!cols[0].writable, "标识列不可写");
            assert!(cols[2].numeric, "numeric 是数值列");
            let member_ix = tables.iter().position(|t| *t == "member").unwrap();
            (db_ix, schema_ix, member_ix)
        });

        // 打开表：真列 + 真行 + 主键当行标识
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, cx| {
                a.open_object(Act::Obj(0, db_ix, schema_ix, 0, member_ix), cx)
            });
        })
        .unwrap();
        settle(cx, handle);
        app.update(cx, |a, _| {
            let t = &a.opened[0];
            assert_eq!(t.data.len(), 3, "夹具 3 行");
            assert_eq!(t.page.as_ref().map(|p| (p.page_no, p.total.clone())), Some((0, Some(3))));
            assert_eq!(t.row_keys.len(), 3);
            assert!(
                t.row_keys.iter().all(|k| k.len() == 1 && !k[0].is_empty()),
                "行标识 = 单个主键值：{:?}",
                t.row_keys
            );
        });

        // 分页 / 排序 / 筛选都下推到服务端
        app.update(cx, |a, _| {
            let c = &a.conns[0];
            let (desc, total) = load_table_page(
                c,
                TEST_DB,
                "public",
                "member",
                None,
                &[("id".to_string(), false)],
                0,
                2,
            )
            .unwrap();
            assert_eq!(
                desc.rows.iter().map(|r| r[1].clone()).collect::<Vec<_>>(),
                ["青梧", "北辰"],
                "ORDER BY id DESC 在服务端做"
            );
            assert_eq!((desc.keys[0].as_slice(), total), (&["3".to_string()][..], 3));

            let (hit, hit_total) = load_table_page(
                c,
                TEST_DB,
                "public",
                "member",
                Some("score > 80"),
                &[],
                0,
                2,
            )
            .unwrap();
            assert_eq!((hit.rows.len(), hit_total), (1, 1), "WHERE 在服务端做");
            assert_eq!(hit.rows[0][2], "91.50", "numeric 按服务端文本原样");
            assert_eq!(hit.rows[0][4], "NULL", "真 NULL 打字面");

            let (tail, tail_total) = load_table_page(
                c, TEST_DB, "public", "member", None, &[], 2, 2,
            )
            .unwrap();
            assert_eq!((tail.rows.len(), tail_total), (1, 3), "末页只回剩下的行");
        });

        // 改一行 → ✓：UPDATE 按主键定位，成功后重新取数
        app.update(cx, |a, cx| {
            a.opened[0].data[0][1] = "阿离改".into();
            a.grid_apply(cx);
        });
        settle(cx, handle);
        app.update(cx, |a, _| {
            assert_eq!(a.opened[0].data[0][1], "阿离改");
            assert!(!a.opened[0].dirty(), "写回后工作集即基线");
        });

        // 删一行 → ✓
        app.update(cx, |a, cx| {
            a.opened[0].cell = (2, 0);
            a.grid_delete_row(cx);
            a.grid_apply(cx);
        });
        settle(cx, handle);
        app.update(cx, |a, _| {
            let p = a.opened[0].page.as_ref().unwrap();
            assert_eq!((a.opened[0].data.len(), p.total), (2, Some(2)), "删的是真库那一行");
        });

        // 新增 → ✓：标识列不送，由服务端生成
        app.update(cx, |a, cx| {
            a.grid_insert_row(cx);
            a.opened[0].inserted[0] = vec![
                "NULL".into(),
                "新兄弟".into(),
                "77".into(),
                "NULL".into(),
                "NULL".into(),
            ];
            a.grid_apply(cx);
        });
        settle(cx, handle);
        app.update(cx, |a, _| {
            let names: Vec<String> = a.opened[0].data.iter().map(|r| r[1].clone()).collect();
            assert_eq!(names, ["阿离改", "北辰", "新兄弟"], "改 / 删 / 增都落在真库");
        });

        // 查询页：新建就落在连接配置的库，执行走后台线程
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, cx| a.open_query_tab(None, window, cx));
            window.render_frame(cx);
        })
        .unwrap();
        app.update(cx, |a, _| {
            let q = a.opened.last().unwrap().qstate.as_ref().unwrap();
            assert_eq!(q.conn, "真机 PG");
            assert_eq!(catalog::databases(&a.conns[0])[q.db], TEST_DB, "默认库 = 配置的库");
            assert_eq!(
                catalog::schemas(&a.conns[0], TEST_DB)[q.schema],
                "public",
                "默认模式 = public"
            );
        });
        let qid = cx
            .update_window(handle, |_, window, cx| {
                app.update(cx, |a, cx| {
                    let editor = a.opened.last().unwrap().qstate.as_ref().unwrap().editor.clone();
                    editor.update(cx, |s, cx| {
                        s.set_value("SELECT count(*) AS n FROM member".to_string(), window, cx)
                    });
                });
                let qid = app.update(cx, |a, _| a.opened.last().unwrap().qid);
                app.update(cx, |a, cx| a.query_run(qid, false, window, cx));
                app.update(cx, |a, _| {
                    let q = a.opened.last().unwrap().qstate.as_ref().unwrap();
                    assert!(q.job.is_some(), "PG 脚本恒后台");
                });
                qid
            })
            .unwrap();
        cx.run_until_parked();
        app.update(cx, |a, _| {
            let q = a.opened.last().unwrap().qstate.as_ref().unwrap();
            assert!(q.job.is_none());
            let o = &q.outcomes[0];
            assert_eq!(o.columns[0].name, "n");
            assert_eq!(o.result.as_deref(), Some(&[vec!["3".to_string()]][..]));
        });

        // 「无主键表」在 UI 口径里拒绝写回：行标识为空，有改动就拦下
        let nopath_ix = app.update(cx, |a, _| {
            let tables = catalog::objects(&a.conns[0], TEST_DB, "public", 0);
            tables.iter().position(|t| *t == "nopath").unwrap()
        });
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, cx| a.open_object(Act::Obj(0, db_ix, schema_ix, 0, nopath_ix), cx));
        })
        .unwrap();
        settle(cx, handle);
        app.update(cx, |a, cx| {
            let ix = a.opened.len() - 1;
            a.active_tab = ix + 1;
            assert!(a.opened[ix].row_keys.iter().all(|k| k.is_empty()), "无主键表没有行标识");
            a.opened[ix].data[0][0] = "改不动".into();
            a.grid_apply(cx);
            assert_eq!(a.opened[ix].data[0][0], "改不动", "写回被拦下，工作集保持原样");
        });

        app.update(cx, |a, _| backend::close_connection(&a.conns[0]));
    }

    /// 真机反查角色常规属性 + 两页成员关系：只读 `pg_roles` / `pg_authid` /
    /// `pg_description` / `pg_auth_members` / `pg_attribute`，不建不删不改。
    /// 断言只押预定义角色的共性（PG 保证的形态），OID / 具体日期这类每台服务器
    /// 不同的值只验「从目录来」。跑前请确认网络可达。
    #[test]
    #[ignore = "打 datawalk 开发库，需要网络可达"]
    fn live_role_lookup_reads_predefined_role() {
        let p = pg_driver::tests::datawalk_params().expect("读不到 datawalk 的开发连接串");
        let dbname = p.dbname.clone();
        let tg = backend::Target::Pg {
            conn: "角色反查".to_string(),
            db: dbname.clone(),
            schema: "public".to_string(),
            params: p,
        };
        let bundle = read_role_meta(&tg, "pg_read_all_data").expect("预定义角色一定在集群里");
        let m = &bundle.model;
        assert!(!m.oid.is_empty(), "OID 从目录取，读不到就该报错而不是填 0");
        // 继承位各版本/各实例不一样（截图那台给 INHERIT，datawalk 这台给
        // NOINHERIT），所以不把答案写死，改成「界面值 == 目录值」逐位对照——
        // 这样列序错位（真机踩过 rolcaninherit）照样红，服务器差异不会误报。
        let raw = meta_rows(
            &tg,
            "SELECT rolcanlogin::text, rolsuper::text, rolcreatedb::text, \
                    rolcreaterole::text, rolinherit::text, rolreplication::text, \
                    rolbypassrls::text \
             FROM pg_roles WHERE rolname = 'pg_read_all_data'",
        )
        .expect("直接查目录应当成功")
        .into_iter()
        .next()
        .expect("预定义角色一定有一行");
        let want = |i: usize| raw[i].as_str() == "t";
        assert_eq!(m.can_login, want(0), "可以登录位错位");
        assert_eq!(m.superuser, want(1), "超级用户位错位");
        assert_eq!(m.create_db, want(2), "可以创建数据库位错位");
        assert_eq!(m.create_role, want(3), "可以创建角色位错位");
        assert_eq!(m.inherit, want(4), "继承权限位错位");
        assert_eq!(m.replication, want(5), "可以复制位错位");
        assert_eq!(m.bypass_rls, want(6), "可以绕过 RLS 位错位");
        assert!(!m.can_login, "预定义角色不能登录");
        assert!(!m.superuser && !m.create_db && !m.create_role, "{m:?}");
        assert!(!m.replication && !m.bypass_rls);
        assert_eq!(m.conn_limit, "-1");
        assert!(m.valid_until.is_empty(), "预定义角色没有过期日期");
        // 口令哈希来自 pg_authid，非超级用户没权限时该留空而不是猜一个
        assert!(
            matches!(
                m.pw_encryption.as_str(),
                "" | "md5" | "scram-sha-256" | "其他"
            ),
            "意外的哈希标签：{}",
            m.pw_encryption
        );
        // 打开即干净：基线与工作集同一份，不该拼出任何语句
        assert!(role_design::alter_statements(&m, &m).is_empty());
        // 成员两页：列出的是全集群减去自己，一条 GRANT / REVOKE 都不该有
        for (dir, rows) in [
            (role_design::MemberDir::MemberOf, &bundle.member_of),
            (role_design::MemberDir::Members, &bundle.members),
        ] {
            let page = if dir == role_design::MemberDir::MemberOf { "成员属于" } else { "成员" };
            assert!(!rows.is_empty(), "{page}页该列出全部角色");
            assert!(
                rows.iter().all(|r| r.name != "pg_read_all_data"),
                "{page}页把当前角色自己列进去了"
            );
            assert!(
                role_design::membership_statements("pg_read_all_data", dir, rows, rows).is_empty(),
                "{page}页没改就不该有语句"
            );
        }
        // 反查目录那一列的名字在这台上确实存在（PG16 起才是 admin_option）
        let col = role_design::admin_col_from_probe(&meta_rows_or_empty(
            &tg,
            role_design::ADMIN_COL_PROBE,
        ));
        assert!(
            meta_rows(&tg, &format!("SELECT {col} FROM pg_auth_members LIMIT 0")).is_ok(),
            "{col} 在这台上取不到"
        );
        pg_driver::close(&pg_driver::key("角色反查", &dbname));
    }

    /// 真库脚本走后台：运行时页签挂任务、旧结果清空；「停止」在语句开跑前
    /// 置标志就按「已停止」收尾；任务摘除后能立刻再跑。
    #[gpui_kit::test]
    fn sqlite_query_runs_off_ui_thread_and_stops(cx: &mut TestAppContext) {
        isolate_store("sqlite-bg");
        let db = std::env::temp_dir().join(format!("daro_rs_bg_{}.db", std::process::id()));
        let _ = std::fs::remove_file(&db);
        let path = db.to_string_lossy().to_string();
        crate::sqlite_driver::open("bg-seed", &path).unwrap();
        crate::sqlite_driver::execute_stmt("bg-seed", "CREATE TABLE t(a INTEGER)", 1).unwrap();
        crate::sqlite_driver::close("bg-seed");

        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.conns = vec![mock::Connection::new(
                    "后台查询",
                    DbKind::SQLite,
                    "",
                    0,
                    path.clone(),
                    "",
                    "",
                    "",
                    false,
                )];
                a.groups.clear();
                a.sel = Act::Conn(0);
                a.open_connection(0, cx);
            });
            window.render_frame(cx);
            app.update(cx, |a, cx| a.open_query_tab(None, window, cx));
            window.render_frame(cx);
        })
        .unwrap();
        let qid = app.update(cx, |a, _| a.opened.last().unwrap().qid);
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, cx| {
                let ed = a.opened.last().unwrap().qstate.as_ref().unwrap().editor.clone();
                ed.update(cx, |s, cx| {
                    s.set_value("SELECT 1;\nSELECT 2".to_string(), window, cx)
                });
            });
            window.render_frame(cx);
        })
        .unwrap();

        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, cx| a.query_run(qid, false, window, cx));
        })
        .unwrap();
        app.update(cx, |a, _| {
            let q = a.opened.last().unwrap().qstate.as_ref().unwrap();
            assert!(q.job.is_some(), "脚本交给后台线程，页签先挂上任务");
            assert_eq!(q.prompt, Some("执行中…"), "回执没来前只说实话");
            assert!(q.outcomes.is_empty(), "上一轮结果不该冒充这一轮");
        });

        // 「停止」赶在语句开跑前置标志：一条没执行，回执按取消收尾
        app.update(cx, |a, cx| a.query_cancel(qid, cx));
        app.update(cx, |a, _| {
            let q = a.opened.last().unwrap().qstate.as_ref().unwrap();
            assert!(q.stopping, "点了停止立刻显示「停止中…」");
            assert_eq!(q.prompt, Some("执行中…"), "回执没来前不改结论");
        });
        cx.run_until_parked();
        app.update(cx, |a, _| {
            let q = a.opened.last().unwrap().qstate.as_ref().unwrap();
            assert!(q.job.is_none(), "回执落地即摘牌");
            assert!(!q.stopping && q.stopped, "停止中收尾成已停止");
            assert!(q.outcomes.is_empty());
            assert_eq!(q.prompt, Some("已停止"));
        });

        // 摘牌后能立刻再跑，两条语句都出网格
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, cx| a.query_run(qid, false, window, cx));
        })
        .unwrap();
        cx.run_until_parked();
        app.update(cx, |a, _| {
            let q = a.opened.last().unwrap().qstate.as_ref().unwrap();
            assert_eq!(q.outcomes.len(), 2);
            assert_eq!(
                q.outcomes[0].result.as_deref(),
                Some(&[vec!["1".to_string()]][..])
            );
            assert_eq!(
                q.outcomes[1].result.as_deref(),
                Some(&[vec!["2".to_string()]][..])
            );
            assert_eq!(q.pane, 3, "自动停在最新的结果页");
        });

        crate::sqlite_driver::close("后台查询");
        let _ = std::fs::remove_file(&db);
    }

    /// 真库分页：网格只持有当前页，翻页 / 排序 / 筛选全部下推成 SQL；
    /// 有未应用修改时拦住翻页，避免工作集被下一次取数悄悄覆盖。
    #[gpui_kit::test]
    fn sqlite_remote_paging_sort_and_filter(cx: &mut TestAppContext) {
        isolate_store("sqlite-page");
        let db = std::env::temp_dir().join(format!("daro_rs_page_{}.db", std::process::id()));
        let _ = std::fs::remove_file(&db);
        let path = db.to_string_lossy().to_string();
        crate::sqlite_driver::open("sqlite-page-seed", &path).unwrap();
        crate::sqlite_driver::with_raw("sqlite-page-seed", |raw| {
            raw.execute_batch(
                r#"
                CREATE TABLE big(id INTEGER PRIMARY KEY, name TEXT, grp INTEGER);
                INSERT INTO big(id, name, grp)
                WITH RECURSIVE c(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM c WHERE n < 1200)
                SELECT n, 'r' || n, n % 4 FROM c;
                "#,
            )
            .unwrap();
        });
        crate::sqlite_driver::close("sqlite-page-seed");

        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.conns = vec![mock::Connection::new(
                    "本地分页",
                    DbKind::SQLite,
                    "",
                    0,
                    path.clone(),
                    "",
                    "",
                    "",
                    false,
                )];
                a.groups.clear();
                a.open_connection(0, cx);
            });
        })
        .unwrap();
        // 目录（库 / 表清单）先在后台补齐，再谈「双击第 0 张表」
        settle(cx, handle);
        app.update(cx, |a, _| {
            let _ = catalog::objects(&a.conns[0], "main", "", 0);
        });
        settle(cx, handle);
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, cx| a.open_object(Act::Obj(0, 0, NO_SCHEMA, 0, 0), cx));
        })
        .unwrap();
        settle(cx, handle);

        // 首屏：只装一页，不跑 COUNT（满页推不出总数，先空着）
        app.update(cx, |a, _| {
            let t = &a.opened[0];
            assert_eq!(t.data.len(), REMOTE_PAGE_SIZE, "只取当前页");
            let p = t.page.as_ref().unwrap();
            assert_eq!((p.page_no, p.page_size, p.total), (0, REMOTE_PAGE_SIZE, None));
            let (sql, status) = a.table_page_status(t);
            assert!(sql.contains("LIMIT 1000 OFFSET 0"), "{sql}");
            assert!(status.contains("于第 1 页"), "{status}");
            assert!(!status.contains("共 "), "没点末页就不该有总数：{status}");
        });

        // 表头排序下推：升序首行 id=1，再点降序首行 id=1200
        cx.update_window(handle, |_, window, cx| {
            window.click("th/0", cx);
            window.render_frame(cx);
        })
        .unwrap();
        settle(cx, handle);
        app.update(cx, |a, _| {
            let t = &a.opened[0];
            assert_eq!(t.sort, Some((0, true)));
            assert_eq!(t.data[0][0], "1");
            let (sql, _) = a.table_page_status(t);
            assert!(sql.contains("ORDER BY \"id\" ASC"), "{sql}");
        });
        cx.update_window(handle, |_, window, cx| {
            window.click("th/0", cx);
            window.render_frame(cx);
        })
        .unwrap();
        settle(cx, handle);
        app.update(cx, |a, _| {
            assert_eq!(a.opened[0].data[0][0], "1200", "降序后首行变了");
        });

        // 翻到末页只有 200 行：不满一页，总数按「页起点 + 实取行数」直接定下
        app.update(cx, |a, cx| a.grid_page_to(1, cx));
        settle(cx, handle);
        app.update(cx, |a, _| {
            let t = &a.opened[0];
            let p = t.page.as_ref().unwrap();
            assert_eq!((p.page_no, p.total), (1, Some(1200)));
            assert_eq!(t.data.len(), 200);
            let (_, status) = a.table_page_status(t);
            assert!(status.contains("共 1200 条"), "{status}");
            assert!(status.contains("于第 2 页"), "{status}");
        });

        // 脏页拦住翻页（改了会被下一次取数覆盖）
        app.update(cx, |a, _| a.opened[0].data[0][1] = "脏".into());
        app.update(cx, |a, cx| a.grid_page_to(0, cx));
        app.update(cx, |a, cx| {
            assert_eq!(
                a.opened[0].page.as_ref().unwrap().page_no,
                1,
                "未应用修改时不翻页"
            );
            a.grid_revert(cx);
        });
        settle(cx, handle);

        // 筛选下推：WHERE 进 SQL，总行数随条件收缩并回到首页
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, _| {
                let t = &mut a.opened[0];
                t.filter.model = filter::parse_where(DbKind::SQLite, &t.cols, "grp = 1").unwrap();
            });
            app.update(cx, |a, cx| a.filter_apply(window, cx));
        })
        .unwrap();
        settle(cx, handle);
        app.update(cx, |a, _| {
            let t = &a.opened[0];
            let p = t.page.as_ref().unwrap();
            assert_eq!((p.page_no, p.total), (0, Some(300)), "条件变了回首页");
            assert_eq!(t.data.len(), 300);
            assert!(t.data.iter().all(|r| r[2] == "1"), "只留 grp=1");
            let (sql, _) = a.table_page_status(t);
            assert!(sql.contains("WHERE \"grp\" = 1"), "{sql}");
        });

        crate::sqlite_driver::close("本地分页");
        let _ = std::fs::remove_file(&db);
    }

    /// 总数只在点「最后一页」时统计：打开表不跑 COUNT；点了才跑一次并跳到末页。
    /// 「下一页」翻到空页时按「上一页满页」把总数补出来，人留在原页。
    #[gpui_kit::test]
    fn sqlite_last_page_counts_on_demand(cx: &mut TestAppContext) {
        isolate_store("sqlite-lastpage");
        let db =
            std::env::temp_dir().join(format!("daro_rs_lastpage_{}.db", std::process::id()));
        let _ = std::fs::remove_file(&db);
        let path = db.to_string_lossy().to_string();
        crate::sqlite_driver::open("sqlite-lastpage-seed", &path).unwrap();
        crate::sqlite_driver::with_raw("sqlite-lastpage-seed", |raw| {
            raw.execute_batch(
                r#"
                CREATE TABLE big(id INTEGER PRIMARY KEY, name TEXT);
                INSERT INTO big(id, name)
                WITH RECURSIVE c(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM c WHERE n < 1200)
                SELECT n, 'r' || n FROM c;
                CREATE TABLE even(id INTEGER PRIMARY KEY, name TEXT);
                INSERT INTO even(id, name)
                WITH RECURSIVE c(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM c WHERE n < 1000)
                SELECT n, 'r' || n FROM c;
                "#,
            )
            .unwrap();
        });
        crate::sqlite_driver::close("sqlite-lastpage-seed");

        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.conns = vec![mock::Connection::new(
                    "末页计数",
                    DbKind::SQLite,
                    "",
                    0,
                    path.clone(),
                    "",
                    "",
                    "",
                    false,
                )];
                a.groups.clear();
                a.open_connection(0, cx);
            });
        })
        .unwrap();
        settle(cx, handle);
        app.update(cx, |a, _| {
            let _ = catalog::objects(&a.conns[0], "main", "", 0);
        });
        settle(cx, handle);
        let big = app.update(cx, |a, _| {
            catalog::objects(&a.conns[0], "main", "", 0)
                .iter()
                .position(|n| *n == "big")
                .expect("目录里有 big")
        });
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, cx| a.open_object(Act::Obj(0, 0, NO_SCHEMA, 0, big), cx));
        })
        .unwrap();
        settle(cx, handle);

        // 打开表：满页推不出总数，先空着（跑过 COUNT 这里就会是 1200）
        app.update(cx, |a, _| {
            let p = a.opened[0].page.as_ref().unwrap();
            assert_eq!((p.page_no, p.total), (0, None), "打开表不跑 COUNT");
        });

        // 点「最后一页」：这时才统计，拿到 1200 直接落到末页
        app.update(cx, |a, cx| a.grid_last_page(cx));
        settle(cx, handle);
        app.update(cx, |a, _| {
            let t = &a.opened[0];
            let p = t.page.as_ref().unwrap();
            assert_eq!((p.page_no, p.total), (1, Some(1200)), "统计后落在末页");
            assert_eq!(t.data.len(), 200, "末页只剩 200 行");
            let (_, status) = a.table_page_status(t);
            assert!(status.contains("共 1200 条"), "{status}");
            assert!(status.contains("于第 2 页"), "{status}");
        });

        // 正好整页的表：下一页是空页，回执按「页起点」定总数并留在原页
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.conns = vec![mock::Connection::new(
                    "空页推断",
                    DbKind::SQLite,
                    "",
                    0,
                    path.clone(),
                    "",
                    "",
                    "",
                    false,
                )];
                a.groups.clear();
                a.open_connection(0, cx);
            });
        })
        .unwrap();
        settle(cx, handle);
        app.update(cx, |a, _| {
            let _ = catalog::objects(&a.conns[0], "main", "", 0);
        });
        settle(cx, handle);
        let even = app.update(cx, |a, _| {
            catalog::objects(&a.conns[0], "main", "", 0)
                .iter()
                .position(|n| *n == "even")
                .expect("目录里有 even")
        });
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, cx| a.open_object(Act::Obj(0, 0, NO_SCHEMA, 0, even), cx));
        })
        .unwrap();
        settle(cx, handle);
        app.update(cx, |a, cx| a.grid_page_to(1, cx));
        settle(cx, handle);
        app.update(cx, |a, _| {
            let t = a.opened.last().unwrap();
            let p = t.page.as_ref().unwrap();
            assert_eq!((p.page_no, p.total), (0, Some(1000)), "空页补出总数，人不动");
            assert_eq!(t.data.len(), 1000);
            let (_, status) = a.table_page_status(t);
            assert!(status.contains("共 1000 条"), "{status}");
            assert!(status.contains("于第 1 页"), "{status}");
        });

        crate::sqlite_driver::close("末页计数");
        crate::sqlite_driver::close("空页推断");
        let _ = std::fs::remove_file(&db);
    }

    /// 「美化 SQL」钮真的改写编辑器正文（不再是个灰摆设）。
    #[gpui_kit::test]
    fn query_prettify_button_rewrites_editor(cx: &mut TestAppContext) {
        isolate_store("qpretty");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| a.open_query_tab(None, window, cx));
            window.render_frame(cx);
        })
        .unwrap();
        cx.update_window(handle, |_, window, cx| {
            let ed = app.update(cx, |a, _| a.opened[0].qstate.as_ref().unwrap().editor.clone());
            ed.update(cx, |s, cx| {
                s.set_value("select a,b from t where a>1 and b<2", window, cx)
            });
            window.render_frame(cx);
            window.click("qp/pretty", cx);
            window.render_frame(cx);
        })
        .unwrap();
        app.update(cx, |a, cx| {
            let q = a.opened[0].qstate.as_ref().unwrap();
            assert_eq!(
                q.editor.read(cx).value().to_string(),
                "SELECT a,\n  b\nFROM t\nWHERE a > 1\n  AND b < 2"
            );
            assert!(q.dirty, "美化算一次编辑");
        });
    }

    /// 美化 SQL 后 Ctrl+Z 退回美化前的正文：写回用 replace_all 而不是
    /// set_value（后者清空撤销栈，美化就变成撤不掉的操作）。
    #[gpui_kit::test]
    fn query_prettify_is_undoable(cx: &mut TestAppContext) {
        isolate_store("qprettyundo");
        const SQL: &str = "select a,b from t where a>1 and b<2";
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| a.open_query_tab(None, window, cx));
            window.render_frame(cx);
        })
        .unwrap();
        cx.update_window(handle, |_, window, cx| {
            let ed = app.update(cx, |a, _| a.opened[0].qstate.as_ref().unwrap().editor.clone());
            ed.update(cx, |s, cx| s.set_value(SQL, window, cx));
            window.render_frame(cx);
            window.click("qp/pretty", cx);
            window.render_frame(cx);
            let formatted = ed.read(cx).value().to_string();
            assert_ne!(formatted, SQL, "先确认美化真的改写了正文");
            // 撤掉美化要焦点在编辑器里，否则 ctrl-z 落到别的上下文
            ed.update(cx, |s, cx| s.focus(window, cx));
            window.render_frame(cx);
            window.press("ctrl-z", cx);
            window.render_frame(cx);
        })
        .unwrap();
        app.update(cx, |a, cx| {
            assert_eq!(
                a.opened[0].qstate.as_ref().unwrap().editor.read(cx).value().to_string(),
                SQL,
                "Ctrl+Z 撤掉美化，正文回到美化前"
            );
        });
    }

    /// 顶栏「格式」菜单照参考界面查询窗口截图：缩进 ▸ / 注释 ▸ / 转换大小写 ▸ ─
    /// 美化 SQL / 美化 SQL 选项... / 简化 SQL ─ 重构 ▸。两档真功能连着行为一起验：
    /// 缩进派编辑器的 Indent / Outdent（正文只多 / 少一层空白），美化 SQL 与工具条
    /// 那颗钮同一个 `query_prettify` 口径。
    #[gpui_kit::test]
    fn format_bar_menu_matches_reference_query_window(cx: &mut TestAppContext) {
        isolate_store("formatbarmenu");
        const SQL: &str = "select a,b from t where a>1;";
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| a.open_query_tab(None, window, cx));
            window.render_frame(cx);
            let ed = app.update(cx, |a, _| a.opened[0].qstate.as_ref().unwrap().editor.clone());
            ed.update(cx, |s, cx| s.set_value(SQL, window, cx));
            window.render_frame(cx);
            // 菜单条平时收在 ☰ 里，点开才铺开（「文件」菜单随 ☰ 一起弹出）
            window.click("title-menu", cx);
            window.render_frame(cx);
            window.click("格式", cx);
            window.render_frame(cx);
            window.render_frame(cx);
            for label in [
                "缩进",
                "注释",
                "转换大小写",
                "美化 SQL",
                "美化 SQL 选项...",
                "简化 SQL",
                "重构",
            ] {
                assert!(
                    window.try_find_by_label(label).is_some(),
                    "格式菜单缺「{label}」"
                );
            }
            // 缩进 ▸ 是第 0 行；子菜单第 0 行 = 增加缩排
            window.hover(0usize, cx);
            window.render_frame(cx);
            window.render_frame(cx);
            window.within("submenu").click(0usize, cx);
            window.render_frame(cx);
            let v = ed.read(cx).value().to_string();
            assert_eq!(v.trim_start(), SQL, "只往行首加空白，不动语句");
            assert_ne!(v, SQL, "增加缩排真的改到正文了");
        })
        .unwrap();

        // 减少缩排（子菜单第 1 行）把空白退回去
        cx.update_window(handle, |_, window, cx| {
            window.click("title-menu", cx);
            window.render_frame(cx);
            window.click("格式", cx);
            window.render_frame(cx);
            window.render_frame(cx);
            window.hover(0usize, cx);
            window.render_frame(cx);
            window.render_frame(cx);
            window.within("submenu").click(1usize, cx);
            window.render_frame(cx);
        })
        .unwrap();
        let back = app.update(cx, |a, cx| {
            a.opened[0]
                .qstate
                .as_ref()
                .unwrap()
                .editor
                .read(cx)
                .value()
                .to_string()
        });
        assert_eq!(back, SQL, "减少缩排退回原正文");

        // 美化 SQL（顶层第 5 行，0 基含分隔线）与工具条「qp/pretty」同一结果
        let want = sql_format::pretty(&back);
        cx.update_window(handle, |_, window, cx| {
            window.click("title-menu", cx);
            window.render_frame(cx);
            window.click("格式", cx);
            window.render_frame(cx);
            window.render_frame(cx);
            window.click(4usize, cx);
            window.render_frame(cx);
        })
        .unwrap();
        app.update(cx, |a, cx| {
            let q = a.opened[0].qstate.as_ref().unwrap();
            assert_eq!(
                q.editor.read(cx).value().to_string(),
                want,
                "菜单「美化 SQL」走的就是工具条那颗钮的格式化"
            );
            assert!(q.dirty, "美化算一次编辑");
        });
    }

    /// 顶栏「工具」菜单照参考界面截图逐行：数据传输 / 数据生成 / 数据脱敏 / 数据字典 /
    /// 数据同步 / 结构同步 / 命令列界面（灰）/ 服务器监控 / 在数据库或模式中查找 ─
    /// 历史日志 ─ 选项。除「选项...」外这些功能 daro 一件都没实现，除子菜单留占位外
    /// 全是死标签；截图上的 F6 / Ctrl+L / Ctrl+, 不搬进来（没有对应绑定，写了就是假提示）。
    #[gpui_kit::test]
    fn tools_bar_menu_matches_reference(cx: &mut TestAppContext) {
        isolate_store("toolsbarmenu");
        let (handle, app) = open_app(cx);
        // 「选项...」走 OpenOptions 动作，处理器来自这条装配
        cx.update(|cx| wire_global_keys(app.clone(), handle, cx));
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            window.click("title-menu", cx);
            window.render_frame(cx);
            window.click("工具", cx);
        })
        .unwrap();
        let base = cx.windows().len();
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            window.render_frame(cx);
            for label in [
                "数据传输...",
                "数据生成...",
                "数据脱敏...",
                "数据字典...",
                "数据同步...",
                "结构同步...",
                "服务器监控",
                "在数据库或模式中查找...",
                "历史日志...",
                "选项...",
            ] {
                assert!(
                    window.try_find_by_label(label).is_some(),
                    "工具菜单缺「{label}」"
                );
            }
            // 备份 / 自动运行是功能区那两颗钮；MCP 设置已并入选项窗，不再占菜单行
            for absent in ["备份...", "自动运行...", "MCP 服务..."] {
                assert!(
                    window.try_find_by_label(absent).is_none(),
                    "工具菜单不该有「{absent}」"
                );
            }
            // 第 6 行「命令列界面...」截图里是灰的，置灰行不挂点击处理器
            window.within("popup-menu").click(6usize, cx);
            window.render_frame(cx);
        })
        .unwrap();
        assert_eq!(cx.windows().len(), base, "灰项点下去不该弹东西");

        // 服务器监控是顶层第 7 行（0 基含分隔线）：下标对得上截图顺序，子菜单留占位
        cx.update_window(handle, |_, window, cx| {
            window.hover(7usize, cx);
            window.render_frame(cx);
            window.render_frame(cx);
            assert!(
                window
                    .within("submenu")
                    .try_find_by_label("（子菜单内容待截图核对）")
                    .is_some(),
                "服务器监控子菜单缺占位"
            );
        })
        .unwrap();
    }

    /// MCP 设置已并入「工具 ▸ 选项...」：导航「扩展 ▸ MCP 服务」里能看到开关 /
    /// 三档模式 / 端口 / 令牌 / 复制配置。不点开关——那会真的拉起后台进程；跑进程的链路
    /// 由 `tests/mcp.rs` 端到端覆盖。
    #[gpui_kit::test]
    fn mcp_page_renders_in_options(cx: &mut TestAppContext) {
        isolate_store("mcp-page");
        let (handle, app) = open_app(cx);
        cx.update(|cx| wire_global_keys(app.clone(), handle, cx));
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            window.click("title-menu", cx);
            window.render_frame(cx);
            window.click("工具", cx);
            window.render_frame(cx);
            window.render_frame(cx);
            // 顶层第 12 行：… / 分隔线(11) / 选项(12)
            window.within("popup-menu").click(12usize, cx);
            window.render_frame(cx);
        })
        .unwrap();
        settle(cx, handle);
        let windows = cx.windows();
        assert_eq!(windows.len(), 2, "点「选项...」应弹出设置窗");
        let options = *windows.last().unwrap();
        cx.update_window(options, |_, window, cx| {
            window.render_frame(cx);
            assert!(
                window.try_find("options-nav-5").is_some(),
                "选项窗缺 MCP 分类"
            );
            window.click("options-nav-5", cx);
            window.render_frame(cx);
            for id in [
                "mcp-enabled",
                "mcp-status",
                "mcp-mode-readonly",
                "mcp-mode-readWrite",
                "mcp-mode-full",
                "mcp-port-apply",
                "mcp-copy-config",
                "mcp-token-rotate",
            ] {
                assert!(window.try_find(id).is_some(), "MCP 页缺控件 {id}");
            }
            assert!(
                window.try_find("mcp-close").is_none(),
                "并入选项窗后不该再有独立的关闭按钮"
            );
            window.click("options-cancel", cx);
            window.render_frame(cx);
        })
        .unwrap();
        settle(cx, handle);
        assert_eq!(cx.windows().len(), 1, "取消收回选项窗");
    }

    /// 「工具 ▸ 选项...」不是死标签：开设置窗 → 改窗格 / 结果页 → 确定落状态与存档。
    #[gpui_kit::test]
    fn options_dialog_applies_and_persists(cx: &mut TestAppContext) {
        isolate_store("options-dialog-apply");
        let (handle, app) = open_app(cx);
        // 菜单行走 OpenOptions 动作，动作监听由 wire_global_keys 装配
        cx.update(|cx| wire_global_keys(app.clone(), handle, cx));
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            window.click("title-menu", cx);
            window.render_frame(cx);
            window.click("工具", cx);
            window.render_frame(cx);
            window.render_frame(cx);
            // 顶层第 12 行（0 基含分隔线）：历史日志(10) / 分隔线(11) / 选项(12)
            window.within("popup-menu").click(12usize, cx);
            window.render_frame(cx);
        })
        .unwrap();
        // 「选项...」走 OpenOptions 动作，动作派发延迟一拍（窗口在 defer 里开）
        settle(cx, handle);
        let windows = cx.windows();
        assert_eq!(windows.len(), 2, "点「选项...」应弹出设置窗");
        let options = *windows.last().unwrap();
        cx.update_window(options, |_, window, cx| {
            window.render_frame(cx);
            for ix in 0..6 {
                assert!(
                    window.try_find(format!("options-nav-{ix}")).is_some(),
                    "选项窗缺第 {ix} 个分类"
                );
            }
            // 分组标题可折叠：收起「外观」后组内两项一起消失，再点恢复
            window.click("options-group-1", cx);
            window.render_frame(cx);
            assert!(
                window.try_find("options-nav-1").is_none(),
                "折叠分组后子项该隐藏"
            );
            window.click("options-group-1", cx);
            window.render_frame(cx);
            assert!(
                window.try_find("options-nav-1").is_some(),
                "展开分组后子项该回来"
            );
            // 界面字体页：常规页只有版本与数据目录，字体挪到「外观 ▸ 界面字体」
            window.click("options-nav-2", cx);
            window.render_frame(cx);
            assert!(
                window.try_find("options-ui-font").is_some(),
                "界面字体页缺字体下拉"
            );
            // 面板与视图页：关掉导航窗格
            window.click("options-nav-3", cx);
            window.render_frame(cx);
            window.click("options-show-tree", cx);
            window.render_frame(cx);
            // 「常显菜单栏」也是落盘开关
            window.click("options-show-menus", cx);
            window.render_frame(cx);
            // 结果页：执行后默认显示改到「消息」
            window.click("options-nav-4", cx);
            window.render_frame(cx);
            window.click("options-run-message", cx);
            window.render_frame(cx);
            window.click("options-ok", cx);
            window.render_frame(cx);
        })
        .unwrap();
        settle(cx, handle);
        assert_eq!(cx.windows().len(), 1, "确定后设置窗收回");
        app.update(cx, |a, _| {
            assert!(!a.show_tree, "关闭导航窗格已应用");
            assert!(a.show_menus, "常显菜单栏已应用");
            assert_eq!(a.run_pane, 0, "执行后默认显示改到「消息」");
        });
        let saved = std::fs::read_to_string(store_path()).unwrap();
        assert!(
            saved.contains("\"show_tree\": false"),
            "存档落 show_tree=false：{saved}"
        );
        assert!(
            saved.contains("\"show_menus\": true"),
            "存档落 show_menus=true：{saved}"
        );
        assert!(
            saved.contains("\"run_pane\": 0"),
            "存档落 run_pane=0：{saved}"
        );
    }

