    /// 色板清单是 Zed 内置十一档 + VS Code 2026 明暗两档（先暗后亮、组内按名字），
    /// 明暗切换要落到同系列、同对比度的对应档。
    #[test]
    fn theme_palette_covers_zed_families() {
        let names: Vec<&str> = palette::THEMES.iter().map(|t| t.name).collect();
        assert_eq!(
            names,
            [
                "Ayu Dark",
                "Ayu Mirage",
                "Dark 2026",
                "Gruvbox Dark",
                "Gruvbox Dark Hard",
                "Gruvbox Dark Soft",
                "One Dark",
                "Ayu Light",
                "Gruvbox Light",
                "Gruvbox Light Hard",
                "Gruvbox Light Soft",
                "Light 2026",
                "One Light",
            ],
            "主题清单与选主题面板同序"
        );
        assert_eq!(
            palette::THEMES.iter().filter(|t| t.dark).count(),
            7,
            "暗色七档"
        );
        let lum = |hex: u32| {
            let chan = |v: u32| {
                let v = v as f32 / 255.0;
                if v <= 0.03928 {
                    v / 12.92
                } else {
                    ((v + 0.055) / 1.055).powf(2.4)
                }
            };
            0.2126 * chan((hex >> 16) & 0xff)
                + 0.7152 * chan((hex >> 8) & 0xff)
                + 0.0722 * chan(hex & 0xff)
        };
        for (ix, theme) in palette::THEMES.iter().enumerate() {
            let pair = &palette::THEMES[theme.counterpart];
            assert_ne!(pair.dark, theme.dark, "{} 的对应档要换明暗", theme.name);
            // Ayu Mirage 的亮色也落在 Ayu Light，所以只对普通成对的档要求对称
            if ix != 1 {
                assert_eq!(pair.counterpart, ix, "{} 的对应档要成对", theme.name);
            }
            let p = theme.palette;
            let (fg, bg) = (lum(p.foreground), lum(p.background));
            let ratio = (fg.max(bg) + 0.05) / (fg.min(bg) + 0.05);
            assert!(
                ratio >= 4.5,
                "{}：正文与背景对比度 {ratio:.1} 低于 4.5",
                theme.name
            );
        }
    }

    /// 「查看 ▸ 显示 ▸ 选择主题...」开 Zed 式主题清单：十一档都在，点一行立刻换主题、
    /// 收窗并落盘；顶栏切换按钮跟着落到同系列的相反明暗档。
    #[gpui_kit::test]
    fn theme_dialog_applies_theme_and_toggle_follows_family(cx: &mut TestAppContext) {
        isolate_store("theme-dialog");
        let (handle, app) = open_app(cx);
        cx.update(|cx| wire_global_keys(app.clone(), handle, cx));
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            // 「显示 ▸」是页签级子菜单，先开一个查询页制造页签上下文
            app.update(cx, |a, cx| a.open_query_tab(None, window, cx));
            window.render_frame(cx);
            window.click("title-menu", cx);
            window.render_frame(cx);
            window.click("查看", cx);
            window.render_frame(cx);
            window.render_frame(cx);
            window.hover(15usize, cx);
            window.render_frame(cx);
            window.render_frame(cx);
            // 显示 ▸ 最后一行：切换主题(13) / 选择主题...(14)
            window.within("submenu").click(14usize, cx);
            window.render_frame(cx);
        })
        .unwrap();
        settle(cx, handle);
        assert_eq!(cx.windows().len(), 2, "「选择主题...」应弹出主题窗");
        let dialog = *cx.windows().last().unwrap();
        cx.update_window(dialog, |_, window, cx| {
            window.render_frame(cx);
            window.render_frame(cx);
            for (ix, name) in [
                (0, "Ayu Dark"),
                (1, "Ayu Mirage"),
                (2, "Dark 2026"),
                (3, "Gruvbox Dark"),
                (4, "Gruvbox Dark Hard"),
                (5, "Gruvbox Dark Soft"),
                (6, "One Dark"),
                (7, "Ayu Light"),
                (8, "Gruvbox Light"),
                (9, "Gruvbox Light Hard"),
                (10, "Gruvbox Light Soft"),
                (11, "Light 2026"),
                (12, "One Light"),
            ] {
                assert!(
                    window.try_find(format!("theme-row-{ix}")).is_some(),
                    "主题清单缺「{name}」"
                );
            }
            // 搜索是真过滤：输 gruvbox 只剩六档
            window.input("gruvbox", cx);
            window.render_frame(cx);
            assert!(window.try_find("theme-row-0").is_none(), "搜索滤掉 Ayu");
            assert!(window.try_find("theme-row-3").is_some(), "Gruvbox 还在");
            for _ in 0.."gruvbox".len() {
                window.press("backspace", cx);
            }
            window.render_frame(cx);
            // 悬浮即预览：主窗立刻换成这档，但这一下不落盘
            let original = palette::active().name;
            window.hover("theme-row-3", cx);
            window.render_frame(cx);
            assert_eq!(palette::active().name, "Gruvbox Dark", "悬浮立即预览");
            let saved = std::fs::read_to_string(store_path()).unwrap_or_default();
            assert!(!saved.contains("Gruvbox Dark"), "悬浮预览不落盘：{saved}");
            assert!(app.update(cx, |a, _| a.dark), "主窗跟着换成暗色");
            // 指针移去搜索框：预览退回开窗那一档
            window.hover("theme-search", cx);
            window.render_frame(cx);
            assert_eq!(palette::active().name, original, "离开清单退回原档");
            assert_eq!(
                app.update(cx, |a, _| a.dark),
                palette::active().dark,
                "主窗明暗也跟着退回"
            );
            // 再点 Gruvbox Dark：这次才落盘并收窗
            window.click("theme-row-3", cx);
            window.render_frame(cx);
        })
        .unwrap();
        settle(cx, handle);
        assert_eq!(cx.windows().len(), 1, "选完主题窗收回");
        app.update(cx, |a, _| {
            assert!(a.dark, "Gruvbox Dark 是暗色");
            assert_eq!(palette::active().name, "Gruvbox Dark");
        });
        let saved = std::fs::read_to_string(store_path()).unwrap();
        assert!(
            saved.contains("\"theme\": \"Gruvbox Dark\""),
            "存档落主题名：{saved}"
        );

        // 顶栏切换：Gruvbox Dark → Gruvbox Light（同系列、同对比度）
        app.update(cx, |a, cx| a.toggle_theme(cx));
        app.update(cx, |a, _| {
            assert!(!a.dark);
            assert_eq!(palette::active().name, "Gruvbox Light");
        });
    }

    /// 标题栏右上角应用菜单：菜单项都是真人口。设置走 OpenOptions 动作开选项窗
    /// （Ctrl+, 是同一动作），面板布局子菜单翻两块窗格并把宽度复位、落盘。
    #[gpui_kit::test]
    fn app_menu_wires_settings_and_panel_layout(cx: &mut TestAppContext) {
        isolate_store("app-menu");
        let (handle, app) = open_app(cx);
        // 应用菜单里的设置项是动作，绑定与处理器都在这条装配里
        cx.update(|cx| wire_global_keys(app.clone(), handle, cx));
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            window.click("app-menu", cx);
        })
        .unwrap();
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            window.render_frame(cx);
            assert!(
                window.try_find_by_label("设置...").is_some(),
                "应用菜单缺「设置...」"
            );
            assert!(
                window.try_find_by_label("主题...").is_some(),
                "应用菜单缺「主题...」"
            );
            assert!(
                window.try_find_by_label("扩展...").is_some(),
                "应用菜单缺「扩展...」"
            );
            assert!(
                window.try_find_by_label("面板布局").is_some(),
                "应用菜单缺「面板布局」"
            );
            // 还没落地的能力不挂灰行
            for absent in ["快捷键...", "图标主题..."] {
                assert!(
                    window.try_find_by_label(absent).is_none(),
                    "应用菜单不该先挂「{absent}」"
                );
            }
            window.within("popup-menu").click(0usize, cx);
            window.render_frame(cx);
        })
        .unwrap();
        // 菜单项走动作，动作派发本身是延迟的（Window::dispatch_action → defer）
        settle(cx, handle);
        assert_eq!(cx.windows().len(), 2, "点「设置...」应弹出选项窗");
        let options = *cx.windows().last().unwrap();
        cx.update_window(options, |_, window, cx| {
            window.render_frame(cx);
            assert!(window.try_find("options-nav-0").is_some(), "开的是选项窗");
            window.click("options-cancel", cx);
            window.render_frame(cx);
        })
        .unwrap();
        settle(cx, handle);
        assert_eq!(cx.windows().len(), 1, "取消收回选项窗");

        // Ctrl+, 与菜单项是同一个动作
        cx.update_window(handle, |_, window, cx| {
            window.press("ctrl-,", cx);
            window.render_frame(cx);
        })
        .unwrap();
        settle(cx, handle);
        assert_eq!(cx.windows().len(), 2, "Ctrl+, 也开选项窗");
        let options = *cx.windows().last().unwrap();
        cx.update_window(options, |_, window, cx| {
            window.render_frame(cx);
            window.click("options-cancel", cx);
            window.render_frame(cx);
        })
        .unwrap();
        settle(cx, handle);
        assert_eq!(cx.windows().len(), 1, "取消收回选项窗");

        // 右上角「主题...」：开同一份主题清单，点一行立刻生效并收窗
        cx.update_window(handle, |_, window, cx| {
            window.click("app-menu", cx);
            window.render_frame(cx);
            window.render_frame(cx);
            window.within("popup-menu").click(1usize, cx);
            window.render_frame(cx);
        })
        .unwrap();
        settle(cx, handle);
        assert_eq!(cx.windows().len(), 2, "点「主题...」应弹出主题窗");
        let theme_win = *cx.windows().last().unwrap();
        cx.update_window(theme_win, |_, window, cx| {
            window.render_frame(cx);
            window.render_frame(cx);
            assert!(window.try_find("theme-row-7").is_some(), "主题清单已列出");
            window.click("theme-row-7", cx);
            window.render_frame(cx);
        })
        .unwrap();
        settle(cx, handle);
        assert_eq!(cx.windows().len(), 1, "选完主题窗收回");
        app.update(cx, |a, _| {
            assert!(!a.dark, "Ayu Light 是亮色");
            assert_eq!(palette::active().name, "Ayu Light");
        });

        app.update(cx, |a, _| {
            a.show_tree = true;
            a.show_info = true;
            a.left_w = 300.;
            a.right_w = 400.;
        });
        // 面板布局（顶层第 5 行，0 基含分隔线）：导航窗格 / 信息窗格 / 分隔线 / 重置宽度
        cx.update_window(handle, |_, window, cx| {
            window.click("app-menu", cx);
            window.render_frame(cx);
            window.render_frame(cx);
            window.hover(4usize, cx);
            window.render_frame(cx);
            window.render_frame(cx);
            for label in ["显示导航窗格", "显示信息窗格", "重置面板宽度"] {
                assert!(
                    window.within("submenu").try_find_by_label(label).is_some(),
                    "面板布局子菜单缺「{label}」"
                );
            }
            window.within("submenu").click(0usize, cx);
            window.render_frame(cx);
        })
        .unwrap();
        app.read_with(cx, |a, _| assert!(!a.show_tree, "第一行关掉导航窗格"));

        cx.update_window(handle, |_, window, cx| {
            window.click("app-menu", cx);
            window.render_frame(cx);
            window.render_frame(cx);
            window.hover(4usize, cx);
            window.render_frame(cx);
            window.render_frame(cx);
            window.within("submenu").click(1usize, cx);
            window.render_frame(cx);
        })
        .unwrap();
        app.read_with(cx, |a, _| assert!(!a.show_info, "第二行关掉信息窗格"));

        cx.update_window(handle, |_, window, cx| {
            window.click("app-menu", cx);
            window.render_frame(cx);
            window.render_frame(cx);
            window.hover(4usize, cx);
            window.render_frame(cx);
            window.render_frame(cx);
            window.within("submenu").click(3usize, cx);
            window.render_frame(cx);
        })
        .unwrap();
        app.update(cx, |a, _| {
            assert_eq!(a.left_w, LEFT_W, "重置到默认左栏宽");
            assert_eq!(a.right_w, RIGHT_W, "重置到默认右栏宽");
        });
        let saved = std::fs::read_to_string(store_path()).unwrap();
        assert!(
            saved.contains("\"show_tree\": false") && saved.contains("\"show_info\": false"),
            "两块窗格的显隐已落盘：{saved}"
        );
    }

    /// 扩展窗：内置驱动与未接入引擎都列出来，搜索 / 状态 / 分类三路过滤是真过滤；
    /// 内置驱动的「新建连接」按类型直开表单（跳过类型选择、补默认端口）。
    #[gpui_kit::test]
    fn extensions_dialog_lists_drivers_and_preseeds_connection(cx: &mut TestAppContext) {
        isolate_store("extensions");
        let (handle, app) = open_app(cx);
        cx.update(|cx| wire_global_keys(app.clone(), handle, cx));
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            window.click("app-menu", cx);
            window.render_frame(cx);
            window.render_frame(cx);
            window.within("popup-menu").click(2usize, cx);
            window.render_frame(cx);
        })
        .unwrap();
        // 菜单行是动作，开窗落在 defer 里
        settle(cx, handle);
        assert_eq!(cx.windows().len(), 2, "点「扩展...」应弹出扩展窗");
        let ext = *cx.windows().last().unwrap();
        cx.update_window(ext, |_, window, cx| {
            window.render_frame(cx);
            window.render_frame(cx);
            assert!(window.try_find("ext-state-0").is_some(), "开的是扩展窗（状态筛选条在）");
            for slug in [
                "ext-card-mysql",
                "ext-card-postgresql",
                "ext-card-sqlserver",
                "ext-card-sqlite",
                "ext-card-mongodb",
                "ext-card-redis",
                "ext-card-oracle",
                "ext-card-mariadb",
                "ext-card-snowflake",
            ] {
                assert!(window.try_find(slug).is_some(), "扩展清单缺 {slug}");
            }
            assert!(window.try_find("ext-connect-mysql").is_some(), "内置驱动给新建连接");
            assert!(window.try_find("ext-missing-oracle").is_some(), "未接入驱动保留状态按钮");

            // 状态筛选：未接入只剩三张未接入卡
            window.click("ext-state-2", cx);
            window.render_frame(cx);
            assert!(window.try_find("ext-card-oracle").is_some());
            assert!(window.try_find("ext-card-mysql").is_none(), "已内置卡被筛掉");

            // 分类筛选叠上去：未接入里没有键值型 → 空态
            window.click("ext-cat-3", cx);
            window.render_frame(cx);
            assert!(window.try_find("ext-empty").is_some(), "没有键值型未接入项");

            // 回到全部
            window.click("ext-state-0", cx);
            window.click("ext-cat-0", cx);
            window.render_frame(cx);

            // 搜索是真过滤（开窗焦点在搜索框）
            window.input("redis", cx);
            window.render_frame(cx);
            assert!(window.try_find("ext-card-redis").is_some());
            assert!(window.try_find("ext-card-mysql").is_none(), "搜索滤掉不匹配的卡");

            // 清空搜索：逐字退格
            for _ in 0.."redis".len() {
                window.press("backspace", cx);
            }
            window.render_frame(cx);
            assert!(window.try_find("ext-card-mysql").is_some(), "清空搜索后全部回来");

            // 内置驱动直开新建连接：跳过类型选择，默认端口已补
            window.click("ext-connect-mysql", cx);
            window.render_frame(cx);
        })
        .unwrap();
        settle(cx, ext);
        assert_eq!(cx.windows().len(), 3, "「新建连接」应弹出连接窗");
        let conn = *cx.windows().last().unwrap();
        settle(cx, conn);
        cx.update_window(conn, |_, window, cx| {
            window.render_frame(cx);
            window.render_frame(cx);
            assert!(window.try_find("ok").is_some(), "直接落在表单页");
            assert!(window.try_find("back").is_none(), "没有类型选择页，不留「上一步」");
            // 连接窗是从扩展窗里开的，先激活它，键输入才落到本窗的输入框
            window.activate_window();
            window.render_frame(cx);
            // 连接名称已聚焦：填个名字就能保存，保存结果能反查类型与默认值
            window.input("扩展测试", cx);
            window.click("ok", cx);
            window.render_frame(cx);
        })
        .unwrap();
        // remove_window 在 update_window 收尾时生效，保存后连接窗立即收回
        assert_eq!(cx.windows().len(), 2, "保存后收回连接窗");
        app.read_with(cx, |app, _| {
            let conn = app.conns.last().expect("保存出一条连接");
            assert_eq!(conn.name, "扩展测试");
            assert!(conn.kind == DbKind::MySql, "按卡片类型直开");
            assert_eq!(conn.host, "localhost", "主机补默认值");
            assert_eq!(conn.port, 3306, "端口补默认值");
            assert_eq!(conn.user, "root", "MySQL 用户名补默认值");
        });

        // 保存会选中新连接并自动建连；localhost 上没有 MySQL，失败回执弹「连接失败」
        // 确认框。这不是扩展页的行为，点掉它再继续。
        settle(cx, handle);
        let prompt = cx.windows().into_iter().find(|h| *h != handle && *h != ext);
        if let Some(prompt) = prompt {
            cx.update_window(prompt, |_, window, cx| {
                window.render_frame(cx);
                window.click("cancel", cx);
                window.render_frame(cx);
            })
            .unwrap();
            settle(cx, handle);
        }
        assert_eq!(cx.windows().len(), 2, "只剩主窗与扩展窗");

        // Esc 收回扩展窗，Ctrl+Shift+X 与菜单项是同一个动作。
        // 连接窗开过一轮后扩展窗已失活，先激活它按键才进本窗。
        cx.update_window(ext, |_, window, cx| {
            window.activate_window();
            window.render_frame(cx);
            window.press("escape", cx);
            window.render_frame(cx);
        })
        .unwrap();
        settle(cx, handle);
        assert_eq!(cx.windows().len(), 1, "Esc 收回扩展窗");
        cx.update_window(handle, |_, window, cx| {
            window.press("ctrl-shift-x", cx);
            window.render_frame(cx);
        })
        .unwrap();
        settle(cx, handle);
        assert_eq!(cx.windows().len(), 2, "Ctrl+Shift+X 也开扩展窗");
        let ext = *cx.windows().last().unwrap();
        cx.update_window(ext, |_, window, cx| {
            window.activate_window();
            window.render_frame(cx);
            assert!(window.try_find("ext-state-0").is_some());
            window.press("escape", cx);
            window.render_frame(cx);
        })
        .unwrap();
        settle(cx, handle);
        assert_eq!(cx.windows().len(), 1, "Esc 收回扩展窗");
    }

    /// 顶栏「帮助」菜单只保留三条真落点的项：反馈 / 检查更新 / 关于，
    /// 并用「不出现」断言守住已移除的 6 个占位项；连着行为验「关于...」开关于窗、关掉收回。
    #[gpui_kit::test]
    fn help_bar_menu_matches_reference(cx: &mut TestAppContext) {
        isolate_store("helpbarmenu");
        let (handle, _app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            window.click("title-menu", cx);
            window.render_frame(cx);
            window.click("帮助", cx);
        })
        .unwrap();
        let base = cx.windows().len();
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            window.render_frame(cx);
            for label in [
                "提供 daro 反馈意见...",
                "检查更新...",
                "关于...",
            ] {
                assert!(
                    window.try_find_by_label(label).is_some(),
                    "帮助菜单缺「{label}」"
                );
            }
            // 框选删掉的 6 项确实不再上屏（外加旧写法「问题反馈」）
            for gone in [
                "帮助主题",
                "在线文档",
                "客户服务中心...",
                "注册...",
                "立即购买...",
                "新功能介绍",
                "问题反馈",
            ] {
                assert!(
                    window.try_find_by_label(gone).is_none(),
                    "「{gone}」已从帮助菜单移除，不该再出现"
                );
            }
            // 「关于...」是顶层第 5 项（0 基下标 4，含两条分隔线），在 popup-menu 作用域里按下标点
            window.within("popup-menu").click(4usize, cx);
            window.render_frame(cx);
        })
        .unwrap();
        let windows = cx.windows();
        assert_eq!(windows.len(), base + 1, "点「关于...」应弹出关于窗");
        let about = *windows.last().unwrap();
        cx.update_window(about, |_, window, cx| {
            window.render_frame(cx);
            assert!(
                window.try_find_by_label("问题反馈").is_some(),
                "关于窗里有反馈入口"
            );
            window.click("about-close", cx);
            window.render_frame(cx);
        })
        .unwrap();
        settle(cx, handle);
        assert_eq!(cx.windows().len(), base, "点「关闭」收回关于窗");
    }

    /// 「帮助 ▸ 检查更新...」不是死标签：开更新中心并立即开查。测试桩返回
    /// 无更新，界面落到「已是最新版本」，底栏留「检查更新」重查入口。
    #[gpui_kit::test]
    fn help_check_update_opens_update_center(cx: &mut TestAppContext) {
        isolate_store("helpcheckupdate");
        let (handle, _app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            window.click("title-menu", cx);
            window.render_frame(cx);
            window.click("帮助", cx);
            window.render_frame(cx);
            window.render_frame(cx);
            // 顶层第 3 项（0 基下标 2）：反馈 / 分隔线 / 检查更新
            window.within("popup-menu").click(2usize, cx);
            window.render_frame(cx);
        })
        .unwrap();
        let windows = cx.windows();
        assert_eq!(windows.len(), 2, "点「检查更新...」应弹出更新中心");
        let center = *windows.last().unwrap();
        // 开窗即自动查一次（测试里走不发网络的桩），结果带 id 落地
        settle(cx, center);
        cx.update_window(center, |_, window, cx| {
            window.render_frame(cx);
            assert!(
                window.try_find("update-check").is_some(),
                "桩返回无更新时应落到「已是最新版本」并给重查入口"
            );
            assert!(window.try_find("update-tab-log").is_some(), "更新日志标签在");
            window.click("update-close", cx);
            window.render_frame(cx);
        })
        .unwrap();
        settle(cx, handle);
        assert_eq!(cx.windows().len(), 1, "点「关闭」收回更新中心");
    }

