    /// PostgreSQL 视图设计器的「规则」子页：名称 / OID / 事件 / 代替运行 / 注释
    /// 五列表格 + 底部「位置 / 定义」属性区，工具条多出添加 / 删除规则两个钮，
    /// 子标签从两个变三个（对齐参考界面视图规则截图）。
    #[gpui_kit::test]
    fn view_rules_subtab_grid_and_props(cx: &mut TestAppContext) {
        isolate_store("viewrules");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.conns = vec![mock::Connection::new(
                    "视图规则测试",
                    DbKind::PostgreSql,
                    "localhost",
                    5432,
                    "postgres",
                    "u",
                    "p",
                    "",
                    false,
                )
                .as_demo()];
                a.groups.clear();
                a.sel = Act::Conn(0);
                a.open_new_designer(Act::Obj(0, 0, NO_SCHEMA, 1, 0), window, cx);
            });
            window.render_frame(cx);
            assert!(window.try_find("dsub/0").is_some(), "定义");
            assert!(window.try_find("dsub/1").is_some(), "规则");
            assert!(window.try_find("dsub/2").is_some(), "高级");
            assert!(window.try_find("dsub/3").is_some(), "注释");
            assert!(window.try_find("dsub/4").is_some(), "SQL 预览");
            assert!(window.try_find("dsub/5").is_none(), "只有五个子标签");

            window.click("dsub/1", cx);
            window.render_frame(cx);
            for col in 0..5 {
                assert!(
                    window.try_find(format!("vrule-cell/0/{col}")).is_some(),
                    "第 {col} 列格子"
                );
                assert!(
                    window.try_find(format!("vrule-resize/{col}")).is_some(),
                    "第 {col} 列列宽把手"
                );
            }
            assert!(window.try_find("vrule-add").is_some(), "工具条添加规则");
            assert!(window.try_find("vrule-del").is_some(), "工具条删除规则");
            assert!(window.try_find("drule-text/qual/0").is_some(), "位置行 …");
            assert!(window.try_find("drule-text/stmt/0").is_some(), "定义行 …");
            app.update(cx, |a, _| {
                let ds = a.opened.last().unwrap().dstate.as_ref().unwrap();
                assert_eq!(ds.rule_cur, 0, "当前格默认在名称列");
            });

            // 点「事件」格：当前格随点击走（截图里当前格整块实蓝）
            window.click("vrule-cell/0/2", cx);
            window.render_frame(cx);
            app.update(cx, |a, _| {
                let ds = a.opened.last().unwrap().dstate.as_ref().unwrap();
                assert_eq!(ds.sub, 1, "停在规则页");
                assert_eq!(ds.rule_cur, 2, "当前格在事件列");
                assert_eq!(ds.rules.len(), 1, "PG 视图播种一条空规则");
            });

            // 空白种子行还在 → 添行不叠第二行（末行永远留一格空白，表页同口径）
            window.click("vrule-add", cx);
            window.render_frame(cx);
            app.update(cx, |a, _| {
                assert_eq!(
                    a.opened
                        .last()
                        .unwrap()
                        .dstate
                        .as_ref()
                        .unwrap()
                        .rules
                        .len(),
                    1,
                    "末行是空白时不叠行"
                );
            });

            // 填上名字后添行 / 删行
            app.update(cx, |a, _| {
                a.opened.last_mut().unwrap().dstate.as_mut().unwrap().rules[0].name =
                    "r1".to_string();
            });
            window.click("vrule-add", cx);
            window.render_frame(cx);
            assert!(window.try_find("vrule-cell/1/0").is_some(), "第二行进格");
            window.click("vrule-cell/1/0", cx);
            window.render_frame(cx);
            window.click("vrule-del", cx);
            window.render_frame(cx);
            app.update(cx, |a, _| {
                let ds = a.opened.last().unwrap().dstate.as_ref().unwrap();
                assert_eq!(ds.rules.len(), 1, "删掉选中的那行");
                assert_eq!(ds.rules[0].name, "r1", "留下的是填过名字的行");
            });

            // 回 SQL 预览：规则页退场
            window.click("dsub/4", cx);
            window.render_frame(cx);
            assert!(window.try_find("dsql").is_some(), "SQL 预览在");
            assert!(window.try_find("vrule-cell/0/0").is_none(), "规则格退场");
        })
        .unwrap();
    }

