    /// PostgreSQL 视图设计器的「高级」子页：所有者（预填 postgres）/ 检查选项
    /// 下拉 / 安全屏障勾选三行，非 PG 视图没有这一页（参考界面视图高级截图口径）。
    #[gpui_kit::test]
    fn view_advanced_subtab_rows_and_sql(cx: &mut TestAppContext) {
        use gpui_kit::test::TestQueryExt as _;
        isolate_store("viewadv");
        let (handle, app) = open_app(cx);
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            app.update(cx, |a, cx| {
                a.conns = vec![mock::Connection::new(
                    "视图高级测试",
                    DbKind::PostgreSql,
                    "localhost",
                    5432,
                    "postgres",
                    "u",
                    "p",
                    "",
                    false,
                )
                .as_demo()];
                a.groups.clear();
                a.sel = Act::Conn(0);
                a.open_new_designer(Act::Obj(0, 0, NO_SCHEMA, 1, 0), window, cx);
            });
            window.render_frame(cx);
            assert!(window.try_find("dsub/2").is_some(), "高级子标签");
            window.click("dsub/2", cx);
            window.render_frame(cx);
            for id in ["vadv/owner", "vadv/check", "vadv/barrier"] {
                assert!(window.try_find(id).is_some(), "缺行 {id}");
            }
            for label in ["所有者:", "检查选项:", "安全屏障"] {
                assert!(window.try_find_by_label(label).is_some(), "缺「{label}」");
            }
            // 规则页的钮不在这一页
            assert!(window.try_find("vrule-cell/0/0").is_none(), "不出规则格");
            assert!(window.try_find("vrule-add").is_none(), "不出添加规则");
            // 所有者沿用表页那套编辑器，PG 连接预填 postgres
            app.update(cx, |a, _| {
                let ds = a.opened.last().unwrap().dstate.as_ref().unwrap();
                assert_eq!(ds.options.owner, "postgres", "属主预填");
                assert!(ds.opt_edits[0].is_some(), "所有者编辑器在");
                assert!(ds.view_check_option.is_empty(), "检查选项起始为空");
                assert!(!ds.view_security_barrier, "安全屏障起始不勾");
            });
        })
        .unwrap();

        // 勾上安全屏障 + 选 LOCAL：状态与「已修改」一起动
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, cx| {
                let did = a.opened.last().unwrap().did;
                a.design_set_view_security_barrier(did, true, cx);
                a.design_set_view_check_option(did, "LOCAL".to_string(), cx);
            });
            window.render_frame(cx);
            app.update(cx, |a, _| {
                let ds = a.opened.last().unwrap().dstate.as_ref().unwrap();
                assert!(ds.view_security_barrier, "安全屏障勾上");
                assert_eq!(ds.view_check_option, "LOCAL", "检查选项写回");
            });
        })
        .unwrap();

        // 高级页的开关最终走同一条预览链路：切到 SQL 预览仍能出正文（串本身见单元用例）
        cx.update_window(handle, |_, window, cx| {
            app.update(cx, |a, _| {
                a.opened.last_mut().unwrap().dstate.as_mut().unwrap().view_body =
                    "SELECT id FROM menus".to_string();
            });
            window.render_frame(cx);
            window.click("dsub/4", cx);
            window.render_frame(cx);
            assert!(window.try_find("dsql").is_some(), "SQL 预览在");
            assert!(window.try_find("vadv/owner").is_none(), "高级三行退场");
        })
        .unwrap();
    }

